INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('nature', 'humain', 'humain', 'Humain / Chasseur', NULL, '{"nature":"humain","description":"L’Humanité n’est pas extérieure à la Vérité. Un Humain peut rester totalement Profane, devenir Initié, rejoindre la Chasse, apprendre une tradition occulte ou martiale et utiliser des technologies qui dépassent la Réalité ordinaire. Il ne possède pas d’arbre racial : ce qu’il acquiert vient de sa formation, de ses alliances et de ce qu’il a réellement découvert.","carte":"> **HUMAIN CONSCIENT** · Nature · Gratuit\n>\n> **Humain conscient** : il connaît la Vérité, mais l''Hologramme peut encore corriger ses souvenirs. **+1 Volonté permanent** ; ni package racial, ni encyclopédie gratuite, ni détection de V.\n>\n> **Statut de Chasseur reconnu** (pas une Nature) : il agit durablement dans la Vérité et l''Hologramme le reconnaît. Les corrections civiles ordinaires n''effacent plus ce qu''il a réellement vu. Ce statut naît de la fiction ; il ne s''achète pas en PTV.\n>\n> **V / SR / R** : un Humain n''a pas de Vérité à Révéler et n''a pas d''états propres. Les mentions V, SR et R des voies sont celles du catalogue (voir question 1).\n>\n> **Limites** : aucune malédiction de Nature. Il reste humain : pas de vision de V, pas d''identification automatique, pas d''immunité aux pouvoirs qui altèrent explicitement l''esprit ou la mémoire.\n>\n> **Relation au Voile** : pas de jauge. Quand il neutralise une menace pour le Voile au profit d''un allié de Vérité, c''est la jauge de cet allié qui en profite.\n\n**Qui peut suivre ces voies** (décision du Builder, rappelée par la passation) : à la création, le parcours de Chasseur est **réservé aux Humains**. Certaines traditions s''ouvrent ensuite **en progression**, sur choix explicite, à d''autres Natures qui gardent leur propre carte : les **Lavandières** aux Vampires seulement, la **Chasse Fantastique** aux Exilés, les **Lueurs d''Azménor** aux Azménoriens, le **Xenoshield** aux Extrals qui l''ont infiltré sans qu''il le sache. Un Chasseur d''une autre Nature garde la jauge de Relation au Voile de sa Nature.\n\n*Correction du 30/10* : la première version présentait « Chasseur reconnu » comme une Nature et ne disait rien de la restriction de création. Corrigé.\n\nJamais achetés en PTV : Association des Chasseurs, habilitations GT, Hunt100 et Hunt15, Observers, Confrérie du Bestiaire, rangs de la Vénerie, ressources de l''Église, compagnons (Djinn, Shikigami, monture), armes de Merlin, reliques et prototypes.","traits_gratuits":[],"droits_acquis":"Les talents achetés avant les voies restent acquis ; les règles de voie valent pour les achats suivants (décision 20)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('couche', 'humain', 'humain_doctrine_commune', 'Doctrine commune', NULL, '{"nature":"humain","chemin":["Doctrine commune"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'humain', 'humain_doctrine_commune_doctrine_de_chasse', 'Doctrine de Chasse', NULL, '{"nature":"humain","forme":"une_porte","forme_lot":"1 porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"aucun. Signalé : la page « Traditions de Chasse » totalise 262 talents ; c''est sans les 4 de la Doctrine (266 au total). Elle dit aussi « treize traditions » : c''est juste, la Doctrine n''en est pas une."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'doctrine_commune_de_chasse_rompu_aux_horreurs', 'Rompu aux horreurs', NULL, '{"nature":"humain","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"V/SR/R, passif","activation":"Consigner les familles réellement identifiées et rencontrées, sans immunité à leurs pouvoirs.","texte_court":"une famille de créatures que tu as identifiée et réellement affrontée ne te cause plus de Stress par sa seule apparence ou Révélation. Ses actes et ses pouvoirs, si.","texte_reference":"V/SR/R — Passif. Après avoir correctement identifié une famille de créatures ou de phénomènes et en avoir réellement fait l’expérience, la simple apparence ou Révélation d’un autre représentant de cette famille ne provoque plus à elle seule de Stress. Les actes horrifiques, conséquences, attaques mentales ou pouvoirs terrifiants restent pleinement capables de provoquer du Stress.\nConditions de résolution : Consigner les familles réellement identifiées et rencontrées, sans immunité à leurs pouvoirs.","lore":"La première Révélation d’un monstre peut bouleverser une vie ; la dixième appartient au métier. Un Chasseur qui a véritablement affronté une famille de créatures cesse d’être choqué par sa seule apparence, sans devenir insensible à ce qu’elle fait réellement.","groupe_actuel":"Doctrine commune de Chasse","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'doctrine_commune_de_chasse_rompu_aux_horreurs_fenetre_de_chasse', 'Fenêtre de chasse', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"V/SR/R, réaction 1 PA, 1/round","activation":"Réaction 1 PA, 1/round ; une action simple incluse, limitée à son déplacement ou sa portée normale, sans attaque sauf exception écrite.","texte_court":"quand une proie identifiée et perçue déclenche une fuite (disparition, transformation, passage de seuil, extraction), tu agis avant : une action simple pour maintenir la chasse (te déplacer, fermer une porte, saisir, activer un dispositif). Ni attaque, ni annulation, ni suivi d''une téléportation déjà faite.","texte_reference":"V/SR/R — Réaction 1 PA — 1/round. Lorsqu’une proie identifiée et perçue déclenche une capacité directement destinée à rompre le contact ou à rendre la poursuite immédiatement impossible — disparition surnaturelle, transformation donnant une fuite, mouvement anormal, passage de seuil, dispositif d’extraction — le Chasseur agit avant sa résolution. Il peut effectuer une action simple directement destinée à maintenir la chasse : se déplacer vers la proie, franchir ou fermer une porte, saisir un élément atteignable, activer un dispositif préparé. Aucun tir ou attaque gratuite, aucune annulation automatique du pouvoir, aucun suivi après une téléportation déjà résolue.\nConditions de résolution : Réaction 1 PA, 1/round ; une action simple incluse, limitée à son déplacement ou sa portée normale, sans attaque sauf exception écrite.","lore":"La Doctrine commune apprend à reconnaître la seconde où une proie essaie de transformer l’affrontement en disparition. Cette Fenêtre permet un geste simple pour maintenir la chasse avant que l’échappatoire ne se referme, jamais une attaque ou un mouvement gratuit après coup.","groupe_actuel":"Doctrine commune de Chasse › Rompu aux horreurs","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'doctrine_commune_de_chasse_rompu_aux_horreurs_frapper_la_faiblesse', 'Frapper la faiblesse', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"V/SR/R, 1/scène, sans PA","activation":"2 PTV et 1/scène, sans PA ajouté à l’action offensive ; une seule Altération, sans DGT générique.","texte_court":"une action offensive réussie qui exploite une vulnérabilité réelle identifiée applique une Altération cohérente, même si la marge n''en donnait pas. Jamais une seconde Altération, jamais de dégâts en plus.","texte_reference":"V/SR/R — 1/Scène. Après avoir correctement identifié une vulnérabilité réelle et l’avoir effectivement exploitée par le moyen approprié, une action offensive réussie peut appliquer une Altération cohérente avec cette faiblesse même si sa marge n’en aurait normalement pas fourni. Si l’action accorde déjà une Altération, le Talent n’en crée pas automatiquement une seconde. Il ne crée jamais une vulnérabilité et n’augmente pas génériquement les dégâts.\nConditions de résolution : 1/scène, sans PA ajouté à l’action offensive ; une seule Altération, sans DGT générique.","lore":"Connaître une faiblesse n’a de valeur que lorsqu’on apporte réellement ce qui l’exploite. Une fois le moyen juste appliqué avec succès, le Chasseur sait convertir cette vulnérabilité en conséquence concrète plutôt qu’en simple note de dossier.","groupe_actuel":"Doctrine commune de Chasse › Rompu aux horreurs","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'doctrine_commune_de_chasse_rompu_aux_horreurs_mise_a_mort_preparee', 'Mise à mort préparée', NULL, '{"nature":"humain","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"V/SR/R, 2 PA","activation":"3 PTV et 2 PA ; exiger une incapacité totale de défense face à la méthode, pas une simple pénalité, Surprise ou mauvaise Défense.","texte_court":"sur une cible à 0 PV, inconsciente, totalement immobilisée ou sans défense, tu appliques une méthode durable que tu connais et possèdes. Elle tue ou maintient neutralisé ; ni régénération ni retour ordinaire pendant la scène. Ne contourne pas phylactère distant, clone, incarnation de remplacement ou résurrection divine.","texte_reference":"V/SR/R — 2 PA. Sur une cible à 0 PV ou moins, inconsciente, totalement immobilisée ou autrement incapable de se défendre efficacement, le Chasseur peut appliquer une méthode de neutralisation durable qu’il connaît réellement et dont il possède les moyens. Une méthode létale valide tue ; une méthode de neutralisation maintient la cible neutralisée. La régénération, la transformation corporelle ou le retour immédiat ordinaire ne la ramènent pas pendant la scène. Ne contourne pas résurrection divine, phylactère distant, clone externe, incarnation de remplacement ou mécanisme explicitement supérieur.\nConditions de résolution : 2 PA ; exiger une incapacité totale de défense face à la méthode, pas une simple pénalité, Surprise ou mauvaise Défense.","lore":"Les Chasseurs apprennent vite qu’abattre une créature ne signifie pas toujours qu’elle restera abattue. Sur une proie neutralisée, la Mise à mort préparée applique la méthode durable réellement connue — décapitation, scellement, destruction du corps ou autre solution adaptée — sans prétendre dépasser les résurrections extérieures à la scène.","groupe_actuel":"Doctrine commune de Chasse › Rompu aux horreurs","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('couche', 'humain', 'humain_lavandieres', 'Lavandières', NULL, '{"nature":"humain","chemin":["Lavandières"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'humain', 'humain_lavandieres_lavandieres', 'Lavandières', NULL, '{"nature":"humain","forme":"une_porte","forme_lot":"1 porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"bloc d''Accès sorti de Clouer au corps vers l''en-tête (correction). Saignée noire inchangée : c''est la décision du 30/09 (opposition et extinction d''un Sang), qui explique la crainte qu''inspirent les Lavandières."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'lavandieres_tradition_vampirique_de_chasse_lire_la_souillure', 'Lire la souillure', NULL, '{"nature":"humain","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, 1 PA","activation":"1 PTV et 1 PA sur un échantillon réellement accessible ; aucun changement de Cour/Sang/Nature détectable au-delà du texte.","texte_court":"sur un échantillon de sang accessible : Vampire, Moroï ou Strygoï ? Deux échantillons du même individu ? Son nom seulement si tu le connais. Ni Cour, ni Sang, ni Talents, ni âge, ni position.","texte_reference":"SR/R — 1 PA. En examinant un échantillon de sang, déterminer s’il provient d’un Vampire, d’un Moroï ou d’un Strygoï ; déterminer si deux échantillons proviennent du même individu ; identifier l’individu seulement s’il est personnellement connu. Ne révèle jamais Cour, Sang, Talents, nom, âge ou position.\nConditions de résolution : 1 PA sur un échantillon réellement accessible ; aucun changement de Cour/Sang/Nature détectable au-delà du texte.","lore":"Les Lavandières ont appris à lire le sang maudit comme d’autres lisent des empreintes. Un échantillon distingue Vampire, Moroï ou Strygoï et reconnaît un individu déjà connu, sans inventer dans une goutte sa Cour, son âge ou ses secrets.","groupe_actuel":"Lavandières — tradition vampirique de Chasse","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'lavandieres_tradition_vampirique_de_chasse_lire_la_souillure_sang_sous_le_masque', 'Sang sous le masque', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, passif, après Lire la souillure","activation":"À 10 m, avec sang frais directement perceptible ou nouvel échantillon, reconnaître la signature ; ni détection à travers tout obstacle ni pistage mondial.","texte_court":"à 10 m, avec du sang frais perceptible ou un nouvel échantillon, tu reconnais une signature déjà connue malgré déguisement, Visage volé, Mue ou changement d''état. Tu ne vois pas la forme de Vérité d''une cible Voilée.","texte_reference":"SR/R — Passif — Prérequis : Lire la souillure. Une signature sanguine déjà connue permet de reconnaître le même individu malgré déguisement, altération physique, passage V/SR/R, Visage volé, Mue ou autre changement de présentation. La Lavandière ne voit pas automatiquement la forme de Vérité d’une cible V.\nConditions de résolution : À 10 m, avec sang frais directement perceptible ou nouvel échantillon, reconnaître la signature ; ni détection à travers tout obstacle ni pistage mondial.","lore":"Une signature sanguine déjà mémorisée survit aux masques du Vampire. Corps emprunté, Mue ou Visage volé changent ce que l’œil reçoit ; la Lavandière reconnaît pourtant l’individu lorsqu’elle rencontre de nouveau ce sang-là.","groupe_actuel":"Lavandières — tradition vampirique de Chasse › Lire la souillure","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'lavandieres_tradition_vampirique_de_chasse_lire_la_souillure_saignee_noire', 'Saignée noire', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R, 1/round, sans PA","activation":"Voir la résolution détaillée","texte_court":"après une attaque de Pugilat ou de Mêlée qui blesse un Vampire, un Moroï ou un Strygoï, V + MS contre sa Défense occulte. Réussite : un de ses Sangs est éteint jusqu''à la fin de sa prochaine activation. Nature, états, Cour, talents communs et autres Sangs restent ; la Prédation blesse mais ne soigne plus.","texte_reference":"Une fois par round, après une attaque de Pugilat ou de Mêlée infligeant au moins 1 dégât réel à un Vampire, Moroï ou Strygoï, opposez Volonté + Maîtrise spirituelle à sa Défense occulte, sans PA supplémentaire. En cas de réussite, choisissez un de ses Sangs : ce Sang entier est éteint jusqu’à la fin de la prochaine activation de la cible. Tous ses talents, passifs gratuits et capacités directement alimentées par ce Sang sont suspendus. La Nature vampirique, les états SR/R, la Cour, les talents communs et les autres Sangs restent disponibles. La Prédation peut encore infliger des dégâts, mais ne soigne pas pendant cette extinction.","lore":"La Saignée noire vise ce qui circule derrière la puissance du Sang. Après une blessure réelle, l’héritage hématique de la cible se tait brièvement : ses Talents de Sang cessent de répondre sans que toute sa Nature vampirique disparaisse avec eux.","groupe_actuel":"Lavandières — tradition vampirique de Chasse › Lire la souillure","statut_regle":"correction","changements":"bloc d''Accès sorti de Clouer au corps vers l''en-tête (correction). Saignée noire inchangée : c''est la décision du 30/09 (opposition et extinction d''un Sang), qui explique la crainte qu''inspirent les Lavandières."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'lavandieres_tradition_vampirique_de_chasse_lire_la_souillure_clouer_au_corps', 'Clouer au corps', NULL, '{"nature":"humain","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, réaction 1 PA attaque comprise, 1/scène","activation":"Réaction 1 PA incluant l’attaque, 1/scène, à portée réelle de l’arme ; distinguer capacités corporelles de fuite et simple déplacement.","texte_court":"quand un Vampire à portée de ton arme déclenche une fuite qui soustrait son corps à la chasse, tu attaques avant. Blessure : l''activation échoue, ses PA et son usage sont perdus. Ne bloque ni la Stase ni Dernier sommeil.","texte_reference":"R — Réaction 1 PA — 1/Scène. Lorsqu’un Vampire atteignable déclenche une capacité de fuite qui retire son corps de la chasse, la Lavandière peut effectuer immédiatement une attaque avant sa résolution. Si l’attaque touche et inflige au moins 1 dégât réel, l’activation échoue ; ses PA et son usage limité sont consommés. Ne bloque ni Stase ni Dernier sommeil et n’est pas un contre-pouvoir générique. Accès : N pour une véritable Lavandière ; R pour un Vampire recruté ; X pour un non-Vampire.\nConditions de résolution : Réaction 1 PA incluant l’attaque, 1/scène, à portée réelle de l’arme ; distinguer capacités corporelles de fuite et simple déplacement.","lore":"Une Lavandière sait frapper le Vampire dans l’instant où il tente de retirer son corps de la chasse. Si le coup trouve réellement la chair, la fuite surnaturelle échoue avant de se résoudre, tandis que Stase et Dernier sommeil suivent leurs propres lois.","groupe_actuel":"Lavandières — tradition vampirique de Chasse › Lire la souillure","statut_regle":"correction","changements":"bloc d''Accès sorti de Clouer au corps vers l''en-tête (correction). Saignée noire inchangée : c''est la décision du 30/09 (opposition et extinction d''un Sang), qui explique la crainte qu''inspirent les Lavandières."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('couche', 'humain', 'humain_chasseurs_catholiques', 'Chasseurs catholiques', NULL, '{"nature":"humain","chemin":["Chasseurs catholiques"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'humain', 'humain_chasseurs_catholiques_liturgie_de_terrain', 'Liturgie de terrain', NULL, '{"nature":"humain","forme":"deux_portes","forme_lot":"2 portes","verrou":"ordre_paliers","portes":{"A":"Le sacré","B":"La fermeté"},"identite":null,"profil":null,"changements":"forme à deux portes (le sacré des lieux, la fermeté des âmes). En-tête de Signe de fermeté corrigé (réaction 1 PA). Note de développement retirée d''Intercession (« Conserver l''exception +3 et 2 PTV »)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'chasseurs_catholiques_liturgie_de_terrain_consecration_de_terrain', 'Consécration de terrain', NULL, '{"nature":"humain","cout":1,"cout_actuel":1,"palier":"I","porte":"A","palier_double":null,"acces":"SR/R, 1 minute ou 1 PA sous pression","activation":"1 minute hors pression ou 1 PA ; un objet tenu, 1 litre ou 1 m² au contact ; caractère Sacré pour la scène, sans arme ni munitions créées.","texte_court":"un objet tenu, 1 litre ou 1 m² au contact devient Sacré pour la scène ou pour le rite qui suit. Ne crée ni arme, ni dégâts, ni faiblesse ; une profanation active peut s''y opposer.","texte_reference":"SR/R — Rituel bref / 1 PA sous pression. Consacrer un objet, une petite surface, de l’eau, du sel ou un support approprié afin qu’il compte comme Sacré pour la scène ou pour le rite immédiatement associé. Ne crée ni dégâts ni faiblesse ; une profanation active peut s’y opposer.\nConditions de résolution : 1 minute hors pression ou 1 PA ; un objet tenu, 1 litre ou 1 m² au contact ; caractère Sacré pour la scène, sans arme ni munitions créées.","lore":"La liturgie de terrain fait d’un support ordinaire un objet momentanément tourné vers le sacré. Eau, sel, surface ou outil reçoit une consécration réelle, assez pour servir un rite ou une faiblesse qui exige précisément cette qualité.","groupe_actuel":"Chasseurs catholiques › Liturgie de terrain","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'chasseurs_catholiques_liturgie_de_terrain_sanctuaire_provisoire', 'Sanctuaire provisoire', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":"A","palier_double":null,"acces":"SR/R, 1 minute ou 2 PA sous pression","activation":"1 minute ou 2 PA, rayon 3 m autour d’un support consacré, scène ; un seul jet de création fixe la Puissance, première intrusion par round pour la zone entière.","texte_court":"rayon de 3 m autour d''un support consacré, pour la scène. La première intrusion extérieure par round (possession, malédiction, corruption, intrusion spirituelle) doit d''abord vaincre ton jet de V + MS, fixé au rite. N''arrête pas les coups physiques.","texte_reference":"SR/R — Rituel / 2 PA sous pression. Consacrer une petite zone pour la scène. La première intrusion extérieure par round cherchant à posséder, maudire, corrompre ou pénétrer spirituellement un occupant doit d’abord vaincre Volonté + Maîtrise spirituelle de l’officiant ; en réussite, la cible résiste ensuite normalement. Le sanctuaire n’arrête pas une attaque physique ordinaire.\nConditions de résolution : 1 minute ou 2 PA, rayon 3 m autour d’un support consacré, scène ; un seul jet de création fixe la Puissance, première intrusion par round pour la zone entière.","lore":"Quelques gestes et paroles suffisent parfois à transformer une petite zone en refuge spirituel. Les intrusions qui cherchent à posséder, maudire ou corrompre doivent d’abord franchir la protection du sanctuaire avant de s’en prendre aux personnes qu’il abrite.","groupe_actuel":"Chasseurs catholiques › Liturgie de terrain","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'chasseurs_catholiques_liturgie_de_terrain_restaurer_le_sacre', 'Restaurer le sacré', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":"A","palier_double":null,"acces":"SR/R, 1 PA au contact, ou 10 minutes pour une zone de 3 m","activation":"1 PA pour un support tenu au contact ; 10 minutes pour une zone de 3 m ; opposition à la profanation, pas de première consécration gratuite.","texte_court":"V + MS contre la Puissance d''une profanation active ; réussite, le support redevient Sacré. Ne consacre pas ce qui ne l''a jamais été.","texte_reference":"SR/R — Rituel / 1 PA. Sur une relique, un lieu, une eau ou un support précédemment consacré mais activement profané, Volonté + Maîtrise spirituelle contre la Puissance de la profanation. En réussite, le caractère Sacré est restauré. Ne consacre pas gratuitement un objet qui ne l’a jamais été.\nConditions de résolution : 1 PA pour un support tenu au contact ; 10 minutes pour une zone de 3 m ; opposition à la profanation, pas de première consécration gratuite.","lore":"Une profanation peut recouvrir un lieu consacré sans effacer son histoire. Le religieux travaille à dégager cette couche hostile et à rendre au support le caractère sacré qu’il possédait réellement auparavant.","groupe_actuel":"Chasseurs catholiques › Liturgie de terrain","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'chasseurs_catholiques_liturgie_de_terrain_signe_de_fermete', 'Signe de fermeté', NULL, '{"nature":"humain","cout":1,"cout_actuel":1,"palier":"I","porte":"B","palier_double":null,"acces":"SR/R, réaction 1 PA, 1/scène","activation":"Réaction 1 PA, 1/scène ; relancer seulement le d10e après échec non narratif, une relance de talent maximum.","texte_court":"après un échec non narratif à une résistance contre peur, terreur, désespoir ou compulsion surnaturelle, relance le d10e. Le second résultat est définitif.","texte_reference":"SR/R — 1/Scène. Après un échec non narratif à une résistance contre peur, terreur, désespoir ou compulsion surnaturelle, relancer le d10e ; le second résultat est définitif.\nConditions de résolution : Réaction 1 PA, 1/scène ; relancer seulement le d10e après échec non narratif, une relance de talent maximum.","lore":"Le Signe de fermeté rappelle au Chasseur la posture qu’il voulait tenir avant que la peur ou la compulsion ne le fasse vaciller. Une résistance manquée peut être reprise une fois, non parce que l’émotion disparaît, mais parce que la volonté se rassemble.","groupe_actuel":"Chasseurs catholiques › Liturgie de terrain","statut_regle":"correction","changements":"forme à deux portes (le sacré des lieux, la fermeté des âmes). En-tête de Signe de fermeté corrigé (réaction 1 PA). Note de développement retirée d''Intercession (« Conserver l''exception +3 et 2 PTV »)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'chasseurs_catholiques_liturgie_de_terrain_intercession', 'Intercession', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":"B","palier_double":null,"acces":"SR/R, réaction 1 PA, 1/round, 10 m","activation":"l’exception +3 et 2 PTV ; réaction 1 PA, allié à 10 m, 1/round ; aucune seconde Assistance sur ce test.","texte_court":"un allié résiste à un effet mental, spirituel ou de corruption ; tu pries, touches ou protèges. Il gagne +3 (Assistance surnaturelle, permise en combat). Une seule Assistance par test.","texte_reference":"SR/R — Réaction 1 PA. Le religieux peut fournir une Assistance surnaturelle à la résistance d’un allié proche contre un effet mental, spirituel ou de corruption, même en combat. Il doit pouvoir prier, toucher, protéger ou intervenir réellement ; l’allié reçoit +3 favorable.\nConditions de résolution : Conserver l’exception +3 et 2 PTV ; réaction 1 PA, allié à 10 m, 1/round ; aucune seconde Assistance sur ce test.","lore":"L’Intercession consiste à placer sa propre foi à côté de la volonté d’un autre. Prière, contact ou protection donne au compagnon une présence supplémentaire lorsqu’une force mentale ou spirituelle cherche à l’isoler.","groupe_actuel":"Chasseurs catholiques › Liturgie de terrain","statut_regle":"correction","changements":"forme à deux portes (le sacré des lieux, la fermeté des âmes). En-tête de Signe de fermeté corrigé (réaction 1 PA). Note de développement retirée d''Intercession (« Conserver l''exception +3 et 2 PTV »)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'chasseurs_catholiques_liturgie_de_terrain_derniers_rites', 'Derniers rites', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":"B","palier_double":null,"acces":"SR/R, rituel d''une minute au contact","activation":"1 minute au contact, mort depuis moins d’une heure ou mourant ; protection jusqu’à fin de scène, sans retenir une âme déjà partie ni remplacer une résurrection.","texte_court":"sur un mourant ou un mort depuis moins d''une heure, jusqu''à la fin de la scène, possession du cadavre, capture de l''âme ou réanimation spirituelle doivent vaincre ton V + MS. Ne ressuscite personne, ne retient pas une âme déjà partie.","texte_reference":"SR/R — Rituel. Sur un mourant ou un mort récent, fixer temporairement la continuité de l’âme. Jusqu’à la fin de la scène, une possession du cadavre, une capture opportuniste de l’âme ou une réanimation spirituelle immédiate doit vaincre Volonté + Maîtrise spirituelle de l’officiant. Ne ressuscite personne et ne bloque pas un mécanisme cosmologique explicitement supérieur.\nConditions de résolution : 1 minute au contact, mort depuis moins d’une heure ou mourant ; protection jusqu’à fin de scène, sans retenir une âme déjà partie ni remplacer une résurrection.","lore":"Les Derniers rites protègent l’instant fragile où l’âme vient de perdre son corps. La prière lui conserve une continuité et oppose une résistance à ceux qui voudraient profiter du cadavre ou capturer ce qui n’a pas encore rejoint sa destination.","groupe_actuel":"Chasseurs catholiques › Liturgie de terrain","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'humain', 'humain_chasseurs_catholiques_arianwen_escouade', 'Arianwen · Escouade', NULL, '{"nature":"humain","forme":"une_porte","forme_lot":"1 porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"aucun. Ressort déjà distinct de la Battue volante (Chasse Fantastique) : ici une proie identifiée par l''escouade ; là une proie marquée par un Limier."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'chasseurs_catholiques_ordre_darianwen_traque_chasse_en_escouade', 'Chasse en escouade', NULL, '{"nature":"humain","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"V/SR/R, 1 PA","activation":"1 PA et +2 à une attaque précise avec compétence 1+ et intervention réelle ; pas d’empilement.","texte_court":"Assistance +2 à l''attaque d''un allié, même en combat, si tu as la Compétence pertinente à 1+ et peux réellement intervenir. Une seule Assistance.","texte_reference":"V/SR/R — 1 PA. Fournir Assistance +2 en combat à l’attaque d’un allié si l’Arianwen possède la Compétence pertinente à 1+, peut réellement intervenir et dépense 1 PA. Une seule Assistance s’applique.\nConditions de résolution : 1 PA et +2 à une attaque précise avec compétence 1+ et intervention réelle ; pas d’empilement.","lore":"L’Ordre a appris à aider sous le feu sans devenir un second attaquant gratuit. Position, appel et geste utile donnent à l’allié l’assistance qu’exigerait normalement un instant plus calme.","groupe_actuel":"Chasseurs catholiques › Ordre d’Arianwen — Traque","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'chasseurs_catholiques_ordre_darianwen_traque_relais_de_chasse', 'Relais de chasse', NULL, '{"nature":"humain","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"V/SR/R, réaction 1 PA, 1/round","activation":"Seule l’Arianwen dépense le PA, l’allié cède sa Fenêtre ; aucune seconde réaction ni attaque.","texte_court":"quand un allié à 10 m pourrait utiliser Fenêtre de chasse, il te la cède. Tu paies le PA et fais l''action simple à ta portée ; lui ne paie rien. Ni seconde réaction ni attaque.","texte_reference":"Une fois par round, lorsqu’un allié à 10 m pourrait utiliser Fenêtre de chasse, il peut vous céder cette Fenêtre. Vous seul dépensez 1 PA en réaction pour accomplir son action simple à votre portée normale ; l’allié ne paie aucun PA. Cette substitution ne crée ni seconde réaction ni attaque.","lore":"L’escouade sait passer une occasion d’un Chasseur à l’autre. Quand un allié ouvre la Fenêtre de chasse, Arianwen peut prendre le relais et accomplir lui-même le geste nécessaire sans que le groupe gagne une action qui n’existait pas.","groupe_actuel":"Chasseurs catholiques › Ordre d’Arianwen — Traque","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'chasseurs_catholiques_ordre_darianwen_traque_couverture_croisee', 'Couverture croisée', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"V/SR/R, réaction 1 PA, 1/round","activation":"Réaction 1 PA, 1/round ; allié à 10 m, perçu et intervention plausible, +2 à une seule Défense active.","texte_court":"quand une proie identifiée attaque un allié à 10 m que tu peux aider, +2 à sa Défense active, malgré l''interdiction normale d''Assistance en combat.","texte_reference":"V/SR/R — Réaction 1 PA — 1/round. Lorsqu’une proie identifiée attaque un allié que l’Arianwen peut réellement aider, fournir Assistance +2 à sa Défense active malgré l’interdiction normale d’Assistance de combat. Intervention fictionnellement plausible requise.\nConditions de résolution : Réaction 1 PA, 1/round ; allié à 10 m, perçu et intervention plausible, +2 à une seule Défense active.","lore":"La couverture croisée transforme un second Chasseur en défense latérale. Lorsque la proie frappe un allié, Arianwen peut intervenir sur l’angle, le rythme ou la ligne d’attaque afin de rendre sa défense réellement plus solide.","groupe_actuel":"Chasseurs catholiques › Ordre d’Arianwen — Traque","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'chasseurs_catholiques_ordre_darianwen_traque_battue_sacree', 'Battue sacrée', NULL, '{"nature":"humain","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, passif","activation":"Deux positions distinctes à 20 m de la proie ; un seul surcoût +1, plafonné à 3 seulement si coût initial ≤3, jamais une réduction ni un cumul de battues.","texte_court":"deux membres de l''escouade perçoivent la même proie identifiée depuis deux positions distinctes à 20 m. Ses capacités de fuite immédiate coûtent +1 PA (maximum 3, sans cumul de battues).","texte_reference":"R — Passif. Si au moins deux membres coordonnés de l’escouade perçoivent la même proie correctement identifiée depuis des positions distinctes, les capacités surnaturelles directement destinées à quitter immédiatement la zone coûtent +1 PA, maximum 3.\nConditions de résolution : Deux positions distinctes à 20 m de la proie ; un seul surcoût +1, plafonné à 3 seulement si coût initial ≤3, jamais une réduction ni un cumul de battues.","lore":"Arianwen sait qu’une proie observée depuis plusieurs angles possède moins d’espace pour disparaître. Lorsque l’escouade la serre, même les fuites surnaturelles deviennent plus coûteuses comme si la chasse refermait ses lignes.","groupe_actuel":"Chasseurs catholiques › Ordre d’Arianwen — Traque","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'humain', 'humain_chasseurs_catholiques_arianwen_tenir_la_proie', 'Arianwen · Tenir la proie', NULL, '{"nature":"humain","forme":"une_porte","forme_lot":"1 porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"aucun."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'chasseurs_catholiques_ordre_darianwen_traque_tenir_le_monstre', 'Tenir le monstre', NULL, '{"nature":"humain","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"V/SR/R, réaction 1 PA, 1/round","activation":"Réaction 1 PA, 1/round ; suivre au maximum un Déplacement normal sur trajet praticable ; une saisie reste une action de Pugilat normale.","texte_court":"quand une proie au contact recule pour rompre le corps-à-corps, suis-la (un Déplacement au plus) ou saisis un appui pour rester au contact. Se dégager par la force reste un test de Pugilat normal.","texte_reference":"V/SR/R — Réaction 1 PA — 1/round. Lorsqu’une proie au contact se déplace volontairement pour rompre le corps-à-corps, l’Arianwen peut immédiatement se déplacer avec elle sur une courte distance valide ou saisir un élément du terrain permettant de maintenir le contact. Aucun test de Pugilat n’est remplacé si la proie tente réellement de se dégager par la force.\nConditions de résolution : Réaction 1 PA, 1/round ; suivre au maximum un Déplacement normal sur trajet praticable ; une saisie reste une action de Pugilat normale.","lore":"Arianwen refuse que la proie quitte simplement le contact après avoir été engagée. Il accompagne son mouvement, attrape ce qui peut l’être et reste dans sa trajectoire jusqu’à ce qu’elle se dégage vraiment par la force ou une autre méthode valable.","groupe_actuel":"Chasseurs catholiques › Ordre d’Arianwen — Traque","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'chasseurs_catholiques_ordre_darianwen_traque_briser_la_mue', 'Briser la mue', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R, réaction 1 PA attaque comprise, 1/scène","activation":"Réaction 1 PA incluant l’attaque, 1/scène ; blessure réelle puis opposition à la Puissance, sans état V/SR/R annulé implicitement.","texte_court":"quand une proie perçue commence une transformation corporelle, attaque avant. Blessure : V + MS contre la Puissance de la transformation ; réussite, elle échoue et son coût est perdu.","texte_reference":"R — Réaction 1 PA — 1/Scène. Lorsqu’une proie perçue commence une transformation surnaturelle corporelle, effectuer une attaque avant sa résolution. Si elle touche et inflige au moins 1 dégât réel, Volonté + Maîtrise spirituelle contre la Puissance de la transformation ; en réussite, cette transformation échoue et son coût est consommé.\nConditions de résolution : Réaction 1 PA incluant l’attaque, 1/scène ; blessure réelle puis opposition à la Puissance, sans état V/SR/R annulé implicitement.","lore":"Une transformation corporelle offre un instant où l’ancien corps n’est déjà plus stable et le nouveau pas encore installé. Arianwen frappe dans cette couture et peut faire avorter la Mue si la blessure atteint réellement la créature.","groupe_actuel":"Chasseurs catholiques › Ordre d’Arianwen — Traque","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'chasseurs_catholiques_ordre_darianwen_traque_clouer_la_proie', 'Clouer la proie', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R, 1/scène, sans PA","activation":"Sans PA supplémentaire, 1/scène après blessure ; un mode corporel identifié, +1 PA non cumulable, aucun coût initial supérieur à 3 ramené à 3.","texte_court":"après avoir blessé une proie identifiée, choisis un mode de fuite corporelle vu ou identifié. Il coûte +1 PA (maximum 3) jusqu''à la fin de sa prochaine activation.","texte_reference":"R — 1/Scène. Après une attaque réussie infligeant au moins 1 dégât réel à une proie identifiée, choisir un mode de fuite surnaturelle corporelle réellement vu ou correctement identifié. Jusqu’à la fin de la prochaine activation de la cible, ce mode coûte +1 PA, maximum 3.\nConditions de résolution : Sans PA supplémentaire, 1/scène après blessure ; un mode corporel identifié, +1 PA non cumulable, aucun coût initial supérieur à 3 ramené à 3.","lore":"Une plaie placée au bon moment peut rendre une méthode de fuite plus difficile à reprendre immédiatement. Arianwen choisit le mouvement surnaturel qu’il vient de voir et laisse la blessure perturber précisément cette échappatoire.","groupe_actuel":"Chasseurs catholiques › Ordre d’Arianwen — Traque","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'humain', 'humain_chasseurs_catholiques_arianwen_armes_consacrees', 'Arianwen · Armes consacrées', NULL, '{"nature":"humain","forme":"une_porte","forme_lot":"1 porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"Purification balistique clarifiée (« porter les Talents » devient « porter les effets attachables à l''attaque », repris de ses conditions). Ressort déjà distinct des autres armes de Vérité : ici le moyen Sacré, à distance comme au contact."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'chasseurs_catholiques_ordre_darianwen_traque_plaie_consacree', 'Plaie consacrée', NULL, '{"nature":"humain","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"R, passif","activation":"Noter les seuls PV réellement infligés, irrégénérables jusqu’à fin de prochaine activation, sans bloquer toute autre guérison.","texte_court":"une blessure infligée par un moyen réellement Sacré ne peut pas être régénérée surnaturellement jusqu''à la fin de la prochaine activation de la cible. Médecine et soins externes restent possibles.","texte_reference":"R — Passif. Une attaque avec un moyen réellement Sacré qui inflige au moins 1 dégât réel empêche la récupération de ces dégâts par régénération surnaturelle jusqu’à la fin de la prochaine activation de la cible. Les soins externes et médicaux restent possibles.\nConditions de résolution : Noter les seuls PV réellement infligés, irrégénérables jusqu’à fin de prochaine activation, sans bloquer toute autre guérison.","lore":"La blessure sacrée reste hostile à la régénération surnaturelle qui voudrait la refermer aussitôt. Pendant un bref moment, la créature doit vivre avec la plaie telle qu’elle a réellement été infligée.","groupe_actuel":"Chasseurs catholiques › Ordre d’Arianwen — Traque","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'chasseurs_catholiques_ordre_darianwen_traque_frapper_limmateriel', 'Frapper l''immatériel', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R, passif","activation":"Arme consacrée réellement possédée et attaque normale, aucune présence créée.","texte_court":"ton arme consacrée frappe une manifestation spirituelle ou un corps partiellement immatériel suffisamment présent. Pas une cible absente ou dans un autre plan.","texte_reference":"R — Passif. Une arme réellement consacrée peut interagir avec une manifestation spirituelle, un corps partiellement immatériel ou une présence surnaturelle suffisamment manifestée pour être atteinte. Elle ne frappe pas une cible absente ou dans un autre plan.\nConditions de résolution : Arme consacrée réellement possédée et attaque normale, aucune présence créée.","lore":"Une arme consacrée devient capable de rappeler à une présence spirituelle qu’elle participe encore à la scène. Si elle est suffisamment manifestée pour être atteinte, la lame ou le projectile trouve une prise là où une arme profane traverserait.","groupe_actuel":"Chasseurs catholiques › Ordre d’Arianwen — Traque","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'chasseurs_catholiques_ordre_darianwen_traque_purification_balistique', 'Purification balistique', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R, passif","activation":"Porter seulement les effets attachables à l’attaque ou à la munition ; suspension d’une Protection précise réellement vulnérable au sacré.","texte_court":"une munition Angélique ou Sacrée compte comme moyen divin contre une faiblesse réelle et porte jusqu''à l''impact tes effets attachables à l''attaque. Blessure : une Protection fondée sur la profanation ou l''impureté, réellement vulnérable au sacré, est suspendue jusqu''à la fin de la prochaine activation de la cible.","texte_reference":"R — Passif. Une munition Angélique ou un projectile réellement Sacré peut porter les Talents de l’Arianwen jusqu’à l’impact et compter comme moyen divin pour une faiblesse réelle. Sur un tir infligeant au moins 1 dégât réel, une Protection fondée explicitement sur profanation ou impureté peut être suspendue jusqu’à la fin de la prochaine activation de la cible si elle est réellement vulnérable au sacré.\nConditions de résolution : Porter seulement les effets attachables à l’attaque ou à la munition ; suspension d’une Protection précise réellement vulnérable au sacré.","lore":"Arianwen fait de la munition consacrée un vecteur de rite jusque dans l’impact. Une protection réellement fondée sur l’impureté peut y perdre sa cohérence, mais seulement si cette faiblesse fait effectivement partie de sa nature.","groupe_actuel":"Chasseurs catholiques › Ordre d’Arianwen — Traque","statut_regle":"correction","changements":"Purification balistique clarifiée (« porter les Talents » devient « porter les effets attachables à l''attaque », repris de ses conditions). Ressort déjà distinct des autres armes de Vérité : ici le moyen Sacré, à distance comme au contact."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'chasseurs_catholiques_ordre_darianwen_traque_salve_de_purification', 'Salve de purification', NULL, '{"nature":"humain","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, 2 PA, 1/scène","activation":"2 PA, 1/scène ; employer le gabarit et les dépenses de munitions du tir de suppression réel de l’arme, sans tirs additionnels.","texte_court":"tir de suppression consacré avec munitions Angéliques (gabarit et munitions de l''arme). Jusqu''au début du prochain round, les entités exposées ne peuvent ignorer la salve par une dissimulation, une phase ou une Protection fondée sur l''impureté.","texte_reference":"R — 2 PA — 1/Scène. Avec une arme à feu et des munitions Angéliques, effectuer un tir de zone/suppression consacrée sur une zone restreinte. Les entités spirituelles ou maudites exposées ne peuvent utiliser une dissimulation, phase ou Protection explicitement fondée sur l’impureté pour ignorer la salve jusqu’au début du prochain round. Les attaques et dégâts restent résolus normalement.\nConditions de résolution : 2 PA, 1/scène ; employer le gabarit et les dépenses de munitions du tir de suppression réel de l’arme, sans tirs additionnels.","lore":"La Salve de purification transforme des munitions angéliques en barrage de chasse. Dans la zone battue, les créatures maudites ou spirituelles ne peuvent compter aussi facilement sur une phase impure ou une dissimulation profane pour traverser le feu comme s’il n’existait pas.","groupe_actuel":"Chasseurs catholiques › Ordre d’Arianwen — Traque","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'chasseurs_catholiques_ordre_darianwen_traque_tueur_de_limpossible', 'Tueur de l''impossible', NULL, '{"nature":"humain","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, après Mise à mort préparée","activation":"Voir la résolution détaillée","texte_court":"lors d''une Mise à mort préparée après neutralisation sacrée, tu scelles un support consacré dans le corps. Tant qu''il reste en place et consacré, la cible ne peut revenir par ce corps ou son ancrage local. Aucun PA en plus.","texte_reference":"Lors d’une Mise à mort préparée après neutralisation sacrée, placez ou scellez un support consacré réel dans le corps. Tant qu’il reste en place et consacré, la cible ne peut revenir par ce corps ou son ancrage local. L’extraction ou la profanation du support lève le verrou. Les réceptacles distants restent intacts. Aucun PA ne s’ajoute aux 2 PA de Mise à mort préparée.","lore":"La mise à mort d’Arianwen devient définitive lorsqu’elle emploie précisément le sacré auquel le monstre est vulnérable. Ce Talent ne dépasse pas un phylactère ou une résurrection divine ; il empêche la créature de tricher avec sa propre régénération locale.","groupe_actuel":"Chasseurs catholiques › Ordre d’Arianwen — Traque","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'humain', 'humain_chasseurs_catholiques_ephraim_discernement', 'Ephraïm · Discernement', NULL, '{"nature":"humain","forme":"une_porte","forme_lot":"1 porte (courte)","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"**ressort propre ajouté** à Présence étrangère : la prière se fait à voix haute et l''occupant se sait repéré. Avant, le texte était identique mot pour mot à Présence parasite (Onmyoji)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'chasseurs_catholiques_ordre_dephraim_exorcistat_presence_etrangere', 'Présence étrangère', NULL, '{"nature":"humain","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, 1 PA, 10 m","activation":"1 PA, cible à 10 m perçue ; Esprit + Perception contre Puissance de dissimulation si nécessaire ; présence étrangère seulement.","texte_court":"par une prière à voix haute, tu sais si une présence spirituelle étrangère (possession, parasite) est attachée à une personne ou un objet. Une présence cachée oppose sa Puissance à ton Esprit + Perception. L''occupant détecté sait qu''il a été vu. Ne détecte pas une Nature.","texte_reference":"SR/R — 1 PA. Examiner une personne ou un objet et déterminer si une présence spirituelle étrangère, possession ou parasite distinct est actuellement attaché. Une présence activement cachée peut s’y opposer. Ne détecte pas une Nature intrinsèque.\nConditions de résolution : 1 PA, cible à 10 m perçue ; Esprit + Perception contre Puissance de dissimulation si nécessaire ; présence étrangère seulement.","lore":"Ephraïm sait distinguer une présence ajoutée d’une Nature intrinsèque. Une possession, un parasite ou un esprit lié apparaît comme quelque chose qui est venu se fixer là, et non comme ce que la cible est depuis toujours.","groupe_actuel":"Chasseurs catholiques › Ordre d’Ephraïm — Exorcistat","statut_regle":"correction","changements":"**ressort propre ajouté** à Présence étrangère : la prière se fait à voix haute et l''occupant se sait repéré. Avant, le texte était identique mot pour mot à Présence parasite (Onmyoji)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'chasseurs_catholiques_ordre_dephraim_exorcistat_lire_lancrage', 'Lire l''ancrage', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, 1 PA, 10 m","activation":"1 PA à 10 m ; lire l’ancrage principal identifié, opposition à sa dissimulation éventuelle ; ni mode de destruction ni ancrages secondaires automatiques.","texte_court":"sur une possession ou un lien identifié, tu perçois son ancrage principal (corps, objet, serment, lieu, marque, nom, relation). Ni la manière de le détruire, ni les ancrages secondaires.","texte_reference":"SR/R — 1 PA. Sur une possession ou un lien spirituel identifié, percevoir ce qui sert actuellement d’ancrage principal : corps, objet, serment, lieu, marque, nom, relation ou autre structure réelle. Ne révèle pas automatiquement comment le détruire.\nConditions de résolution : 1 PA à 10 m ; lire l’ancrage principal identifié, opposition à sa dissimulation éventuelle ; ni mode de destruction ni ancrages secondaires automatiques.","lore":"Une possession tient toujours par quelque chose. Ephraïm cherche ce point principal — corps, objet, nom, relation, serment ou lieu — et le rend intelligible avant de choisir comment le combattre.","groupe_actuel":"Chasseurs catholiques › Ordre d’Ephraïm — Exorcistat","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'humain', 'humain_chasseurs_catholiques_ephraim_seuils', 'Ephraïm · Seuils', NULL, '{"nature":"humain","forme":"une_porte","forme_lot":"1 porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"note de développement retirée du Cercle (« garder 2 PTV »). Ressort déjà distinct du Sceau de Fermeture (Onmyoji) : Fermer le seuil est une consécration immédiate, sans préparation ni support."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'chasseurs_catholiques_ordre_dephraim_exorcistat_ligne_de_sel', 'Ligne de sel', NULL, '{"nature":"humain","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, 1 PA au contact, scène","activation":"1 PA pour 2 m de ligne au contact avec support, durée scène ; Puissance fixée au tracé, une tentative par franchissement, rupture matérielle possible.","texte_court":"avec un support rituel, trace 2 m de ligne. Une entité spirituelle, immatérielle ou possessive qui veut la franchir surnaturellement doit vaincre ton V + MS, fixé au tracé. Une rupture matérielle la brise ; elle n''arrête pas une personne matérielle.","texte_reference":"SR/R — Préparation / 1 PA. Avec un support rituel approprié, tracer une courte limite. Une entité spirituelle, immatérielle ou possessive qui veut la franchir surnaturellement doit vaincre Volonté + Maîtrise spirituelle de l’exorciste. La ligne peut être brisée physiquement et n’arrête pas une personne matérielle.\nConditions de résolution : 1 PA pour 2 m de ligne au contact avec support, durée scène ; Puissance fixée au tracé, une tentative par franchissement, rupture matérielle possible.","lore":"Une Ligne de sel est moins un mur qu’une déclaration de frontière. Ce qui veut la franchir sous forme spirituelle doit imposer sa volonté au rite, tandis qu’un pied matériel ou un coup de balai peut toujours rompre le tracé.","groupe_actuel":"Chasseurs catholiques › Ordre d’Ephraïm — Exorcistat","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'chasseurs_catholiques_ordre_dephraim_exorcistat_cercle_dephraim', 'Cercle d''Ephraïm', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, rituel de 10 minutes, après Ligne de sel","activation":"10 minutes, rayon 3 m, jusqu’à rupture ou fin de scène ; garder 2 PTV et l’opposition au franchissement.","texte_court":"ta ligne se ferme en cercle de 3 m de rayon jusqu''à rupture ou fin de scène. Sortir ou entrer surnaturellement exige de vaincre l''opposition. Une rupture matérielle le brise.","texte_reference":"SR/R — Rituel. Fermer une Ligne de sel en enceinte stable. Une entité contenue doit vaincre l’opposition pour sortir surnaturellement ; une entité extérieure doit la vaincre pour entrer spirituellement. Le cercle reste vulnérable à une rupture matérielle réelle.\nConditions de résolution : 10 minutes, rayon 3 m, jusqu’à rupture ou fin de scène ; garder 2 PTV et l’opposition au franchissement.","lore":"Le Cercle d’Ephraïm transforme une ligne rituelle en véritable enceinte spirituelle. L’entité peut toujours chercher une sortie, mais elle doit vaincre la frontière consacrée ou faire briser matériellement ce qui la dessine.","groupe_actuel":"Chasseurs catholiques › Ordre d’Ephraïm — Exorcistat","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'chasseurs_catholiques_ordre_dephraim_exorcistat_fermer_le_seuil', 'Fermer le seuil', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, 1 PA au contact, scène","activation":"1 PA au contact, une ouverture de 3 m maximum pour la scène ; même opposition spirituelle, aucune fermeture physique automatique.","texte_court":"consacre un passage précis (porte, fenêtre, brèche, portail matériel) de 3 m au plus. Possessions, intrusions spirituelles et passages immatériels doivent vaincre ton V + MS. Une créature matérielle peut encore l''ouvrir ou le détruire.","texte_reference":"SR/R — 1 PA. Consacrer temporairement un passage précis — porte, fenêtre, brèche, portail matériel — pour la scène. Les possessions, intrusions spirituelles et passages immatériels doivent vaincre Volonté + Maîtrise spirituelle pour le franchir. Une créature matérielle peut encore ouvrir ou détruire le passage.\nConditions de résolution : 1 PA au contact, une ouverture de 3 m maximum pour la scène ; même opposition spirituelle, aucune fermeture physique automatique.","lore":"Ephraïm consacre un passage réel afin qu’il cesse d’être une porte facile pour les intrusions de l’esprit. Possession et immatérialité doivent lutter contre le rite, tandis qu’un être matériel reste parfaitement capable d’ouvrir la porte ou de l’abattre.","groupe_actuel":"Chasseurs catholiques › Ordre d’Ephraïm — Exorcistat","statut_regle":"correction","changements":"note de développement retirée du Cercle (« garder 2 PTV »). Ressort déjà distinct du Sceau de Fermeture (Onmyoji) : Fermer le seuil est une consécration immédiate, sans préparation ni support."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'chasseurs_catholiques_ordre_dephraim_exorcistat_chambre_blanche', 'Chambre blanche', NULL, '{"nature":"humain","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, rituel d''une heure, 24 heures","activation":"1 heure, une pièce de 5 m de rayon maximum, durée 24 h puis renouvellement rituel ; ancrages matériels intacts, autres pouvoirs disponibles.","texte_court":"une pièce de 5 m de rayon au plus. Tant que ses limites restent intactes, une entité étrangère à l''hôte ne peut se téléporter spirituellement, posséder une nouvelle cible ou se projeter hors du corps sans vaincre ton V + MS. Ses autres pouvoirs restent.","texte_reference":"R — Rituel prolongé. Préparer une pièce ou petite cellule d’exorcisme. Tant que ses limites restent intactes, les entités étrangères à l’hôte ne peuvent utiliser téléportation spirituelle, possession d’une nouvelle cible ou projection hors du corps sans vaincre Volonté + Maîtrise spirituelle. La Chambre ne neutralise pas leurs autres pouvoirs.\nConditions de résolution : 1 heure, une pièce de 5 m de rayon maximum, durée 24 h puis renouvellement rituel ; ancrages matériels intacts, autres pouvoirs disponibles.","lore":"La Chambre blanche est un lieu préparé pour que l’occupant ne puisse pas simplement changer d’hôte ou s’échapper hors du corps. Les murs restent matériels, mais le rite ajoute autour d’eux une géométrie pensée pour l’exorcisme prolongé.","groupe_actuel":"Chasseurs catholiques › Ordre d’Ephraïm — Exorcistat","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'humain', 'humain_chasseurs_catholiques_ephraim_exorcisme', 'Ephraïm · Exorcisme', NULL, '{"nature":"humain","forme":"une_porte","forme_lot":"1 porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"aucun. Ressort déjà distinct de l''Extraction par le Sceau (Onmyoji) : Ephraïm expulse par la prière en un temps ; l''Onmyoji doit d''abord faire comparaître, puis sceller."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'chasseurs_catholiques_ordre_dephraim_exorcistat_faire_parler_loccupant', 'Faire parler l''occupant', NULL, '{"nature":"humain","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, 1 PA, 10 m","activation":"1 PA à 10 m sur hôte perçu ; Volonté + Maîtrise spirituelle contre Défense occulte, jusqu’à fin du prochain round.","texte_court":"sur un hôte dont la présence étrangère est établie, V + MS contre la Défense occulte de l''entité. Réussite : elle se manifeste assez pour entendre et répondre jusqu''à la fin du prochain round. Elle peut mentir ; elle n''est pas expulsée.","texte_reference":"SR/R — 1 PA. Sur un hôte dont une présence étrangère a été établie, Volonté + Maîtrise spirituelle contre la Défense occulte de l’entité. En réussite, elle doit se manifester suffisamment pour pouvoir entendre et répondre jusqu’à la fin du prochain round. Elle n’est pas forcée de dire vrai et n’est pas expulsée.\nConditions de résolution : 1 PA à 10 m sur hôte perçu ; Volonté + Maîtrise spirituelle contre Défense occulte, jusqu’à fin du prochain round.","lore":"Une présence cachée dans un hôte peut être forcée à venir jusqu’à la surface. Elle devient assez manifeste pour entendre et répondre, même si l’Exorciste n’obtient ni vérité ni coopération par ce seul dévoilement.","groupe_actuel":"Chasseurs catholiques › Ordre d’Ephraïm — Exorcistat","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'chasseurs_catholiques_ordre_dephraim_exorcistat_distinguer_lhote', 'Distinguer l''hôte', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, passif","activation":"Exiger une identification réelle de l’occupant, ne convertir aucune balle ou attaque physique ordinaire en exorcisme.","texte_court":"une fois l''occupant identifié, tes exorcismes et effets spirituels le visent sans traiter le corps de l''hôte comme la cible. Une attaque physique reste physique.","texte_reference":"SR/R — Passif. Une fois l’entité et l’hôte distingués, les exorcismes et effets spirituels d’Ephraïm peuvent cibler l’occupant sans traiter automatiquement le corps de l’hôte comme la cible. Les attaques physiques restent physiques.\nConditions de résolution : Exiger une identification réelle de l’occupant, ne convertir aucune balle ou attaque physique ordinaire en exorcisme.","lore":"Ephraïm apprend à ne pas confondre la personne possédée avec ce qui l’habite. Une fois cette distinction faite, les rites peuvent viser l’occupant spirituel sans faire de l’hôte innocent la cible par défaut.","groupe_actuel":"Chasseurs catholiques › Ordre d’Ephraïm — Exorcistat","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'chasseurs_catholiques_ordre_dephraim_exorcistat_priere_de_bannissement', 'Prière de bannissement', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, 1 PA, 10 m","activation":"1 PA, cible manifestée à 10 m ; opposition occulte, recul de 3 m vers un espace valide ; interdiction courte du même hôte inchangée.","texte_court":"sur une présence manifestée ou rendue ciblable, V + MS contre Défense occulte. Réussite : elle recule de 3 m et ne peut reprendre le même hôte avant la fin de sa prochaine activation.","texte_reference":"SR/R — 1 PA. Sur une présence manifestée ou rendue ciblable, Volonté + Maîtrise spirituelle contre Défense occulte. En réussite, elle est repoussée hors du contact immédiat et ne peut reprendre possession du même hôte avant la fin de sa prochaine activation.\nConditions de résolution : 1 PA, cible manifestée à 10 m ; opposition occulte, recul de 3 m vers un espace valide ; interdiction courte du même hôte inchangée.","lore":"La Prière de bannissement ne détruit pas l’entité : elle l’arrache au contact immédiat et lui ferme brièvement l’hôte dont elle vient d’être repoussée. Le combat spirituel continue ensuite sur un terrain moins favorable à l’occupant.","groupe_actuel":"Chasseurs catholiques › Ordre d’Ephraïm — Exorcistat","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'chasseurs_catholiques_ordre_dephraim_exorcistat_purge', 'Purge', NULL, '{"nature":"humain","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, 2 PA, 1/scène, au contact","activation":"2 PA, 1/scène, hôte au contact ; Volonté + Maîtrise spirituelle contre Défense occulte de l’occupant ; expulsion, pas destruction.","texte_court":"sur un hôte vivant portant une présence étrangère identifiée, V + MS contre la Défense occulte de l''occupant. Réussite : la possession est rompue et l''occupant expulsé, pas détruit.","texte_reference":"R — 2 PA — 1/Scène. Sur un hôte vivant portant une présence étrangère identifiée, Volonté + Maîtrise spirituelle contre l’entité. En réussite, la possession est rompue et l’occupant expulsé. L’entité reste présente dans le monde ou à proximité selon sa Nature ; elle n’est pas détruite.\nConditions de résolution : 2 PA, 1/scène, hôte au contact ; Volonté + Maîtrise spirituelle contre Défense occulte de l’occupant ; expulsion, pas destruction.","lore":"La Purge est le moment où l’Exorciste cesse de diagnostiquer et expulse réellement l’occupant. L’hôte est libéré si la volonté d’Ephraïm l’emporte, mais l’entité ainsi chassée continue d’exister quelque part dans la scène ou son environnement.","groupe_actuel":"Chasseurs catholiques › Ordre d’Ephraïm — Exorcistat","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'chasseurs_catholiques_ordre_dephraim_exorcistat_renvoi', 'Renvoi', NULL, '{"nature":"humain","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, 2 PA, 1/scène, 10 m","activation":"2 PA, 1/scène, entité à 10 m ; nommer le domaine accessible avant le jet, aucune destination inventée après réussite.","texte_court":"sur une entité expulsée, manifestée ou contenue, nomme son domaine d''origine accessible avant le jet, puis V + MS contre sa Défense occulte. Réussite : elle y est renvoyée. Sans effet sur une créature qui est chez elle dans ce monde.","texte_reference":"R — 2 PA — 1/Scène. Sur une entité expulsée, manifestée ou contenue dont le plan/refuge d’origine est réellement accessible, Volonté + Maîtrise spirituelle contre sa Défense occulte. En réussite, elle est renvoyée vers cet état ou domaine. Ne fonctionne pas sur une créature dont le monde actuel est réellement le sien.\nConditions de résolution : 2 PA, 1/scène, entité à 10 m ; nommer le domaine accessible avant le jet, aucune destination inventée après réussite.","lore":"Une entité déjà expulsée ou contenue peut être poussée vers le domaine auquel elle appartient véritablement. Le Renvoi exige qu’un tel refuge existe encore et qu’il soit accessible ; il ne bannit pas arbitrairement une créature de son propre monde.","groupe_actuel":"Chasseurs catholiques › Ordre d’Ephraïm — Exorcistat","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'chasseurs_catholiques_ordre_dephraim_exorcistat_grand_exorcisme', 'Grand exorcisme', NULL, '{"nature":"humain","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, rituel d''une heure au moins","activation":"Minimum 1 heure ; fiche rituelle précisant ancrage, participants, conditions et Puissance avant le rite ; même opposition, exigences majeures narratives, aucun succès automatique.","texte_court":"contre une possession majeure, une entité très puissante ou une contamination enracinée. Avant le rite, la fiche rituelle fixe ancrage, participants, conditions et Puissance ; puis même opposition. Réussite : la possession est rompue durablement ou la présence majeure renvoyée. Ne détruit pas une Nature.","texte_reference":"R — Rituel prolongé. Sur une possession majeure, une entité très puissante ou une contamination spirituelle enracinée, conduire un exorcisme collectif dépassant les limites de Purge. Le rite exige identification, ancrage, temps, supports et parfois assistants ou conditions de scénario ; en réussite il peut rompre durablement une possession ou renvoyer une présence majeure. Ne détruit pas une Nature fondamentale.\nConditions de résolution : Minimum 1 heure ; fiche rituelle précisant ancrage, participants, conditions et Puissance avant le rite ; même opposition, exigences majeures narratives, aucun succès automatique.","lore":"Le Grand exorcisme est réservé aux présences qui ont eu le temps de s’enraciner. Noms, ancrages, assistants et supports deviennent les pièces d’un travail collectif capable de défaire durablement une possession majeure sans abolir la Nature profonde de l’être.","groupe_actuel":"Chasseurs catholiques › Ordre d’Ephraïm — Exorcistat","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'humain', 'humain_chasseurs_catholiques_magdalena_enquete', 'Magdalena · Enquête', NULL, '{"nature":"humain","forme":"une_porte","forme_lot":"1 porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"note de développement retirée de Lire la marque (« conserver le coût de 2 PTV »)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'chasseurs_catholiques_ordre_de_magdalena_jugement_pesee_de_lame', 'Pesée de l''âme', NULL, '{"nature":"humain","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, 1 PA, 10 m","activation":"1 PA à 10 m ; influence extérieure active seulement, test de détection contre dissimulation éventuelle, aucune lecture morale.","texte_court":"face à une altération surnaturelle soupçonnée, tu sais si l''âme de la cible porte une influence extérieure active. Jamais une lecture morale (« est-ce quelqu''un de mauvais ? »).","texte_reference":"SR/R — 1 PA. Face à une altération surnaturelle précise soupçonnée, déterminer si l’âme de la cible porte actuellement une influence extérieure active. Ne répond jamais à « est-ce une mauvaise personne ? » et ne constitue pas une lecture morale universelle.\nConditions de résolution : 1 PA à 10 m ; influence extérieure active seulement, test de détection contre dissimulation éventuelle, aucune lecture morale.","lore":"La Pesée de l’âme n’est pas une balance morale. Elle cherche seulement à savoir si quelque chose d’extérieur travaille actuellement dans l’âme examinée, distinction essentielle entre corruption active et personne simplement coupable ou désagréable.","groupe_actuel":"Chasseurs catholiques › Ordre de Magdalena — Jugement","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'chasseurs_catholiques_ordre_de_magdalena_jugement_main_de_linquisiteur', 'Main de l''Inquisiteur', NULL, '{"nature":"humain","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, passif","activation":"Manipuler réellement le support, sans transférer cette protection à toute la scène ou aux alliés.","texte_court":"tu peux saisir et manipuler un objet porteur d''une influence spirituelle dangereuse sans que le simple contact la déclenche contre toi. Un effet actif hostile peut toujours t''attaquer. Pour toi seul.","texte_reference":"SR/R — Passif. Le personnage peut saisir, déplacer et manipuler directement un objet ou support porteur d’une influence spirituelle dangereuse sans que le simple contact suffise à déclencher automatiquement cette influence contre lui ; un effet actif hostile peut toujours l’attaquer normalement.\nConditions de résolution : Manipuler réellement le support, sans transférer cette protection à toute la scène ou aux alliés.","lore":"L’Inquisiteur sait toucher ce que d’autres craindraient d’effleurer. Un support spirituellement dangereux peut être saisi et déplacé sans que le simple contact déclenche automatiquement son piège, même si une attaque active reste capable de répondre.","groupe_actuel":"Chasseurs catholiques › Ordre de Magdalena — Jugement","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'chasseurs_catholiques_ordre_de_magdalena_jugement_lire_la_marque', 'Lire la marque', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, 1 PA, 10 m","activation":"1 PA à 10 m sur marque perçue ; opposition au masquage si présent ; conserver le coût de 2 PTV et l’absence de clauses révélées.","texte_court":"sur une marque, bénédiction, pacte, sceau ou corruption déjà détectés, tu perçois sa fonction générale (contraindre, nourrir, protéger, appeler, surveiller, transformer). Ni ses clauses, ni son auteur.","texte_reference":"SR/R — 1 PA. Sur une marque, bénédiction, pacte, sceau ou corruption active déjà détectée, percevoir sa fonction générale : contraindre, nourrir, protéger, appeler, surveiller, transformer, etc. Ne révèle pas automatiquement toutes ses clauses ni son auteur.\nConditions de résolution : 1 PA à 10 m sur marque perçue ; opposition au masquage si présent ; conserver le coût de 2 PTV et l’absence de clauses révélées.","lore":"Une marque active possède une fonction même lorsqu’elle cache son auteur. Magdalena apprend à distinguer si elle nourrit, protège, surveille, transforme ou contraint, premier diagnostic avant tout acte d’Inquisition.","groupe_actuel":"Chasseurs catholiques › Ordre de Magdalena — Jugement","statut_regle":"correction","changements":"note de développement retirée de Lire la marque (« conserver le coût de 2 PTV »)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'chasseurs_catholiques_ordre_de_magdalena_jugement_suivre_la_chaine', 'Suivre la chaîne', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, 1 PA, scène","activation":"1 PA, direction pendant la scène si autre extrémité à 10 km maximum ET même plan ; anti-divination conserve son opposition.","texte_court":"sur une marque ou un lien actif, tu sens la direction de l''autre extrémité, si elle est à 10 km au plus et dans le même plan. Ni distance ni adresse ; un anti-divination s''y oppose.","texte_reference":"SR/R — 1 PA. Sur une marque ou lien actif, percevoir la direction générale de l’autre extrémité tant qu’elle se trouve dans la même région ou le même plan et qu’aucun dispositif anti-divination ne l’isole. Pas de GPS ni d’adresse.\nConditions de résolution : 1 PA, direction pendant la scène si autre extrémité à 10 km maximum ET même plan ; anti-divination conserve son opposition.","lore":"Un lien surnaturel actif indique aussi qu’il existe une autre extrémité. Magdalena peut sentir dans quelle direction générale court cette chaîne tant qu’elle reste dans le même monde et qu’aucune protection spécialisée ne la coupe.","groupe_actuel":"Chasseurs catholiques › Ordre de Magdalena — Jugement","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'humain', 'humain_chasseurs_catholiques_magdalena_jugement', 'Magdalena · Jugement', NULL, '{"nature":"humain","forme":"une_porte","forme_lot":"1 porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"note de développement retirée de Briser le pacte (« garder 3 PTV »). Ressort déjà distinct de Briser le pacte contraint (Khālsā) : Magdalena juge sur pièces et doit connaître les clauses ; le Khālsā tranche avec l''Arme du Serment, victime présente, sans connaître les clauses."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'chasseurs_catholiques_ordre_de_magdalena_jugement_jugement', 'Jugement', NULL, '{"nature":"humain","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, 1 PA, 10 m, 1/scène","activation":"1 PA à 10 m, 1/scène ; +3 au prochain rite de Magdalena contre cette source avant fin du prochain round, sans fabriquer culpabilité ni faiblesse.","texte_court":"désigne une source surnaturelle identifiée. +3 à ton prochain rite de Magdalena contre elle avant la fin du prochain round. Ne crée ni culpabilité ni faiblesse.","texte_reference":"Pour 1 PA à 10 m, une fois par scène, désignez une source surnaturelle réellement identifiée. Vous gagnez +3 au prochain rite de Magdalena dirigé contre cette source avant la fin du prochain round. Ce jugement ne crée ni culpabilité ni faiblesse.","lore":"Le Jugement de Magdalena commence par établir de quoi vient réellement le préjudice. Une fois la source nommée — marque, pacte, objet ou influence — tous les gestes de l’Ordre peuvent se concentrer sur elle sans confondre soupçon et culpabilité.","groupe_actuel":"Chasseurs catholiques › Ordre de Magdalena — Jugement","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'chasseurs_catholiques_ordre_de_magdalena_jugement_mise_sous_scelles', 'Mise sous scellés', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, 1 PA au contact, scène","activation":"1 PA au contact pour la scène ; nommer une propriété identifiée, jet de création comme Puissance ; chaque activation affronte le sceau une seule fois.","texte_court":"sur un objet ou support surnaturel, nomme une propriété identifiée. Chaque activation de cette propriété doit vaincre ton V + MS, fixé à la pose. Un support explicitement supérieur peut résister.","texte_reference":"SR/R — 1 PA. Sur un objet, document, relique ou support surnaturel accessible, placer un sceau de Magdalena. Jusqu’à la fin de la scène, une activation de la propriété surnaturelle scellée doit vaincre Volonté + Maîtrise spirituelle. Un support explicitement supérieur peut résister.\nConditions de résolution : 1 PA au contact pour la scène ; nommer une propriété identifiée, jet de création comme Puissance ; chaque activation affronte le sceau une seule fois.","lore":"Le sceau de Magdalena place une propriété surnaturelle sous interdit temporaire. L’objet demeure ce qu’il est, mais sa capacité scellée doit forcer le jugement de l’Inquisiteur chaque fois qu’elle tente de s’exprimer.","groupe_actuel":"Chasseurs catholiques › Ordre de Magdalena — Jugement","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'chasseurs_catholiques_ordre_de_magdalena_jugement_confiscation_spirituelle', 'Confiscation spirituelle', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R, 1/scène, sans PA","activation":"1/scène sans PA supplémentaire après désarmement réel ; opposition à la Puissance du lien ; suspension pour la scène, aucune appropriation.","texte_court":"après avoir désarmé ou neutralisé une cible d''un objet surnaturel lié, opposition à la Puissance du lien : le lien d''usage est suspendu pour la scène. L''objet n''est ni détruit ni acquis.","texte_reference":"R — 1/Scène. Après avoir neutralisé ou désarmé une cible d’un objet surnaturel lié, suspendre le lien d’usage entre cet objet et son propriétaire jusqu’à la fin de la scène. L’objet n’est ni détruit ni acquis gratuitement.\nConditions de résolution : 1/scène sans PA supplémentaire après désarmement réel ; opposition à la Puissance du lien ; suspension pour la scène, aucune appropriation.","lore":"La confiscation ne vole pas l’objet : elle suspend le privilège surnaturel de celui qui prétend encore l’utiliser. Après désarmement, le lien entre relique et propriétaire peut être mis sous séquestre le temps de la scène.","groupe_actuel":"Chasseurs catholiques › Ordre de Magdalena — Jugement","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'chasseurs_catholiques_ordre_de_magdalena_jugement_faire_comparaitre_la_corruption', 'Faire comparaître la corruption', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, 1 PA, 10 m","activation":"1 PA à 10 m ; Volonté + Maîtrise spirituelle contre Puissance de dissimulation si présente ; devient ciblable par les officiants qui la perçoivent jusqu’à fin du prochain round.","texte_court":"une corruption ou influence extérieure déjà détectée devient distincte et ciblable par les rites de purification, de scellement ou de rupture jusqu''à la fin du prochain round. Une dissimulation oppose sa Puissance à ton V + MS. La cible n''est pas purifiée pour autant.","texte_reference":"SR/R — 1 PA. Une corruption extérieure ou influence active déjà détectée devient distincte et perceptible comme cible de rite jusqu’à la fin du prochain round. Elle peut alors être visée par des Talents de purification, scellement ou rupture appropriés ; la cible elle-même n’est pas automatiquement purifiée.\nConditions de résolution : 1 PA à 10 m ; Volonté + Maîtrise spirituelle contre Puissance de dissimulation si présente ; devient ciblable par les officiants qui la perçoivent jusqu’à fin du prochain round.","lore":"Une influence détectée peut être forcée à comparaître comme chose distincte de sa victime. Elle devient alors assez nettement définie pour recevoir sceau, purification ou rupture, sans que cette mise en accusation suffise encore à la vaincre.","groupe_actuel":"Chasseurs catholiques › Ordre de Magdalena — Jugement","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'chasseurs_catholiques_ordre_de_magdalena_jugement_briser_le_pacte', 'Briser le pacte', NULL, '{"nature":"humain","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, rituel d''une heure au moins","activation":"1 heure minimum, victime et support accessibles ; opposition à la Puissance, conséquences contractuelles explicites avant résolution ; garder 3 PTV.","texte_court":"sur un pacte imposé sans consentement réel, dont tu as identifié la chaîne et les clauses essentielles, victime et support accessibles, V + MS contre sa Puissance ou son garant. Réussite : le pacte est rompu durablement ; ses clauses de rupture peuvent se déclencher. Un pacte librement conclu tient.","texte_reference":"R — Rituel prolongé. Sur un pacte surnaturel imposé sans consentement réel, après identification de sa chaîne et de ses clauses essentielles, Volonté + Maîtrise spirituelle contre la Puissance du pacte ou son garant. En réussite, le pacte est rompu durablement. Les conséquences prévues par ses clauses peuvent se déclencher. Un pacte librement conclu n’est pas annulé par ce Talent.\nConditions de résolution : 1 heure minimum, victime et support accessibles ; opposition à la Puissance, conséquences contractuelles explicites avant résolution ; garder 3 PTV.","lore":"Magdalena traite un pacte imposé comme une chaîne qui n’a jamais reçu la légitimité du consentement. Une fois ses attaches et ses clauses comprises, l’Inquisiteur peut chercher à la rompre, en acceptant que le pacte possède peut-être ses propres représailles.","groupe_actuel":"Chasseurs catholiques › Ordre de Magdalena — Jugement","statut_regle":"correction","changements":"note de développement retirée de Briser le pacte (« garder 3 PTV »). Ressort déjà distinct de Briser le pacte contraint (Khālsā) : Magdalena juge sur pièces et doit connaître les clauses ; le Khālsā tranche avec l''Arme du Serment, victime présente, sans connaître les clauses."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'chasseurs_catholiques_ordre_de_magdalena_jugement_excommunication_surnaturelle', 'Excommunication surnaturelle', NULL, '{"nature":"humain","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, 2 PA, 10 m, 1/scène","activation":"2 PA à 10 m, 1/scène ; opposer à la Puissance de la délégation identifiée, suspendre ce seul canal pour la scène, jamais le Patron.","texte_court":"sur une faveur, bénédiction, délégation ou canal extérieur identifié, V + MS contre sa source. Réussite : ce canal est suspendu pour la scène. Jamais une Nature, un Mageius, un Patron ou une identité divine.","texte_reference":"R — 2 PA — 1/Scène. Sur une cible porteuse d’une faveur, bénédiction, délégation ou canal extérieur correctement identifié, Volonté + Maîtrise spirituelle contre sa source. En réussite, cette délégation est suspendue pour la scène. Ne retire jamais une Nature, un Mageius, un Patron fondamental ou une identité divine intrinsèque.\nConditions de résolution : 2 PA à 10 m, 1/scène ; opposer à la Puissance de la délégation identifiée, suspendre ce seul canal pour la scène, jamais le Patron.","lore":"L’Excommunication vise ce qui a été accordé de l’extérieur : faveur, bénédiction, délégation ou canal. Magdalena peut suspendre cette autorisation sans prétendre retrancher d’un être ce qui constitue sa Nature véritable.","groupe_actuel":"Chasseurs catholiques › Ordre de Magdalena — Jugement","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('couche', 'humain', 'humain_khalsa', 'Khālsā', NULL, '{"nature":"humain","chemin":["Khālsā"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'humain', 'humain_khalsa_arme_du_serment', 'Arme du Serment', NULL, '{"nature":"humain","forme":"une_porte","forme_lot":"1 porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"note de développement de Briser le rempart appliquée (aucun PA ajouté) puis retirée. En-tête de Trancher l''emprise complété (1 PA). Ressort déjà distinct des brèches d''autres traditions : l''Arme du Serment, consacrée longuement, au contact."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'khalsa_serment_protection_et_liberte_arme_du_serment_arme_du_serment', 'Arme du Serment', NULL, '{"nature":"humain","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, rituel de 10 minutes, puis passif","activation":"10 minutes au contact, une arme du Serment à la fois ; nouvelle consécration remplace l’ancienne, caractère Sacré sans bonus de statistiques.","texte_court":"une arme de mêlée que tu possèdes devient Sacrée et peut frapper une manifestation spirituelle ou partiellement immatérielle suffisamment présente. Une seule à la fois. Aucun bonus.","texte_reference":"SR/R — Rituel / Passif. Consacrer une arme de mêlée réellement possédée. Elle compte comme Sacrée et peut affecter une manifestation spirituelle ou partiellement immatérielle suffisamment présente. Aucun bonus d’attaque, DGT ou Armure.\nConditions de résolution : 10 minutes au contact, une arme du Serment à la fois ; nouvelle consécration remplace l’ancienne, caractère Sacré sans bonus de statistiques.","lore":"L’arme consacrée par le Khālsā devient le prolongement visible de son engagement. Elle peut toucher l’esprit suffisamment manifesté et porter le caractère Sacré du Serment sans que cette dignité lui offre la moindre puissance balistique gratuite.","groupe_actuel":"Khālsā — Serment, protection et liberté › Arme du Serment","statut_regle":"correction","changements":"note de développement de Briser le rempart appliquée (aucun PA ajouté) puis retirée. En-tête de Trancher l''emprise complété (1 PA). Ressort déjà distinct des brèches d''autres traditions : l''Arme du Serment, consacrée longuement, au contact."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'khalsa_serment_protection_et_liberte_arme_du_serment_plaie_fidele', 'Plaie fidèle', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R, passif","activation":"2 PTV et Arme du Serment ; bloquer seulement les PV infligés jusqu’à fin de prochaine activation, médecine et soins externes maintenus.","texte_court":"une blessure infligée par l''Arme du Serment ne peut pas être régénérée surnaturellement jusqu''à la fin de la prochaine activation de la cible. Médecine et soins externes restent possibles.","texte_reference":"R — Passif — Prérequis : Arme du Serment. Une attaque avec l’Arme du Serment infligeant au moins 1 dégât réel empêche la récupération de ces dégâts par régénération surnaturelle jusqu’à la fin de la prochaine activation de la cible. Soins externes et médecine restent possibles.\nConditions de résolution : Arme du Serment ; bloquer seulement les PV infligés jusqu’à fin de prochaine activation, médecine et soins externes maintenus.","lore":"Une blessure reçue de l’Arme du Serment refuse d’être immédiatement effacée par une régénération surnaturelle. Le sang peut être soigné de l’extérieur, mais la Nature de la cible ne referme pas simplement la marque consacrée comme si elle n’avait jamais existé.","groupe_actuel":"Khālsā — Serment, protection et liberté › Arme du Serment","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'khalsa_serment_protection_et_liberte_arme_du_serment_trancher_lemprise', 'Trancher l''emprise', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R, 1 PA au contact, 1/scène","activation":"1 PA au contact, 1/scène ; toucher une source consentante ou accessible, attaque normale si hostile, puis opposition au maintien, sans dégâts gratuits supplémentaires.","texte_court":"touche ou frappe la source, l''ancrage, l''objet ou la manifestation qui maintient un effet surnaturel (attaque normale si hostile), puis V + MS contre sa Puissance. Réussite : l''effet maintenu s''interrompt. Ni Nature, ni propriété permanente, ni effet devenu autonome.","texte_reference":"R — 1/Scène — Prérequis : Arme du Serment. Attaquer ou toucher directement la source, l’ancrage, l’objet ou la manifestation maintenant un effet surnaturel actuel. Volonté + Maîtrise spirituelle contre la Puissance de l’effet ; en réussite, un effet maintenu est interrompu. Ne vise ni Nature, ni propriété permanente, ni effet devenu autonome.\nConditions de résolution : 1 PA au contact, 1/scène ; toucher une source consentante ou accessible, attaque normale si hostile, puis opposition au maintien, sans dégâts gratuits supplémentaires.","lore":"Le Khālsā frappe ce qui maintient réellement l’emprise : objet, ancrage, source ou manifestation. Le coup devient une rupture de lien et non une attaque contre l’être qui en subit les conséquences.","groupe_actuel":"Khālsā — Serment, protection et liberté › Arme du Serment","statut_regle":"correction","changements":"note de développement de Briser le rempart appliquée (aucun PA ajouté) puis retirée. En-tête de Trancher l''emprise complété (1 PA). Ressort déjà distinct des brèches d''autres traditions : l''Arme du Serment, consacrée longuement, au contact."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'khalsa_serment_protection_et_liberte_arme_du_serment_coup_de_delivrance', 'Coup de délivrance', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R, 1/round","activation":"1/round, attaque normalement payée avec l’Arme du Serment ; occupant identifié et réellement accessible spirituellement, pas de dommages doublés sur l’hôte.","texte_court":"contre une possession ou un parasite identifié, ton attaque normalement payée avec l''Arme du Serment vise l''occupant à travers l''hôte, contre la Défense de l''entité. Les dégâts touchent l''entité, pas le corps de l''hôte.","texte_reference":"R — 1/round — Prérequis : Arme du Serment. Si une possession, un parasite spirituel ou une entité extérieure distincte a été correctement identifié, l’Arme du Serment peut attaquer l’occupant à travers l’hôte. Résoudre l’attaque contre la Défense appropriée de l’entité ; les dégâts visent l’entité et non le corps de l’hôte.\nConditions de résolution : 1/round, attaque normalement payée avec l’Arme du Serment ; occupant identifié et réellement accessible spirituellement, pas de dommages doublés sur l’hôte.","lore":"Lorsqu’un occupant étranger a été clairement distingué de son hôte, l’Arme du Serment peut chercher cette présence directement. Le corps possédé n’est plus automatiquement celui qui paie pour la violence dirigée contre ce qui l’habite.","groupe_actuel":"Khālsā — Serment, protection et liberté › Arme du Serment","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'khalsa_serment_protection_et_liberte_arme_du_serment_briser_le_rempart', 'Briser le rempart', NULL, '{"nature":"humain","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, 1/scène, après Trancher l''emprise","activation":"Préciser qu’aucun PA d’activation ne s’ajoute à l’attaque normale, puis opposition à la Puissance.","texte_court":"après une attaque réussie contre une barrière ou Protection surnaturelle active, renonce aux dégâts : V + MS contre sa Puissance. Réussite : la Protection est suspendue jusqu''à la fin de la prochaine activation de son bénéficiaire. Aucun PA en plus de l''attaque.","texte_reference":"R — 1/Scène — Prérequis : Trancher l’emprise. Après une attaque réussie contre une barrière ou Protection surnaturelle active, renoncer aux dégâts ordinaires puis effectuer Volonté + Maîtrise spirituelle contre la Puissance du rempart. En réussite, la Protection est suspendue jusqu’à la fin de la prochaine activation de son bénéficiaire.\nConditions de résolution : Préciser qu’aucun PA d’activation ne s’ajoute à l’attaque normale, puis opposition à la Puissance.","lore":"Le Khālsā peut choisir de frapper la protection plutôt que celui qu’elle couvre. Toute la force du Serment est alors dirigée contre le rempart surnaturel afin d’ouvrir un instant le passage au lieu de chercher les dégâts ordinaires.","groupe_actuel":"Khālsā — Serment, protection et liberté › Arme du Serment","statut_regle":"correction","changements":"note de développement de Briser le rempart appliquée (aucun PA ajouté) puis retirée. En-tête de Trancher l''emprise complété (1 PA). Ressort déjà distinct des brèches d''autres traditions : l''Arme du Serment, consacrée longuement, au contact."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'humain', 'humain_khalsa_devoir_de_protection', 'Devoir de Protection', NULL, '{"nature":"humain","forme":"une_porte","forme_lot":"1 porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"aucun. Ressort déjà distinct du Sacrifice de Tiph''ereth (Kabbale) : le Khālsā le fait chaque round, par devoir ; le Kabbaliste une fois par scène, par offrande."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'khalsa_serment_protection_et_liberte_devoir_de_protection_veille_du_defenseur', 'Veille du défenseur', NULL, '{"nature":"humain","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, réaction 1 PA","activation":"Réaction 1 PA, allié au contact ou à 3 m sur trajet libre ; PA déjà disponible même Surpris, sans défense gratuite supplémentaire.","texte_court":"même Surpris, quand une manifestation surnaturelle attaque un allié au contact ou à 3 m sur un trajet libre, tu t''interposes et deviens la cible. Aucun PA ni défense en plus.","texte_reference":"SR/R — Réaction 1 PA. Même Surpris par une manifestation surnaturelle attaquant un allié proche, le Khālsā peut dépenser un PA déjà déterminé pour s’interposer et devenir la cible si la position et le vecteur le permettent. Aucun PA supplémentaire.\nConditions de résolution : Réaction 1 PA, allié au contact ou à 3 m sur trajet libre ; PA déjà disponible même Surpris, sans défense gratuite supplémentaire.","lore":"Même surpris, le Khālsā peut reconnaître que l’attaque vise celui qu’il a juré de protéger. S’il lui reste réellement une action disponible et la possibilité physique de s’interposer, son corps part avant que la stupeur ne le fige.","groupe_actuel":"Khālsā — Serment, protection et liberté › Devoir de Protection","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'khalsa_serment_protection_et_liberte_devoir_de_protection_parole_qui_releve', 'Parole qui relève', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, réaction 1 PA, 1/scène par cible, 10 m","activation":"Réaction 1 PA, allié à 10 m qui entend, 1/scène/cible et une seule relance de talent par test.","texte_court":"un allié qui t''entend échoue (non narratif) à résister à peur, domination, désespoir, compulsion ou attaque de volonté surnaturelle : il relance le d10e. Le second résultat est définitif.","texte_reference":"SR/R — Réaction 1 PA — 1/Scène/cible. Après l’échec non narratif d’un allié à une résistance contre peur, domination, désespoir, compulsion ou attaque de volonté surnaturelle, lui permettre de relancer le d10e. Le second résultat est définitif ; une seule relance de Talent par test.\nConditions de résolution : Réaction 1 PA, allié à 10 m qui entend, 1/scène/cible et une seule relance de talent par test.","lore":"La Parole qui relève rappelle à un allié qu’il possède encore une volonté après l’instant où celle-ci vient de céder. Peur, domination ou désespoir peuvent être affrontés une seconde fois, avec pour seul appui la voix du défenseur.","groupe_actuel":"Khālsā — Serment, protection et liberté › Devoir de Protection","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'khalsa_serment_protection_et_liberte_devoir_de_protection_tenir_la_ligne', 'Tenir la ligne', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R, 1 PA puis 1 PA par round","activation":"1 PA puis maintien 1 PA/round, ligne de 3 m devant soi ; opposition au franchissement surnaturel, pas aux projectiles ou déplacements ordinaires.","texte_court":"tu tiens une ligne de 3 m devant toi. Une entité spirituelle, immatérielle ou en déplacement surnaturel doit vaincre ton V + MS pour la franchir. N''arrête ni course, ni véhicule, ni projectile.","texte_reference":"R — Maintien 1 PA/round. En défendant un passage, seuil ou zone immédiate, toute entité spirituelle, immatérielle ou utilisant un déplacement surnaturel doit vaincre Volonté + Maîtrise spirituelle du Khālsā pour franchir volontairement sa ligne. N’arrête pas course, véhicule, projectile ou effondrement.\nConditions de résolution : 1 PA puis maintien 1 PA/round, ligne de 3 m devant soi ; opposition au franchissement surnaturel, pas aux projectiles ou déplacements ordinaires.","lore":"Le défenseur consacre sa propre position comme une ligne à ne pas franchir surnaturellement. Esprits et déplacements occultes doivent vaincre sa volonté pour passer, tandis qu’un corps, un véhicule ou un projectile reste soumis aux lois ordinaires du combat.","groupe_actuel":"Khālsā — Serment, protection et liberté › Devoir de Protection","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'khalsa_serment_protection_et_liberte_devoir_de_protection_prendre_le_fardeau', 'Prendre le fardeau', NULL, '{"nature":"humain","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"SR/R, réaction 1 PA, 1/round, 10 m","activation":"Réaction 1 PA, 1/round, allié à 10 m perçu ; devenir la cible avant sa résistance, utiliser ensuite ses propres protections, aucune duplication.","texte_court":"un effet surnaturel hostile à cible unique (malédiction, domination, possession, attaque mentale) vise un allié perçu : si tu es une cible valide, tu deviens la cible, avec tes propres protections. Pas contre une zone.","texte_reference":"SR/R — Réaction 1 PA — max 1/round. Lorsqu’un effet surnaturel hostile à cible unique vise un allié proche et que le Khālsā constitue lui-même une cible valide, il peut volontairement devenir la cible. Fonctionne notamment contre malédiction, domination, possession ou attaque mentale ; pas contre une zone ni un effet impossible à appliquer au Khālsā.\nConditions de résolution : Réaction 1 PA, 1/round, allié à 10 m perçu ; devenir la cible avant sa résistance, utiliser ensuite ses propres protections, aucune duplication.","lore":"Protéger signifie parfois accepter que la malédiction ou la domination trouve une autre cible. Le Khālsā se place volontairement sur le chemin de l’effet à cible unique et assume lui-même ce qu’il empêchait d’atteindre son compagnon.","groupe_actuel":"Khālsā — Serment, protection et liberté › Devoir de Protection","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'khalsa_serment_protection_et_liberte_devoir_de_protection_refuge_vivant', 'Refuge vivant', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R, 1 PA puis 1 PA par round, après Prendre le fardeau","activation":"1 PA et maintien 1 PA/round ; une personne au contact ou à 1 m derrière, perte de cette position met fin à la protection.","texte_court":"une personne consentante au contact ou juste derrière toi (1 m) : toute tentative extérieure de possession, domination, malédiction ou lien hostile doit d''abord vaincre ton V + MS, puis se résout normalement contre elle. Quitter la position y met fin.","texte_reference":"R — 1 PA puis maintien 1 PA/round — Prérequis : Prendre le fardeau. Une personne consentante au contact ou immédiatement derrière le Khālsā est protégée : une tentative extérieure de possession, domination, malédiction spirituelle ou lien hostile doit d’abord vaincre Volonté + Maîtrise spirituelle du Khālsā ; en réussite, l’effet résout ensuite normalement contre sa vraie cible. Le Khālsā ne le prend pas automatiquement.\nConditions de résolution : 1 PA et maintien 1 PA/round ; une personne au contact ou à 1 m derrière, perte de cette position met fin à la protection.","lore":"Le Khālsā devient le seuil derrière lequel un proche consentant peut se tenir. Possession, malédiction et domination doivent d’abord franchir sa vigilance spirituelle avant d’arriver jusqu’à la personne qu’il couvre.","groupe_actuel":"Khālsā — Serment, protection et liberté › Devoir de Protection","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'humain', 'humain_khalsa_volonte_libre', 'Volonté libre', NULL, '{"nature":"humain","forme":"une_porte","forme_lot":"1 porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"mention méta retirée de Libérer la volonté (« Ephraïm reste la référence pour l''expulsion »)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'khalsa_serment_protection_et_liberte_volonte_libre_esprit_sans_maitre', 'Esprit sans maître', NULL, '{"nature":"humain","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, passif, 1/scène","activation":"Offrir une résistance supplémentaire gratuite au début de la prochaine activation, 1/scène, puis suivre les résistances normales de l’effet.","texte_court":"au début de ta prochaine activation après avoir subi un contrôle surnaturel, une résistance supplémentaire gratuite contre sa Puissance. Ensuite, seules les résistances prévues par l''effet.","texte_reference":"Une fois par scène, au début de votre prochaine activation après avoir subi un contrôle surnaturel, effectuez gratuitement une résistance supplémentaire contre sa Puissance. Ensuite, seules les résistances normalement prévues par l’effet restent possibles.","lore":"Un contrôle maintenu doit reconquérir le Khālsā à chaque fois qu’il essaie d’agir à travers lui. Son esprit recommence la lutte au début de chaque activation au lieu d’accepter qu’une défaite initiale vaille soumission indéfinie.","groupe_actuel":"Khālsā — Serment, protection et liberté › Volonté libre","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'khalsa_serment_protection_et_liberte_volonte_libre_deceler_lemprise', 'Déceler l''emprise', NULL, '{"nature":"humain","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, 1 PA, 10 m","activation":"1 PA à 10 m sur personne perçue ; contre dissimulation active, Esprit + Perception contre Puissance ; exclusions ordinaires inchangées.","texte_court":"tu sais si les actes actuels d''une personne sont directement contraints par une influence surnaturelle extérieure. Ni source, ni ordre, ni Nature ; pas la persuasion, le chantage ou l''addiction.","texte_reference":"SR/R — 1 PA. Observer une personne et déterminer si ses actes ou décisions actuels sont directement contraints par une influence surnaturelle extérieure. Ne révèle ni source, ni ordre, ni Nature ; ne détecte pas persuasion, chantage, addiction ou pression ordinaire.\nConditions de résolution : 1 PA à 10 m sur personne perçue ; contre dissimulation active, Esprit + Perception contre Puissance ; exclusions ordinaires inchangées.","lore":"La Volonté libre distingue l’ordre surnaturel du choix personnel sans juger le reste de la vie d’une personne. Le Khālsā voit qu’une décision présente est contrainte de l’extérieur, mais pas qui tient la laisse ni ce qu’il a ordonné.","groupe_actuel":"Khālsā — Serment, protection et liberté › Volonté libre","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'khalsa_serment_protection_et_liberte_volonte_libre_refuser_la_souillure', 'Refuser la souillure', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, 1/scène","activation":"2 PTV et 1/scène ; ne cumuler aucune réduction équivalente, ne pas modifier l’Intégrité ni la Corruption déjà acquise.","texte_court":"quand une source surnaturelle extérieure devrait te donner de la Corruption, le gain baisse de 1 (minimum 0). Pas contre une Corruption recherchée ou une transformation devenue intrinsèque ; sans cumul avec une réduction équivalente.","texte_reference":"SR/R — 1/Scène. Lorsqu’une source surnaturelle extérieure devrait infliger de la Corruption, réduire le gain de 1, minimum 0. Ne fonctionne ni sur une Corruption volontairement recherchée ni sur une transformation devenue intrinsèque.\nConditions de résolution : 1/scène ; ne cumuler aucune réduction équivalente, ne pas modifier l’Intégrité ni la Corruption déjà acquise.","lore":"Le Serment protège aussi le droit de rester soi-même face à la corruption extérieure. Une partie de la souillure peut être refusée au moment où elle cherche à entrer, mais pas lorsqu’on la poursuit volontairement ou qu’elle est devenue constitutive de l’être.","groupe_actuel":"Khālsā — Serment, protection et liberté › Volonté libre","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'khalsa_serment_protection_et_liberte_volonte_libre_parole_qui_brise_lordre', 'Parole qui brise l''ordre', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, 1 PA, 1/scène par cible, 10 m","activation":"1 PA, personne à 10 m qui entend, 1/scène/cible ; nouveau test complet contre la Puissance actuelle, pas cumul de relances.","texte_court":"une personne sous domination ou compulsion surnaturelle qui t''entend fait immédiatement un nouveau test complet contre la Puissance actuelle, même si l''effet n''en prévoit pas.","texte_reference":"SR/R — 1 PA — 1/Scène/cible. Une personne sous domination ou compulsion surnaturelle qui entend le Khālsā obtient immédiatement une nouvelle résistance, même si l’effet n’en accorderait normalement aucune. Il s’agit d’un nouveau test, pas d’une relance du test initial.\nConditions de résolution : 1 PA, personne à 10 m qui entend, 1/scène/cible ; nouveau test complet contre la Puissance actuelle, pas cumul de relances.","lore":"Une personne sous compulsion peut entendre dans la voix du Khālsā la possibilité d’un refus qu’elle croyait perdue. Le nouvel effort de résistance commence maintenant, indépendamment de celui qui avait échoué lorsque l’ordre fut d’abord imposé.","groupe_actuel":"Khālsā — Serment, protection et liberté › Volonté libre","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'khalsa_serment_protection_et_liberte_volonte_libre_liberer_la_volonte', 'Libérer la volonté', NULL, '{"nature":"humain","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, 2 PA, 10 m, 1/scène, après Déceler l''emprise","activation":"2 PA à 10 m, 1/scène, contrôle identifié ; opposition à la Puissance du contrôle, suspendu pour la scène sans expulsion de l’entité.","texte_court":"contre un contrôle identifié, V + MS contre sa source. Réussite : la domination, compulsion ou contrôle est suspendu pour la scène. Une entité possessive peut rester, mais ne dirige plus l''hôte.","texte_reference":"R — 2 PA — 1/Scène — Prérequis : Déceler l’emprise. Au contact ou à courte portée d’un contrôle correctement identifié, Volonté + Maîtrise spirituelle contre sa source. En réussite, une domination, compulsion ou contrôle est suspendu jusqu’à la fin de la scène. Une entité possessive peut rester présente mais ne peut diriger l’hôte ; Ephraïm reste la référence pour l’expulsion.\nConditions de résolution : 2 PA à 10 m, 1/scène, contrôle identifié ; opposition à la Puissance du contrôle, suspendu pour la scène sans expulsion de l’entité.","lore":"Le Khālsā vise directement le contrôle déjà identifié et rend pour un temps la conduite de l’hôte à lui-même. Une présence possessive peut rester tapie dans le corps ; ce Talent lui retire la direction sans se substituer au véritable exorcisme.","groupe_actuel":"Khālsā — Serment, protection et liberté › Volonté libre","statut_regle":"correction","changements":"mention méta retirée de Libérer la volonté (« Ephraïm reste la référence pour l''expulsion »)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'humain', 'humain_khalsa_briseur_de_chaines', 'Briseur de chaînes', NULL, '{"nature":"humain","forme":"une_porte","forme_lot":"1 porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"note de développement retirée de Briser le pacte contraint (« deux prérequis exacts »). En-têtes d''Acier libérateur et Délier l''entrave complétés (1 PA)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'khalsa_serment_protection_et_liberte_briseur_de_chaines_voir_les_chaines', 'Voir les chaînes', NULL, '{"nature":"humain","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, 1 PA, 10 m","activation":"1 PA à 10 m ; liens actifs extérieurs seulement, opposition à leur masquage, distinguer contrainte/nourriture sans localisation automatique.","texte_court":"sur une personne, un objet ou un lieu, tu perçois les liens surnaturels actifs vers l''extérieur (pacte, marque, chaîne, sceau, contrat occulte, ancrage, entrave) et s''ils contraignent ou nourrissent. Ni clauses, ni source exacte, ni localisation.","texte_reference":"SR/R — 1 PA. Examiner une personne, un objet ou un lieu à courte portée pour percevoir les liens surnaturels actifs vers une chose extérieure : pacte, marque, chaîne, sceau, contrat occulte, ancrage ou entrave. Déterminer s’il est actif et s’il contraint ou nourrit ; pas ses clauses ni sa source exacte.\nConditions de résolution : 1 PA à 10 m ; liens actifs extérieurs seulement, opposition à leur masquage, distinguer contrainte/nourriture sans localisation automatique.","lore":"Le Briseur apprend d’abord à voir ce qui relie une personne, un objet ou un lieu à quelque chose d’extérieur. Pacte, marque, contrat ou ancrage apparaît comme une chaîne active dont il distingue le rôle général sans encore connaître toutes les clauses.","groupe_actuel":"Khālsā — Serment, protection et liberté › Briseur de chaînes","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'khalsa_serment_protection_et_liberte_briseur_de_chaines_acier_liberateur', 'Acier libérateur', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R, 1 PA au contact, 1/scène, après Voir les chaînes et Arme du Serment","activation":"Arme du Serment ET Voir les chaînes ; 1 PA au contact, 1/scène, opposition à la Puissance ; suspension courte inchangée.","texte_court":"l''Arme du Serment frappe une chaîne surnaturelle identifiée : V + MS contre la Puissance du lien. Réussite : suspendu jusqu''à la fin de la prochaine activation de la cible ; le pacte n''est pas forcément détruit.","texte_reference":"R — 1/Scène — Prérequis : Arme du Serment + Voir les chaînes. Une chaîne surnaturelle identifiée peut être directement ciblée avec l’Arme du Serment. Volonté + Maîtrise spirituelle contre la Puissance du lien ; en réussite, il est suspendu jusqu’à la fin de la prochaine activation de la cible. Un pacte n’est pas nécessairement détruit.\nConditions de résolution : Arme du Serment ET Voir les chaînes ; 1 PA au contact, 1/scène, opposition à la Puissance ; suspension courte inchangée.","lore":"Une chaîne surnaturelle correctement vue peut devenir la cible de l’acier. Le Serment permet de la toucher comme une chose à part entière et de suspendre sa contrainte sans prétendre que tout pacte ainsi atteint disparaît à jamais.","groupe_actuel":"Khālsā — Serment, protection et liberté › Briseur de chaînes","statut_regle":"correction","changements":"note de développement retirée de Briser le pacte contraint (« deux prérequis exacts »). En-têtes d''Acier libérateur et Délier l''entrave complétés (1 PA)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'khalsa_serment_protection_et_liberte_briseur_de_chaines_delier_lentrave', 'Délier l''entrave', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R, 1 PA au contact, 1/scène, après Arme du Serment","activation":"1 PA au contact, 1/scène ; Volonté + Maîtrise spirituelle contre Puissance de l’entrave extérieure.","texte_court":"l''Arme du Serment frappe des chaînes magiques, liens spectraux, paralysies surnaturelles externes ou sceaux de contention : V + MS contre leur Puissance. Réussite : l''entrave est brisée. Pas une paralysie naturelle, une blessure ou un poison.","texte_reference":"R — 1/Scène. Des chaînes magiques, liens spectraux, paralysies surnaturelles externes ou sceaux de contention peuvent être frappés avec l’Arme du Serment ; en réussite à l’opposition appropriée, l’entrave est brisée. Ne fonctionne pas sur paralysie naturelle, blessure, poison ou propriété intrinsèque.\nConditions de résolution : 1 PA au contact, 1/scène ; Volonté + Maîtrise spirituelle contre Puissance de l’entrave extérieure.","lore":"Chaîne magique, paralysie extérieure ou sceau de contention deviennent des entraves que le Serment sait désigner puis frapper. Une blessure, un poison ou une limite naturelle ne deviennent jamais des chaînes simplement parce qu’ils gênent la victime.","groupe_actuel":"Khālsā — Serment, protection et liberté › Briseur de chaînes","statut_regle":"correction","changements":"note de développement retirée de Briser le pacte contraint (« deux prérequis exacts »). En-têtes d''Acier libérateur et Délier l''entrave complétés (1 PA)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'khalsa_serment_protection_et_liberte_briseur_de_chaines_briser_le_pacte_contraint', 'Briser le pacte contraint', NULL, '{"nature":"humain","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, rituel d''une heure au moins, après Acier libérateur","activation":"Minimum 1 heure, victime et support accessibles, opposition à la Puissance ; deux prérequis exacts et conséquences du pacte conservées.","texte_court":"victime présente, pacte identifié, Arme du Serment ou support : V + MS contre le pacte ou son garant. Réussite : un pacte imposé sans consentement réel est rompu durablement ; ses clauses de rupture peuvent se déclencher. Un pacte libre tient.","texte_reference":"R — Rituel prolongé — Prérequis : Voir les chaînes + Acier libérateur. Victime présente, pacte identifié, temps et arme/support requis. Volonté + Maîtrise spirituelle contre le pacte ou son garant ; en réussite, un pacte imposé sans consentement réel est rompu durablement. Les conséquences ou clauses peuvent se déclencher. Ne brise pas un pacte réellement libre.\nConditions de résolution : Minimum 1 heure, victime et support accessibles, opposition à la Puissance ; deux prérequis exacts et conséquences du pacte conservées.","lore":"Le Khālsā ne reconnaît pas comme sacré un engagement arraché sans consentement. Après avoir compris le pacte et réuni les conditions nécessaires, il peut le rompre durablement, quitte à déclencher les clauses que le geôlier avait prévues pour ce jour.","groupe_actuel":"Khālsā — Serment, protection et liberté › Briseur de chaînes","statut_regle":"correction","changements":"note de développement retirée de Briser le pacte contraint (« deux prérequis exacts »). En-têtes d''Acier libérateur et Délier l''entrave complétés (1 PA)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'khalsa_serment_protection_et_liberte_briseur_de_chaines_serment_contre_serment', 'Serment contre serment', NULL, '{"nature":"humain","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, 1/scène, sans PA, après Briser le pacte contraint","activation":"Sans PA supplémentaire lors de la rupture, 1/scène ; même source et même type de lien seulement.","texte_court":"quand tu brises, suspends ou purges un lien hostile, tu prononces un Serment protecteur. La même source ne peut rétablir le même type de lien avant la fin de la scène sans vaincre ton V + MS.","texte_reference":"R — 1/Scène — Prérequis : Briser le pacte contraint. Lorsqu’un lien hostile est brisé, suspendu ou purgé par le Khālsā, il peut prononcer un Serment protecteur. La même source ne peut rétablir le même type de lien jusqu’à la fin de la scène sans vaincre Volonté + Maîtrise spirituelle du Khālsā.\nConditions de résolution : Sans PA supplémentaire lors de la rupture, 1/scène ; même source et même type de lien seulement.","lore":"Après avoir brisé une emprise, le Khālsā remplit le vide par une promesse protectrice. La même source doit désormais vaincre ce nouveau Serment si elle veut rattacher exactement le même type de chaîne avant la fin de la scène.","groupe_actuel":"Khālsā — Serment, protection et liberté › Briseur de chaînes","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('couche', 'humain', 'humain_taoistes', 'Taoïstes', NULL, '{"nature":"humain","chemin":["Taoïstes"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'humain', 'humain_taoistes_fondamentaux_du_qi', 'Fondamentaux du Qi', NULL, '{"nature":"humain","forme":"une_porte","forme_lot":"1 porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"les règles de la piste sortent de Transe de l''équilibre vers l''encadré de tradition (correction : c''était l''entrée la plus longue du fichier)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'taoistes_gu_shimazu_et_secrets_shi_fondamentaux_du_qi_sentir_le_qi', 'Sentir le Qi', NULL, '{"nature":"humain","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, 1 PA, 10 m","activation":"1 PA, 10 m, perturbation actuellement présente ; opposition à une dissimulation active, sans identification automatique de Nature.","texte_court":"tu perçois le Qi d''une créature ou d''un phénomène présent : flux vivant cohérent, altéré, vide anormal ou circulation surnaturelle active. Ni espèce, ni fiche, ni identité ; une dissimulation active s''y oppose.","texte_reference":"SR/R — 1 PA. Percevoir la présence et les perturbations majeures du Qi d’une créature ou d’un phénomène à courte portée même lorsque ses signes physiques sont absents. Le Talent distingue un flux vivant cohérent, un flux altéré, un vide anormal ou une circulation surnaturelle active ; il ne donne ni espèce, ni fiche, ni identité.\nConditions de résolution : 1 PA, 10 m, perturbation actuellement présente ; opposition à une dissimulation active, sans identification automatique de Nature.","lore":"Le Qi laisse une présence que le Taoïste perçoit même lorsque les signes physiques manquent. Flux vivant, circulation altérée, vide anormal ou activité surnaturelle se distinguent par leur équilibre plutôt que par une identité ou une espèce.","groupe_actuel":"Taoïstes — Gu, Shimazu et secrets Shi › Fondamentaux du Qi","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'taoistes_gu_shimazu_et_secrets_shi_fondamentaux_du_qi_souffle_interieur', 'Souffle intérieur', NULL, '{"nature":"humain","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, 1 PA, 1/scène","activation":"1 PA, 1/scène, durée scène ; bloquer seulement les nouveaux agents inhalés, aucune neutralisation des doses déjà reçues.","texte_court":"pour la scène, tu survis sans respirer normalement et résistes aux agents qui ne passent que par l''inhalation. Pas les doses déjà reçues, ni le vide, ni la pression.","texte_reference":"SR/R — 1/Scène. Fermer brièvement les échanges du corps avec l’extérieur. Pour la scène, le Taoïste peut survivre sans respirer normalement et résiste aux agents dont le seul vecteur est l’inhalation ; il ne devient pas immunisé aux toxines déjà présentes, au vide, à la pression ou aux dégâts environnementaux.\nConditions de résolution : 1 PA, 1/scène, durée scène ; bloquer seulement les nouveaux agents inhalés, aucune neutralisation des doses déjà reçues.","lore":"Le Souffle intérieur ferme momentanément le corps sur sa propre circulation. L’inhalation cesse d’être nécessaire et les agents qui ne savent entrer que par les poumons restent dehors, sans protéger contre le vide, la pression ou ce qui est déjà dans le sang.","groupe_actuel":"Taoïstes — Gu, Shimazu et secrets Shi › Fondamentaux du Qi","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'taoistes_gu_shimazu_et_secrets_shi_fondamentaux_du_qi_lecture_des_meridiens', 'Lecture des méridiens', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, 1 PA, 10 m, après Sentir le Qi","activation":"1 PA à 10 m sur cible perçue, valable pour l’état observé dans la scène ; nouvelle lecture si sa circulation change réellement.","texte_court":"sur une créature perçue, tu lis si une altération active est interne ou extérieure, si un méridien est bloqué ou surchargé, et où. Valable pour l''état observé dans la scène ; elle rend ces points ciblables par les techniques taoïstes.","texte_reference":"SR/R — 1 PA — Prérequis : Sentir le Qi. Sur une créature perçue, lire la circulation actuelle du Qi : savoir si une altération active est interne ou extérieure, si un méridien est bloqué ou surchargé et où se trouve le point de circulation principalement concerné. Cette lecture ouvre des cibles impossibles aux techniques taoïstes ; elle ne remplace pas Médecine ou Investigation.\nConditions de résolution : 1 PA à 10 m sur cible perçue, valable pour l’état observé dans la scène ; nouvelle lecture si sa circulation change réellement.","lore":"La Lecture des méridiens transforme un flux abstrait en carte : blocage, surcharge, origine interne ou influence extérieure deviennent localisables. Le taoïste apprend où intervenir sans prétendre remplacer médecin, enquêteur ou exorciste.","groupe_actuel":"Taoïstes — Gu, Shimazu et secrets Shi › Fondamentaux du Qi","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'taoistes_gu_shimazu_et_secrets_shi_fondamentaux_du_qi_transe_de_lequilibre', 'Transe de l''équilibre', NULL, '{"nature":"humain","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, 2 PA, 1/scène, à Équilibre seulement","activation":"2 PA, 1/scène ; publier la piste et l’ordre des déplacements, première technique de chaque polarité exonérée par round, arrêt aux extrêmes.","texte_court":"pour la scène, ta première technique Yin et ta première technique Yang de chaque round ne déplacent pas la piste. Une polarité répétée la déplace normalement. La Transe cesse dès qu''un extrême est atteint.","texte_reference":"R — 2 PA — 1/Scène. Uniquement à Équilibre. Pour la scène, la première utilisation d’un Talent Yin et la première utilisation d’un Talent Yang de chaque round ne déplacent pas la piste de Qi. Une même polarité répétée la déplace ensuite normalement. La Transe cesse immédiatement si le personnage atteint Yin profond ou Yang profond.\nConditions de résolution : 2 PA, 1/scène ; première technique de chaque polarité exonérée par round, arrêt aux extrêmes.\nPiste de Qi : Yin profond ← Yin ← Équilibre → Yang → Yang profond. Commencez à Équilibre. Un déplacement indiqué par une technique avance d’un cran vers sa polarité, sans dépasser l’extrémité ; un déplacement direct vers un état rejoint cet état. Résolvez les techniques dans leur ordre d’utilisation. Transe exonère la première technique Yin et la première Yang de chaque round ; Cycle contraire remplace le déplacement normal par un cran vers Équilibre ; Deux souffles diffère le calcul jusqu’après les deux techniques, sans supprimer leurs déplacements. La Transe cesse dès qu’un extrême est atteint.","lore":"À l’Équilibre, la Transe maintient Yin et Yang autour d’un centre volontairement stable. La première expression de chaque polarité trouve sa place sans déplacer le pratiquant ; insister dans un seul sens finit pourtant par rompre cette neutralité.","groupe_actuel":"Taoïstes — Gu, Shimazu et secrets Shi › Fondamentaux du Qi","statut_regle":"correction","changements":"les règles de la piste sortent de Transe de l''équilibre vers l''encadré de tradition (correction : c''était l''entrée la plus longue du fichier)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'humain', 'humain_taoistes_voie_du_yin', 'Voie du Yin', NULL, '{"nature":"humain","forme":"une_porte","forme_lot":"1 porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"aucun. Ressort déjà distinct des autres défenses spirituelles : chaque technique déplace la piste de Qi."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'taoistes_gu_shimazu_et_secrets_shi_voie_du_yin_paume_yin', 'Paume Yin', NULL, '{"nature":"humain","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, 1/round, sans PA, Yin +1","activation":"1/round, sans PA ajouté à l’attaque ; suspend seulement la récupération automatique jusqu’à fin de prochaine activation.","texte_court":"après une attaque de Pugilat qui blesse, la cible ne peut bénéficier d''aucune récupération surnaturelle automatique de PV jusqu''à la fin de sa prochaine activation.","texte_reference":"SR/R — 1/round. Après une attaque de Pugilat réussie infligeant au moins 1 dégât réel, fermer brièvement le flux de la cible : jusqu’à la fin de sa prochaine activation, elle ne peut bénéficier d’une récupération surnaturelle automatique de PV. Décale d’un cran vers Yin.\nConditions de résolution : 1/round, sans PA ajouté à l’attaque ; suspend seulement la récupération automatique jusqu’à fin de prochaine activation.","lore":"La Paume Yin ferme momentanément la circulation qui soutient une récupération surnaturelle. La blessure reste une blessure ordinaire à soigner ; elle cesse seulement d’être immédiatement effacée par la puissance interne de la cible.","groupe_actuel":"Taoïstes — Gu, Shimazu et secrets Shi › Voie du Yin","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'taoistes_gu_shimazu_et_secrets_shi_voie_du_yin_qi_silencieux', 'Qi silencieux', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, 1 PA, scène, Yin +1","activation":"1 PA pour la scène, un cran Yin ; fixer le jet de Volonté + Maîtrise spirituelle à l’activation, opposé aux seules perceptions énergétiques adaptées.","texte_court":"les perceptions surnaturelles d''aura, de Qi, d''énergie vitale ou de signature spirituelle doivent vaincre ton V + MS, fixé à l''activation. Tu n''es ni invisible ni silencieux.","texte_reference":"SR/R — 1 PA — Scène. Rendre sa circulation métaphysiquement silencieuse. Les perceptions surnaturelles fondées sur aura, Qi, énergie vitale ou signature spirituelle doivent vaincre Volonté + Maîtrise spirituelle du Taoïste pour le détecter. Ne rend ni invisible ni silencieux physiquement. Décale d’un cran vers Yin.\nConditions de résolution : 1 PA pour la scène, un cran Yin ; fixer le jet de Volonté + Maîtrise spirituelle à l’activation, opposé aux seules perceptions énergétiques adaptées.","lore":"Le Taoïste apaise son Qi jusqu’à ce qu’il ne rayonne presque plus hors de lui. Aura, énergie vitale et signature spirituelle deviennent difficiles à détecter, sans rien changer au bruit de ses pas ni à la lumière qui tombe sur son corps.","groupe_actuel":"Taoïstes — Gu, Shimazu et secrets Shi › Voie du Yin","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'taoistes_gu_shimazu_et_secrets_shi_voie_du_yin_meridiens_fermes', 'Méridiens fermés', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, réaction 1 PA, 1/round, Yin +1, après Lecture des méridiens","activation":"Réaction 1 PA incluant la Défense active : Volonté + Maîtrise spirituelle + d10e ; une seule défense contre l’effet interne, puis déplacement Yin.","texte_court":"contre un effet qui veut agir à l''intérieur de ton corps, Défense active V + MS + d10e. Réussite : il ne s''ancre pas en toi.","texte_reference":"SR/R — Réaction 1 PA — 1/round — Prérequis : Lecture des méridiens. Lorsqu’un effet surnaturel cherche à agir directement à l’intérieur du corps, le Taoïste peut fermer la circulation concernée et utiliser Volonté + Maîtrise spirituelle à la place de sa Défense occulte passive si elle est meilleure. En réussite, l’effet ne peut établir son ancrage interne. Décale d’un cran vers Yin.\nConditions de résolution : Réaction 1 PA incluant la Défense active : Volonté + Maîtrise spirituelle + d10e ; une seule défense contre l’effet interne, puis déplacement Yin.","lore":"Le Yin ferme la voie par laquelle un pouvoir tente de s’établir directement dans le corps. L’influence doit alors vaincre la circulation spirituelle verrouillée avant de pouvoir créer son ancrage interne.","groupe_actuel":"Taoïstes — Gu, Shimazu et secrets Shi › Voie du Yin","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'taoistes_gu_shimazu_et_secrets_shi_voie_du_yin_nuit_des_cinq_souffles', 'Nuit des cinq souffles', NULL, '{"nature":"humain","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, 2 PA, 1/scène, Yin profond direct, après Qi silencieux","activation":"Indétectable aux sens énergétiques ordinaires, perception surnaturelle dédiée opposée à la Puissance de la technique ; Yin profond et contraintes physiques conservés.","texte_court":"pour la scène, les sens énergétiques ordinaires ne détectent plus ta vie ; une perception dédiée doit vaincre ton V + MS. Tu peux franchir les seuils qui exigent l''absence de souffle vivant. Tu restes vivant, matériel et visible.","texte_reference":"Pour 2 PA, une fois par scène, plongez votre Qi en Yin profond pour la scène. Les sens énergétiques ordinaires ne détectent plus votre signature de vie ; une perception surnaturelle dédiée doit vaincre la Puissance de votre technique, fixée par Volonté + Maîtrise spirituelle à l’activation. Vous pouvez interagir avec les seuils qui exigent l’absence de souffle vivant. Vous restez vivant, matériel et détectable par les sens ordinaires.","lore":"La Nuit des cinq souffles plonge le Qi presque jusqu’à l’absence. Les sens fondés sur âme ou énergie vitale ne trouvent plus de signature à suivre, alors que le corps reste parfaitement vivant, matériel et visible pour les perceptions ordinaires.","groupe_actuel":"Taoïstes — Gu, Shimazu et secrets Shi › Voie du Yin","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'humain', 'humain_taoistes_voie_du_yang', 'Voie du Yang', NULL, '{"nature":"humain","forme":"une_porte","forme_lot":"1 porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"aucun."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'taoistes_gu_shimazu_et_secrets_shi_voie_du_yang_paume_yang', 'Paume Yang', NULL, '{"nature":"humain","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, 1/round, Yang +1","activation":"L’attaque de Pugilat peut d’emblée cibler la manifestation accessible ; sur réussite, empêcher son effacement énergétique jusqu’à fin de prochaine activation ; un cran Yang.","texte_court":"ton attaque de Pugilat peut viser une entité spirituelle ou partiellement immatérielle présente. Réussite : jusqu''à la fin de sa prochaine activation, elle ne peut se dissimuler en supprimant sa propre présence énergétique.","texte_reference":"SR/R — 1/round. Après une attaque de Pugilat réussie, le Taoïste injecte un flux manifeste. L’attaque peut affecter une entité spirituelle ou partiellement immatérielle suffisamment présente et empêche jusqu’à la fin de sa prochaine activation une dissimulation fondée sur la suppression de sa propre présence énergétique. Décale d’un cran vers Yang.\nConditions de résolution : L’attaque de Pugilat peut d’emblée cibler la manifestation accessible ; sur réussite, empêcher son effacement énergétique jusqu’à fin de prochaine activation ; un cran Yang.","lore":"La Paume Yang injecte dans l’impact un flux assez manifeste pour rencontrer l’esprit partiellement présent. Ce même excès de présence empêche brièvement la cible de disparaître en effaçant sa propre signature énergétique.","groupe_actuel":"Taoïstes — Gu, Shimazu et secrets Shi › Voie du Yang","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'taoistes_gu_shimazu_et_secrets_shi_voie_du_yang_barriere_yang', 'Barrière Yang', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, réaction 1 PA, 1/round, Yang +1","activation":"Réaction 1 PA incluant la Défense, Volonté + Maîtrise spirituelle + d10e contre attaque surnaturelle perçue ; jamais en plus d’une autre Défense.","texte_court":"contre une attaque surnaturelle directe perçue, Défense active V + MS + d10e si c''est mieux. Pas contre une balle ou une chute ordinaire ; jamais en plus d''une autre Défense.","texte_reference":"SR/R — Réaction 1 PA — 1/round. Projeter le Qi devant soi contre une attaque surnaturelle directe perçue. Utiliser Volonté + Maîtrise spirituelle comme Défense active si elle est meilleure que la Défense normalement applicable. La Barrière ne protège pas d’une balle ou chute strictement ordinaire. Décale d’un cran vers Yang.\nConditions de résolution : Réaction 1 PA incluant la Défense, Volonté + Maîtrise spirituelle + d10e contre attaque surnaturelle perçue ; jamais en plus d’une autre Défense.","lore":"Le Yang est projeté comme une présence manifeste entre le Taoïste et une attaque surnaturelle perçue. Cette défense oppose la maîtrise spirituelle au phénomène qui arrive, pas aux balles et aux chutes dont la menace est strictement matérielle.","groupe_actuel":"Taoïstes — Gu, Shimazu et secrets Shi › Voie du Yang","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'taoistes_gu_shimazu_et_secrets_shi_voie_du_yang_circulation_vitale', 'Circulation vitale', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, 1 PA, 1/scène, Yang +1, après Lecture des méridiens","activation":"1 PA, 1/scène, contact et consentement ; suspension d’une seule altération extérieure, un cran Yang.","texte_court":"sur toi ou une cible consentante au contact, une fonction vitale bloquée surnaturellement (respiration, circulation, membre, conscience) repart : l''altération extérieure est suspendue un round. Ne soigne pas.","texte_reference":"SR/R — 1 PA — 1/Scène — Prérequis : Lecture des méridiens. Sur soi-même ou une cible consentante au contact, relancer immédiatement une fonction vitale bloquée surnaturellement : respiration, circulation, mouvement d’un membre ou conscience physiologique. L’effet suspend pendant un round une altération extérieure qui empêchait cette fonction ; il ne soigne pas la blessure ni une destruction anatomique réelle. Décale d’un cran vers Yang.\nConditions de résolution : 1 PA, 1/scène, contact et consentement ; suspension d’une seule altération extérieure, un cran Yang.","lore":"Le Yang relance ce qu’une influence surnaturelle a forcé à s’arrêter dans le corps. Respiration, circulation ou mouvement revient pour un instant parce que le flux est rouvert, même si la blessure anatomique demeure exactement là où elle était.","groupe_actuel":"Taoïstes — Gu, Shimazu et secrets Shi › Voie du Yang","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'taoistes_gu_shimazu_et_secrets_shi_voie_du_yang_debordement_yang', 'Débordement Yang', NULL, '{"nature":"humain","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, 2 PA, 1/scène, Yang profond direct, après Barrière Yang","activation":"2 PA, rayon 3 m, 1/scène ; un jet opposé à chaque Défense occulte, recul de 3 m vers espace valide et manifestation jusqu’à fin du round ; Yang profond.","texte_court":"dans 3 m, possessions, influences maintenues et formes immatérielles : V + MS contre chaque Défense occulte. Réussite : recul de 3 m et manifestation distincte jusqu''à la fin du round. Ne détruit rien.","texte_reference":"R — 2 PA — 1/Scène — Prérequis : Barrière Yang. Émettre brutalement le Qi dans une zone proche. Les possessions, influences spirituelles maintenues et formes immatérielles présentes doivent vaincre Volonté + Maîtrise spirituelle ou être repoussées de quelques mètres et rendues distinctement manifestes jusqu’à la fin du round. Ne les détruit pas. Décale directement vers Yang profond.\nConditions de résolution : 2 PA, rayon 3 m, 1/scène ; un jet opposé à chaque Défense occulte, recul de 3 m vers espace valide et manifestation jusqu’à fin du round ; Yang profond.","lore":"Au Yang profond, le Qi déborde du corps et pousse au-dehors ce qui s’y maintenait sans chair. Possessions et formes immatérielles sont forcées de se manifester ou de reculer, sans être détruites par cette simple explosion de présence.","groupe_actuel":"Taoïstes — Gu, Shimazu et secrets Shi › Voie du Yang","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'humain', 'humain_taoistes_harmonie', 'Harmonie', NULL, '{"nature":"humain","forme":"une_porte","forme_lot":"1 porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"aucun. Voir question 4 sur la piste."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'taoistes_gu_shimazu_et_secrets_shi_harmonie_cycle_contraire', 'Cycle contraire', NULL, '{"nature":"humain","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, passif","activation":"Une technique opposée ramène d’un cran vers Équilibre au lieu de son déplacement habituel ; ce n’est jamais un déplacement supplémentaire, une application par alternance.","texte_court":"après une technique Yin, ta prochaine technique Yang de la scène ramène le Qi d''un cran vers Équilibre au lieu de le pousser ; inversement. Une application par alternance, jamais un cran de plus.","texte_reference":"SR/R — Passif. Après avoir utilisé une technique Yin, la prochaine technique Yang utilisée avant la fin de la scène ramène d’abord le Qi d’un cran vers Équilibre au lieu de le pousser vers Yang ; inversement pour Yang puis Yin. Une seule application par enchaînement.\nConditions de résolution : Une technique opposée ramène d’un cran vers Équilibre au lieu de son déplacement habituel ; ce n’est jamais un déplacement supplémentaire, une application par alternance.","lore":"Une technique laisse derrière elle le besoin de son contraire. Le Taoïste qui répond par l’autre souffle utilise ce mouvement pour revenir vers l’Équilibre au lieu de basculer simplement de l’autre côté.","groupe_actuel":"Taoïstes — Gu, Shimazu et secrets Shi › Harmonie","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'taoistes_gu_shimazu_et_secrets_shi_harmonie_renversement_des_souffles', 'Renversement des souffles', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, réaction 1 PA, 1/scène, 10 m, après Cycle contraire","activation":"Réaction 1 PA, 1/scène ; effet visant soi ou cible à 10 m perçue, opposition à sa Puissance.","texte_court":"une altération extérieure impose une polarité opposable (accélération ou stagnation, chaud ou froid énergétique, expansion ou contraction) à toi ou à une cible perçue : V + MS contre sa Puissance. Réussite : suspendue jusqu''à la fin de la prochaine activation de sa source.","texte_reference":"SR/R — Réaction 1 PA — 1/Scène — Prérequis : Cycle contraire. Lorsqu’une altération surnaturelle extérieure impose une accélération, stagnation, chaud/froid énergétique, expansion/contraction ou autre polarité clairement opposable, le Taoïste peut en inverser brièvement la circulation. Volonté + Maîtrise spirituelle contre la Puissance de l’effet ; en réussite, l’altération est suspendue jusqu’à la fin de la prochaine activation de sa source.\nConditions de résolution : Réaction 1 PA, 1/scène ; effet visant soi ou cible à 10 m perçue, opposition à sa Puissance.","lore":"Lorsqu’une influence extérieure pousse clairement une polarité — chaleur, expansion, stagnation ou son contraire — le Taoïste retourne brièvement le sens de circulation et suspend la poussée au lieu de chercher à la détruire.","groupe_actuel":"Taoïstes — Gu, Shimazu et secrets Shi › Harmonie","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'taoistes_gu_shimazu_et_secrets_shi_harmonie_deux_souffles_un_corps', 'Deux souffles, un corps', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, passif, 1/round","activation":"1/round, payer les deux techniques puis appliquer chaque déplacement dans l’ordre, Cycle contraire compris ; aucun gel gratuit de la piste.","texte_court":"dans une même activation, une technique Yin puis une technique Yang (ou l''inverse), sans que le premier déplacement empêche la seconde. PA payés normalement ; la piste se calcule après les deux.","texte_reference":"SR/R — Passif. Une fois par round, le Taoïste peut employer dans la même activation une technique Yin puis une technique Yang, ou l’inverse, sans que le premier déplacement de Qi empêche l’usage de la seconde. Les PA sont payés normalement et le positionnement final de la piste est calculé après les deux.\nConditions de résolution : 1/round, payer les deux techniques puis appliquer chaque déplacement dans l’ordre, Cycle contraire compris ; aucun gel gratuit de la piste.","lore":"Harmonie signifie parfois accepter Yin et Yang dans la même respiration. Le Taoïste peut enchaîner les deux polarités dans une seule activation et ne calcule leur effet sur son équilibre qu’après les avoir toutes deux laissées circuler.","groupe_actuel":"Taoïstes — Gu, Shimazu et secrets Shi › Harmonie","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'taoistes_gu_shimazu_et_secrets_shi_harmonie_harmonie_imposee', 'Harmonie imposée', NULL, '{"nature":"humain","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, 2 PA au contact, 1/scène, après Lecture des méridiens et Renversement des souffles","activation":"2 PA au contact, 1/scène ; verrouiller un régime précis observé et lu, jusqu’à fin de prochaine activation, sans interdire ses pouvoirs compatibles.","texte_court":"sur une cible dont tu as lu les méridiens, V + MS contre Défense occulte. Réussite : jusqu''à la fin de sa prochaine activation, une source d''énergie surnaturelle choisie ne peut changer de forme, de polarité ou de régime. Ses pouvoirs compatibles continuent.","texte_reference":"R — 2 PA — 1/Scène — Prérequis : Lecture des méridiens + Renversement des souffles. Sur une cible au contact dont les méridiens ont été lus, Volonté + Maîtrise spirituelle contre Défense occulte. En réussite, jusqu’à la fin de sa prochaine activation, une seule source d’énergie surnaturelle active choisie doit rester stable : elle ne peut changer de forme, polarité, régime ou mode d’expression. Les pouvoirs déjà compatibles continuent ; aucune Nature n’est supprimée.\nConditions de résolution : 2 PA au contact, 1/scène ; verrouiller un régime précis observé et lu, jusqu’à fin de prochaine activation, sans interdire ses pouvoirs compatibles.","lore":"Après avoir lu les méridiens, le praticien peut forcer une énergie active à conserver le régime qu’elle possède déjà. Changer de forme, de polarité ou de mode devient momentanément impossible, sans supprimer pour autant ce qui demeure compatible avec cet état.","groupe_actuel":"Taoïstes — Gu, Shimazu et secrets Shi › Harmonie","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'humain', 'humain_taoistes_art_du_neant_des_shi', 'Art du Néant des Shi', NULL, '{"nature":"humain","forme":"une_porte","forme_lot":"1 porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"aucun. Ressort déjà distinct du Grand Scellement des Onmyoji : les Shi fixent la créature à un ancrage dans le Vide ; les Onmyoji l''enferment dans un support."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'taoistes_gu_shimazu_et_secrets_shi_art_du_neant_des_shi_vacillement_du_qi', 'Vacillement du Qi', NULL, '{"nature":"humain","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, passif, 10 m","activation":"Perception du Vacillement à 10 m sur cible perçue ; annonce uniquement l’instant d’activation, jamais identité du talent ni annulation gratuite.","texte_court":"quand une créature perçue commence à utiliser un Talent Actif, tu sens « maintenant ». Jamais quel talent ; passifs, effets autonomes et gestes physiques ne vacillent pas.","texte_reference":"SR/R — Passif — Prérequis : Lecture des méridiens. Lorsqu’une créature perçue commence à utiliser un Talent surnaturel Actif, le Shi ressent l’infime rupture de continuité produite par son activation : le Vacillement. Il sait seulement « maintenant ». Passifs, effets autonomes et actions purement physiques ne produisent normalement pas de Vacillement.\nConditions de résolution : Perception du Vacillement à 10 m sur cible perçue ; annonce uniquement l’instant d’activation, jamais identité du talent ni annulation gratuite.","lore":"Pour les Shi, l’activation surnaturelle produit un défaut minuscule dans la continuité du Qi. Ils ne savent pas encore ce qui va arriver ; ils sentent seulement l’instant exact où quelque chose vient de quitter le régime ordinaire du monde.","groupe_actuel":"Taoïstes — Gu, Shimazu et secrets Shi › Art du Néant des Shi","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'taoistes_gu_shimazu_et_secrets_shi_art_du_neant_des_shi_sceau_de_vacuite', 'Sceau de Vacuité', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, rituel de 10 minutes, scène","activation":"10 minutes, enceinte de 3 m de rayon, scène ; Puissance fixée au tracé, ancrages destructibles, sorties physiques possibles.","texte_court":"une enceinte de 3 m de rayon sur une limite réelle. Une créature contenue qui veut sortir par téléportation, immatérialité, passage spirituel, projection, abandon d''incarnation ou ouverture dimensionnelle doit vaincre ton V + MS. Elle peut marcher, casser le mur ou détruire les ancrages.","texte_reference":"SR/R — Rituel préparé — Prérequis : Vacillement du Qi. Avec temps, supports et connaissance suffisante de ce qui doit être contenu, préparer une enceinte de Vacuité attachée à une limite réelle. Une créature contenue qui veut franchir la limite par téléportation, immatérialité, passage spirituel, projection hors du corps, abandon d’incarnation ou ouverture dimensionnelle doit vaincre Volonté + Maîtrise spirituelle du Shi. Elle peut encore marcher, casser le mur ou détruire les ancrages.\nConditions de résolution : 10 minutes, enceinte de 3 m de rayon, scène ; Puissance fixée au tracé, ancrages destructibles, sorties physiques possibles.","lore":"Les Shi entourent une limite matérielle d’un vide conceptuel qui refuse les sorties surnaturelles. Téléportation, projection d’âme ou abandon d’incarnation y rencontrent le Néant, tandis qu’une créature reste libre de casser le mur ou de franchir physiquement la porte.","groupe_actuel":"Taoïstes — Gu, Shimazu et secrets Shi › Art du Néant des Shi","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'taoistes_gu_shimazu_et_secrets_shi_art_du_neant_des_shi_paume_des_shi', 'Paume des Shi', NULL, '{"nature":"humain","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, réaction 1 PA frappe comprise, 1/scène","activation":"Réaction 1 PA incluant la frappe, 1/scène ; après blessure, opposition à la Puissance pour annuler seulement la capacité déclenchante, sans silence général supplémentaire.","texte_court":"quand le Vacillement t''avertit d''une capacité déclenchée à portée de Pugilat, frappe. Blessure : V + MS contre la Puissance de la capacité ; réussite, cette activation est annulée. Rien d''autre n''est verrouillé.","texte_reference":"En réaction pour 1 PA, une fois par scène, lorsque Vacillement du Qi vous avertit d’une capacité déclenchée par une cible à portée de Pugilat, effectuez une frappe comprise dans ce PA. Après une blessure réelle, opposez Volonté + Maîtrise spirituelle à la Puissance de la capacité pour annuler cette seule activation. Aucun autre pouvoir Actif n’est verrouillé.","lore":"Le Vacillement révèle la fraction de seconde où un pouvoir quitte la continuité ordinaire. La Paume des Shi frappe exactement dans cette rupture et peut faire s’effondrer l’activation avant qu’elle ait fini de devenir réelle.","groupe_actuel":"Taoïstes — Gu, Shimazu et secrets Shi › Art du Néant des Shi","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'taoistes_gu_shimazu_et_secrets_shi_art_du_neant_des_shi_grand_scellement_des_shi', 'Grand Scellement des Shi', NULL, '{"nature":"humain","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, rituel d''une heure au moins, après Sceau de Vacuité","activation":"Voir la résolution détaillée","texte_court":"sur une créature vaincue, inconsciente, immobilisée, volontaire ou contenue, tu fixes son existence à un ancrage et l''entoures de Vacuité, contre sa Défense occulte. Tant que l''ancrage tient, elle ne peut s''échapper, se téléporter, quitter son corps, changer d''incarnation ni se reconstruire ailleurs par sa Nature. Puissances majeures : conditions de scénario fixées avant.","texte_reference":"R — Rituel prolongé — Prérequis : Sceau de Vacuité. Sur une créature vaincue, inconsciente, immobilisée, volontaire ou déjà contenue, fixer son existence manifestée à un ancrage adapté puis entourer cette fixation de Vacuité. Tant que le scellement reste intact, la cible ne peut utiliser sa propre Nature pour s’échapper, se téléporter, devenir immatérielle pour sortir, abandonner son corps, changer d’incarnation ou se reconstruire ailleurs. Les puissances majeures exigent des conditions de scénario, plusieurs maîtres, vrais noms, artefacts ou lieux appropriés.\nConditions de résolution : 1 heure minimum, cible neutralisée, ancrage concret ; opposition à la Défense occulte, maintien jusqu’à rupture de l’ancrage ; puissances majeures soumises à conditions de scénario établies.","lore":"Le Grand Scellement Shi ne cherche pas l’équilibre : il fixe une existence manifestée puis entoure cette fixation de Vacuité. Tant que l’architecture tient, la créature ne peut utiliser sa propre Nature pour abandonner corps, incarnation ou plan et réapparaître ailleurs.","groupe_actuel":"Taoïstes — Gu, Shimazu et secrets Shi › Art du Néant des Shi","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('couche', 'humain', 'humain_kabbale', 'Kabbale', NULL, '{"nature":"humain","chemin":["Kabbale"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'humain', 'humain_kabbale_rigueur_bina_gueburah_hod', 'Rigueur (Bina, Gueburah, Hod)', NULL, '{"nature":"humain","forme":"une_porte","forme_lot":"1 porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"coût d''activation d''Interdit de Bina corrigé (l''en-tête disait 2 PA, le texte validé 1 PA). **Ressort propre ajouté** : l''Interdit est prononcé et la cible doit t''entendre. Avant, il était identique à Interdit du Néant (Lueurs). Les Sephiroth sont regroupées en 4 voies (voir Grâce, Unité et rêve, Victoire) ; aucune paire n''est séparée de sa Sephira."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'kabbale_les_dix_sephiroth_gueburah_severite_arme_de_gueburah', 'Arme de Gueburah', NULL, '{"nature":"humain","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"R, 1 PA, scène","activation":"1 PA, arme tenue, scène ; interaction spirituelle et arme de Vérité, sans bonus ni objet offert.","texte_court":"une arme que tu tiens devient arme de Vérité pour la scène et peut atteindre une présence spirituelle manifestée. Aucun bonus ; attaques payées normalement.","texte_reference":"Pour 1 PA, conférez à une arme réellement tenue le caractère d’arme de Vérité pour la scène. Elle peut atteindre une présence spirituelle manifestée et accessible. Aucun objet, bonus de DGT ou autre statistique n’est créé ; les attaques restent normalement payées.","lore":"La Sévérité de Gueburah donne à une arme tenue le droit de rencontrer ce qui n’a pas toujours de chair. La consécration ne rend pas le coup plus puissant ; elle fait simplement de l’arme un instrument reconnu par la Vérité.","groupe_actuel":"Kabbale — les Dix Sephiroth › Gueburah — Sévérité","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'kabbale_les_dix_sephiroth_hod_forme_et_analyse_lecture_de_hod', 'Lecture de Hod', NULL, '{"nature":"humain","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, 1 PA, 10 m","activation":"1 PA à 10 m, effet perçu ; Esprit + Perception contre Puissance de dissimulation, pas de faiblesse ou source distante automatiquement révélée.","texte_court":"sur un effet surnaturel perçu, tu distingues sa structure : source, cible, lien de maintien, point d''intervention. Une dissimulation oppose sa Puissance à ton Esprit + Perception. Ni nom, ni faiblesse.","texte_reference":"SR/R — 1 PA. Sur un effet surnaturel perçu, distinguer sa structure active : source, cible, lien de maintien et point où une intervention surnaturelle pourrait agir, sans révéler automatiquement son nom ni sa faiblesse. Ce Talent rend ciblables des éléments métaphysiques qu’une analyse profane ne pourrait pas isoler.\nConditions de résolution : 1 PA à 10 m, effet perçu ; Esprit + Perception contre Puissance de dissimulation, pas de faiblesse ou source distante automatiquement révélée.","lore":"La Lecture de Hod révèle l’architecture plutôt que le nom. Source, cible, lien de maintien et point d’intervention deviennent des éléments distincts, assez nets pour qu’un rite puisse enfin agir sur ce qu’une analyse profane ne savait même pas désigner.","groupe_actuel":"Kabbale — les Dix Sephiroth › Hod — Forme et analyse","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'kabbale_les_dix_sephiroth_bina_limite_imposer_une_limite', 'Imposer une limite', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"Bina ; SR/R, 1 PA, 10 m, scène","activation":"1 PA à 10 m, scène ; une limite géométrique de 3 m ou une cible protégée, choisie avant jet, une seule limite active par Kabbaliste.","texte_court":"sur un phénomène actif délimitable, choisis avant le jet une limite (rayon ou seuil de 3 m, cible protégée, extension maximale) qu''il ne franchit pas sans vaincre ton V + MS. Une seule limite active ; elle ne supprime pas l''effet.","texte_reference":"SR/R — 1 PA. Sur un phénomène surnaturel actif et clairement délimitable, définir une limite simple qu’il ne peut franchir sans vaincre Volonté + Maîtrise spirituelle : rayon, seuil, cible interdite, extension maximale, etc. La limite ne peut contredire totalement la Nature de l’effet ni le supprimer.\nConditions de résolution : 1 PA à 10 m, scène ; une limite géométrique de 3 m ou une cible protégée, choisie avant jet, une seule limite active par Kabbaliste.","lore":"Bina ne détruit pas le phénomène : elle lui rappelle qu’il possède un contour. Le Kabbaliste choisit une frontière compréhensible — seuil, rayon, cible ou extension — et oblige l’effet à lutter s’il veut prétendre n’avoir aucune limite.","groupe_actuel":"Kabbale — les Dix Sephiroth › Bina — Limite","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'kabbale_les_dix_sephiroth_hod_forme_et_analyse_decomposition_de_hod', 'Décomposition de Hod', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R, 1 PA, 10 m, 1/scène, après Lecture de Hod","activation":"1 PA à 10 m, 1/scène ; composante distincte définie avant opposition, suspension courte.","texte_court":"V + MS contre la Puissance d''un effet composite : une composante choisie avant (camouflage et protection, lien et douleur, projection et contrôle) en est séparée jusqu''à la fin de la prochaine activation de sa source.","texte_reference":"R — 1 PA — 1/Scène — Prérequis : Lecture de Hod. Volonté + Maîtrise spirituelle contre la Puissance de l’effet. En réussite, séparer une composante choisie d’un effet composite jusqu’à la fin de la prochaine activation de sa source : dissocier camouflage et protection, lien et douleur, projection et contrôle, etc. Ne détruit pas le phénomène entier.\nConditions de résolution : 1 PA à 10 m, 1/scène ; composante distincte définie avant opposition, suspension courte.","lore":"Hod sait qu’un effet complexe est souvent plusieurs mécanismes attachés ensemble. Le Kabbaliste isole l’une de ces fonctions et la sépare momentanément du reste, comme on démonterait une pièce précise sans casser toute la machine.","groupe_actuel":"Kabbale — les Dix Sephiroth › Hod — Forme et analyse","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'kabbale_les_dix_sephiroth_bina_limite_interdit_de_bina', 'Interdit de Bina', NULL, '{"nature":"humain","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, 1 PA, 10 m, 1/scène","activation":"Aligner à 1 PA, 3 PTV, 1/scène, 10 m ; capacité Active déjà observée, opposition occulte, interdiction jusqu’à fin de prochaine activation.","texte_court":"tu prononces la limite à voix haute ; la cible doit pouvoir t''entendre. Sur une capacité Active vue ou identifiée, V + MS contre sa Défense occulte. Réussite : elle ne peut être activée jusqu''à la fin de la prochaine activation de la cible. Jamais une Nature, un passif ou une ressource.","texte_reference":"R — 1 PA — 1/Scène. Après avoir vu ou correctement identifié une capacité surnaturelle Active précise, Volonté + Maîtrise spirituelle contre la Défense occulte de la cible, à 10 m. En réussite, cette capacité ne peut être activée jusqu’à la fin de la prochaine activation de la cible. Ne vise pas Nature, passif fondamental ou ressource.\nConditions de résolution : 1 PA, 1/scène, 10 m ; capacité Active déjà observée, opposition occulte, interdiction jusqu’à fin de prochaine activation.","lore":"Après avoir réellement vu une capacité à l’œuvre, le Kabbaliste peut lui opposer la Limite sous sa forme la plus sévère. Pendant un bref instant, Bina affirme que cette activation précise n’a plus sa place parmi les possibles.","groupe_actuel":"Kabbale — les Dix Sephiroth › Bina — Limite","statut_regle":"correction","changements":"coût d''activation d''Interdit de Bina corrigé (l''en-tête disait 2 PA, le texte validé 1 PA). **Ressort propre ajouté** : l''Interdit est prononcé et la cible doit t''entendre. Avant, il était identique à Interdit du Néant (Lueurs). Les Sephiroth sont regroupées en 4 voies (voir Grâce, Unité et rêve, Victoire) ; aucune paire n''est séparée de sa Sephira."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'kabbale_les_dix_sephiroth_gueburah_severite_breche_de_gueburah', 'Brèche de Gueburah', NULL, '{"nature":"humain","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, 1/scène, sans PA, après Arme de Gueburah","activation":"1/scène ; attaque normalement payée, pas de PA ajouté, une Protection active suspendue brièvement.","texte_court":"après une attaque réussie de l''Arme de Gueburah contre une barrière ou Protection active, renonce aux dégâts : V + MS contre sa Puissance. Réussite : suspendue jusqu''à la fin de la prochaine activation de sa source.","texte_reference":"R — 1/Scène — Prérequis : Arme de Gueburah. Après une attaque réussie de l’Arme de Gueburah contre une barrière ou Protection surnaturelle active, renoncer aux dégâts ordinaires et opposer Volonté + Maîtrise spirituelle à la Puissance de la Protection. En réussite, elle est suspendue jusqu’à la fin de la prochaine activation de sa source.\nConditions de résolution : 1/scène ; attaque normalement payée, pas de PA ajouté, une Protection active suspendue brièvement.","lore":"Une protection surnaturelle frappée par l’Arme de Gueburah peut devenir le véritable adversaire du coup. Le Kabbaliste renonce à blesser derrière le rempart et concentre toute la Sévérité sur l’ouverture d’une brèche temporaire.","groupe_actuel":"Kabbale — les Dix Sephiroth › Gueburah — Sévérité","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'humain', 'humain_kabbale_grace_hokhma_hesed_tiph_ereth', 'Grâce (Hokhma, Hesed, Tiph''ereth)', NULL, '{"nature":"humain","forme":"une_porte","forme_lot":"1 porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"en-tête de Sacrifice de Tiph''ereth complété (réaction 1 PA). Ressorts déjà distincts : Sceau de pureté est le seul à couvrir la mutation ; Sursis de Hesed sauve un allié, Quête inachevée (Table Ronde) se sauve soi-même tant que la Quête tient."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'kabbale_les_dix_sephiroth_tiphereth_harmonie_et_offrande_offrande_de_tiphereth', 'Offrande de Tiph''ereth', NULL, '{"nature":"humain","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, 1/scène, sans PA","activation":"Sans PA supplémentaire au rite, 1 PV irréductible, 1/scène, petit composant symbolique seulement.","texte_court":"lors d''un rite de Vérité, perds volontairement 1 PV irréductible pour remplacer un petit composant symbolique manquant, si l''équivalence est cohérente. Jamais un artefact ni une condition majeure.","texte_reference":"SR/R — 1/Scène. Lors d’un rite de Vérité, le Kabbaliste peut payer immédiatement un coût symbolique réel par une perte volontaire de 1 PV, qui ne peut être réduite ni transférée. Cette offrande peut remplacer un petit composant symbolique manquant si l’équivalence est cohérente ; elle ne remplace jamais un artefact ou une condition majeure.\nConditions de résolution : Sans PA supplémentaire au rite, 1 PV irréductible, 1/scène, petit composant symbolique seulement.","lore":"Tiph’ereth accepte parfois la chair du praticien comme symbole lorsque manque un petit composant du rite. Le sang versé ne remplace jamais l’unique relique indispensable ; il vaut seulement lorsque l’offrande possède vraiment le même sens rituel.","groupe_actuel":"Kabbale — les Dix Sephiroth › Tiph’ereth — Harmonie et offrande","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'kabbale_les_dix_sephiroth_hokhma_purete_purification_de_hokhma', 'Purification de Hokhma', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, 1 PA au contact","activation":"1 PA au contact ; supprimer un effet autonome de Puissance 12 maximum, sinon suspendre pour la scène sur opposition ; aucun point de Corruption retiré implicitement.","texte_court":"sur une pollution spirituelle, corruption extérieure ou effet impur présent, V + MS contre sa Puissance. Réussite : supprimé si sa Puissance est de 12 au plus, sinon suspendu pour la scène. Ne retire aucun point de Corruption, ni une Nature.","texte_reference":"SR/R — 1 PA. Sur une pollution spirituelle, corruption extérieure ou effet impur mineur actuellement présent, Volonté + Maîtrise spirituelle contre sa Puissance. En réussite, l’effet est supprimé s’il est mineur ou suspendu jusqu’à la fin de la scène s’il est plus fort. Ne retire jamais une Nature ou transformation devenue intrinsèque.\nConditions de résolution : 1 PA au contact ; supprimer un effet autonome de Puissance 12 maximum, sinon suspendre pour la scène sur opposition ; aucun point de Corruption retiré implicitement.","lore":"Hokhma traite la corruption extérieure comme quelque chose qui s’est ajouté au monde et peut donc en être retiré. Les souillures légères se dissipent ; les plus fortes sont tenues en silence sans que la Pureté confonde jamais une Nature intrinsèque avec une maladie.","groupe_actuel":"Kabbale — les Dix Sephiroth › Hokhma — Pureté","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'kabbale_les_dix_sephiroth_hokhma_purete_sceau_de_purete', 'Sceau de pureté', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, rituel de 10 minutes, scène","activation":"10 minutes, une personne/objet au contact ou rayon 3 m, scène ; première tentative pour tout le sceau, sans multiplier les défenses par occupant.","texte_court":"une personne ou un objet au contact, ou un rayon de 3 m. La première tentative extérieure par round de corruption, possession ou mutation hostile doit d''abord vaincre ton V + MS.","texte_reference":"SR/R — Rituel. Consacrer une personne, un objet ou une petite zone pour la scène. La première tentative extérieure par round de corruption, possession ou mutation surnaturelle hostile doit d’abord vaincre Volonté + Maîtrise spirituelle du Kabbaliste.\nConditions de résolution : 10 minutes, une personne/objet au contact ou rayon 3 m, scène ; première tentative pour tout le sceau, sans multiplier les défenses par occupant.","lore":"Le Sceau de Pureté prépare une personne, un objet ou un lieu à refuser ce qui voudrait le corrompre de l’extérieur. La première intrusion de chaque instant doit franchir cette clarté avant de pouvoir commencer son propre travail.","groupe_actuel":"Kabbale — les Dix Sephiroth › Hokhma — Pureté","statut_regle":"correction","changements":"en-tête de Sacrifice de Tiph''ereth complété (réaction 1 PA). Ressorts déjà distincts : Sceau de pureté est le seul à couvrir la mutation ; Sursis de Hesed sauve un allié, Quête inachevée (Table Ronde) se sauve soi-même tant que la Quête tient."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'kabbale_les_dix_sephiroth_hesed_grace_main_de_hesed', 'Main de Hesed', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, réaction 1 PA, 1/scène par cible, 10 m","activation":"Réaction 1 PA, 1/scène/cible à 10 m ; nouvelle résistance complète contre la même Puissance avant conséquence, résultat définitif.","texte_court":"un allié va subir une conséquence surnaturelle non létale immédiate (chute spirituelle, expulsion, emprise, affliction) : il fait une nouvelle résistance complète contre la même Puissance. Résultat définitif ; n''annule pas des dégâts reçus.","texte_reference":"SR/R — Réaction 1 PA — 1/Scène/cible. Lorsqu’un allié proche devrait subir une conséquence surnaturelle non létale immédiate — chute spirituelle, expulsion, emprise, affliction — le Kabbaliste peut lui offrir une seconde issue : nouvelle Défense occulte ou résistance appropriée. Le Talent n’annule pas des dégâts physiques déjà reçus.\nConditions de résolution : Réaction 1 PA, 1/scène/cible à 10 m ; nouvelle résistance complète contre la même Puissance avant conséquence, résultat définitif.","lore":"Hesed offre une seconde issue au compagnon que le surnaturel vient de pousser vers une conséquence immédiate. La Main ne nie pas ce qui s’est passé ; elle retient assez la chute pour permettre une nouvelle résistance.","groupe_actuel":"Kabbale — les Dix Sephiroth › Hesed — Grâce","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'kabbale_les_dix_sephiroth_hesed_grace_sursis_de_hesed', 'Sursis de Hesed', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R, réaction 1 PA, 1/scène, 10 m","activation":"Réaction 1 PA, 1/scène, allié à 10 m ; maintien jusqu’à fin de prochaine activation sans PV ni actions rendues, un seul effet de report par mort.","texte_court":"un allié va franchir son seuil de Mort à cause d''un effet surnaturel : son âme et son corps tiennent ensemble jusqu''à la fin de sa prochaine activation. Aucun PV rendu ; s''il n''est pas stabilisé avant, la mort suit.","texte_reference":"R — Réaction 1 PA — 1/Scène. Lorsqu’un allié devrait franchir son seuil de Mort à cause d’un effet surnaturel, maintenir son âme et son corps ensemble jusqu’à la fin de sa prochaine activation. Aucun PV n’est restauré ; si la cible n’est pas stabilisée ou sauvée avant l’expiration, la mort suit normalement.\nConditions de résolution : Réaction 1 PA, 1/scène, allié à 10 m ; maintien jusqu’à fin de prochaine activation sans PV ni actions rendues, un seul effet de report par mort.","lore":"Le Sursis de Hesed refuse que l’âme se sépare du corps pendant les quelques secondes où un secours reste encore possible. La blessure demeure entière, mais la mort attend jusqu’à la prochaine occasion de sauver réellement la personne.","groupe_actuel":"Kabbale — les Dix Sephiroth › Hesed — Grâce","statut_regle":"correction","changements":"en-tête de Sacrifice de Tiph''ereth complété (réaction 1 PA). Ressorts déjà distincts : Sceau de pureté est le seul à couvrir la mutation ; Sursis de Hesed sauve un allié, Quête inachevée (Table Ronde) se sauve soi-même tant que la Quête tient."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'kabbale_les_dix_sephiroth_tiphereth_harmonie_et_offrande_sacrifice_de_tiphereth', 'Sacrifice de Tiph''ereth', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R, réaction 1 PA, 1/scène, 10 m, après Offrande","activation":"Réaction 1 PA, 1/scène, allié à 10 m ; devenir cible valide avant résolution, avec ses protections normales ; pas de zone ni duplication.","texte_court":"une conséquence surnaturelle vise un allié ; si tu es une cible valide, tu la subis entièrement à sa place, avec tes protections. Pas contre une zone.","texte_reference":"R — 1/Scène — Prérequis : Offrande de Tiph’ereth. Accepter volontairement une conséquence surnaturelle destinée à un allié proche si le Kabbaliste constitue une cible valide. Il subit l’effet complet à sa place. Ne fonctionne pas sur une zone ni sur un effet dont la cible est intrinsèquement spécifique.\nConditions de résolution : Réaction 1 PA, 1/scène, allié à 10 m ; devenir cible valide avant résolution, avec ses protections normales ; pas de zone ni duplication.","lore":"Le Sacrifice de Tiph’ereth fait de l’harmonie une substitution volontaire. Si le Kabbaliste peut réellement recevoir l’effet destiné à son allié, il se place dans sa trajectoire spirituelle et en accepte l’intégralité.","groupe_actuel":"Kabbale — les Dix Sephiroth › Tiph’ereth — Harmonie et offrande","statut_regle":"correction","changements":"en-tête de Sacrifice de Tiph''ereth complété (réaction 1 PA). Ressorts déjà distincts : Sceau de pureté est le seul à couvrir la mutation ; Sursis de Hesed sauve un allié, Quête inachevée (Table Ronde) se sauve soi-même tant que la Quête tient."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'humain', 'humain_kabbale_unite_et_reve_kether_yessod_malkhouth', 'Unité et rêve (Kether, Yessod, Malkhouth)', NULL, '{"nature":"humain","forme":"une_porte","forme_lot":"1 porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"bloc d''Accès de toute la Kabbale sorti d''Incarner de force vers l''en-tête (correction)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'kabbale_les_dix_sephiroth_yessod_image_et_reve_image_de_yessod', 'Image de Yessod', NULL, '{"nature":"humain","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, 1 PA, 10 m, scène","activation":"1 PA à 10 m, image visuelle dans un cube de 2 m pour la scène ; doute motivé : Esprit + Perception contre Puissance initiale, aucune substance.","texte_court":"une image surnaturelle simple dans un cube de 2 m, attachée à un support, un lieu ou une personne consentante : forme, symbole, message ou apparence. Aucune substance ; un doute motivé oppose Esprit + Perception à sa Puissance.","texte_reference":"SR/R — 1 PA — Scène. Créer une image surnaturelle simple attachée à un support, lieu ou personne consentante. Elle peut transmettre une forme, un symbole, un message ou une apparence superficielle et résiste aux incohérences d’un simple hologramme technique. Elle n’a aucune substance et ne trompe pas automatiquement une perception de Vérité.\nConditions de résolution : 1 PA à 10 m, image visuelle dans un cube de 2 m pour la scène ; doute motivé : Esprit + Perception contre Puissance initiale, aucune substance.","lore":"Yessod attache au monde une image simple qui ne dépend pas d’un projecteur. Symbole, message ou apparence superficielle demeure sur son support avec une cohérence surnaturelle, mais sans substance et sans pouvoir tromper automatiquement un regard de Vérité.","groupe_actuel":"Kabbale — les Dix Sephiroth › Yessod — Image et rêve","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'kabbale_les_dix_sephiroth_kether_unite_nud_de_kether', 'Nœud de Kether', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, 1 PA, scène","activation":"1 PA, trois volontaires à 10 m lors du lien ; scène et rayon de liaison 100 m ; une Puissance commune, aucune télépathie ajoutée.","texte_court":"lie jusqu''à 3 volontaires à 10 m (puis 100 m de liaison). Toute tentative de les isoler, de leur faire s''oublier ou de leur imposer des réalités incompatibles doit d''abord vaincre ton V + MS. Aucune télépathie.","texte_reference":"SR/R — 1 PA — Scène. Lier jusqu’à trois personnes consentantes comme un même ensemble symbolique. Une tentative surnaturelle visant à isoler spirituellement l’une d’elles, leur faire oublier mutuellement leur existence, séparer artificiellement leurs consciences ou leur imposer des réalités mutuellement incompatibles doit d’abord vaincre Volonté + Maîtrise spirituelle du Kabbaliste.\nConditions de résolution : 1 PA, trois volontaires à 10 m lors du lien ; scène et rayon de liaison 100 m ; une Puissance commune, aucune télépathie ajoutée.","lore":"Le Nœud de Kether unit symboliquement quelques volontés consentantes. Une force qui voudrait les isoler spirituellement, leur faire nier mutuellement leur existence ou leur imposer des réalités incompatibles rencontre d’abord cette unité construite.","groupe_actuel":"Kabbale — les Dix Sephiroth › Kether — Unité","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'kabbale_les_dix_sephiroth_kether_unite_concordance_de_kether', 'Concordance de Kether', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, 1 PA, 1/scène, après Nœud de Kether","activation":"2 PTV et 1/scène ; 1 PA, seulement contradictions réellement perçues par les membres encore liés.","texte_court":"quand des membres du Nœud perçoivent ou se souviennent d''une scène de façon surnaturellement contradictoire, tu obtiens un fait commun à toutes les versions (personne présente, objet absent, son, direction). Pas quelle version est vraie.","texte_reference":"SR/R — 1 PA — 1/Scène — Prérequis : Nœud de Kether. Lorsque plusieurs membres du Nœud perçoivent ou se souviennent d’une situation de manière surnaturellement contradictoire, obtenir un fait invariant réellement commun à toutes les versions : personne présente, objet absent, même son, direction ou événement. Ne dit pas quelle version complète est vraie.\nConditions de résolution : 1/scène ; 1 PA, seulement contradictions réellement perçues par les membres encore liés.","lore":"Quand plusieurs perceptions surnaturelles se contredisent, Kether cherche ce qu’aucune version n’a réussi à modifier. Le Nœud fait émerger ce fait commun — présence, absence, son ou événement — sans décider à lui seul quel récit complet mérite confiance.","groupe_actuel":"Kabbale — les Dix Sephiroth › Kether — Unité","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'kabbale_les_dix_sephiroth_yessod_image_et_reve_marche_onirique', 'Marche onirique', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R, rituel de 10 minutes, 1/scène","activation":"10 minutes, dormeur à 1 km maximum avec lien réel, durée 10 minutes ; corps de l’officiant inerte, rupture du consentement termine la visite.","texte_court":"entre 10 minutes dans le rêve d''un dormeur consentant à 1 km au plus, connu ou lié par un support. Tu communiques et observes ses symboles ; ni souvenirs cachés, ni contrôle. Ton corps reste inerte.","texte_reference":"R — Rituel / 1/Scène. Entrer dans le rêve d’une cible consentante endormie connue ou liée par un support pertinent. Le Kabbaliste peut y communiquer et observer les symboles produits par le rêve réel ; il ne lit pas automatiquement des souvenirs cachés et ne peut imposer un contrôle durable.\nConditions de résolution : 10 minutes, dormeur à 1 km maximum avec lien réel, durée 10 minutes ; corps de l’officiant inerte, rupture du consentement termine la visite.","lore":"Le Kabbaliste rejoint le rêve d’une personne consentante par un lien réel avec elle. Il y parle et observe les images que le dormeur produit lui-même, visiteur d’un paysage intime plutôt que voleur automatique de souvenirs cachés.","groupe_actuel":"Kabbale — les Dix Sephiroth › Yessod — Image et rêve","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'kabbale_les_dix_sephiroth_malkhouth_royaume_et_incarnation_ancrage_de_malkhouth', 'Ancrage de Malkhouth', NULL, '{"nature":"humain","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, rituel de 10 minutes, scène","activation":"10 minutes au contact d’un support, cible à 10 m ; opposition occulte, ancrage pour la scène, aucune immobilisation physique.","texte_court":"fixe une manifestation spirituelle ou projetée à 10 m à un lieu ou un support pour qu''elle ne puisse cesser d''être présente pour éviter l''échange. Opposition si elle résiste. Ne l''immobilise pas.","texte_reference":"R — Rituel. Fixer temporairement une manifestation surnaturelle, spirituelle ou projetée à un lieu ou support réel afin qu’elle ne puisse simplement cesser d’être présente pour éviter l’interaction. Volonté + Maîtrise spirituelle contre la source si elle résiste. L’Ancrage ne l’immobilise pas physiquement et n’interdit pas une vraie fuite.\nConditions de résolution : 10 minutes au contact d’un support, cible à 10 m ; opposition occulte, ancrage pour la scène, aucune immobilisation physique.","lore":"Malkhouth donne au surnaturel une adresse dans le Royaume. Une manifestation projetée ou spirituelle est fixée à un lieu ou support réel et ne peut plus simplement cesser d’être présente pour éviter l’interaction, même si elle reste libre de fuir normalement.","groupe_actuel":"Kabbale — les Dix Sephiroth › Malkhouth — Royaume et incarnation","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'kabbale_les_dix_sephiroth_malkhouth_royaume_et_incarnation_incarner_de_force', 'Incarner de force', NULL, '{"nature":"humain","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, 2 PA, 10 m, 1/scène, après Ancrage de Malkhouth","activation":"2 PA à 10 m, 1/scène ; incarnation jusqu’à fin de prochaine activation, attaques et protections résolues normalement.","texte_court":"sur une entité Ancrée, V + MS contre Défense occulte. Réussite : jusqu''à la fin de sa prochaine activation, elle prend une forme assez corporelle pour être ciblée physiquement.","texte_reference":"R — 2 PA — 1/Scène — Prérequis : Ancrage de Malkhouth. Sur une entité spirituelle, projetée ou partiellement immatérielle déjà Ancrée, Volonté + Maîtrise spirituelle contre Défense occulte. En réussite, elle doit adopter jusqu’à la fin de sa prochaine activation une manifestation suffisamment corporelle pour être ciblée par les interactions physiques compatibles. Ne force pas une entité totalement absente à apparaître. Accès : N pour un initié ; O/R pour une formation extérieure crédible ; Sephirien X en progression PJ.\nConditions de résolution : 2 PA à 10 m, 1/scène ; incarnation jusqu’à fin de prochaine activation, attaques et protections résolues normalement.","lore":"Une entité déjà Ancrée peut être poussée plus loin vers l’incarnation. Malkhouth l’oblige brièvement à présenter assez de corps au monde pour recevoir les interactions physiques auxquelles son état immatériel échappait jusque-là.","groupe_actuel":"Kabbale — les Dix Sephiroth › Malkhouth — Royaume et incarnation","statut_regle":"correction","changements":"bloc d''Accès de toute la Kabbale sorti d''Incarner de force vers l''en-tête (correction)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'humain', 'humain_kabbale_victoire_nesah', 'Victoire (Nesah)', NULL, '{"nature":"humain","forme":"progression","forme_lot":"progression (courte)","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"« ouverture » précisée par les exemples du texte (brèche, passage, cible matérialisée, lien rompu, Protection suspendue), comme pour Formes complémentaires (Table Ronde). Aucune autre définition ajoutée."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'kabbale_les_dix_sephiroth_nesah_victoire_elan_de_nesah', 'Élan de Nesah', NULL, '{"nature":"humain","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, réaction 1 PA, 1/round, 10 m","activation":"Réaction 1 PA, 1/round, ouverture à 10 m ; une seule prolongation par ouverture, jusqu’à fin de prochaine activation, sans prolonger dégâts ou contrôle.","texte_court":"quand un allié crée une ouverture temporaire dans un phénomène surnaturel (brèche, passage, cible matérialisée, lien rompu, Protection suspendue), elle reste ouverte jusqu''à la fin de ta prochaine activation. Ni dégâts ni contrôle prolongés.","texte_reference":"SR/R — Réaction 1 PA — 1/round. Lorsqu’un personnage proche obtient une réussite qui crée une ouverture temporaire dans un phénomène surnaturel — brèche, passage, cible matérialisée, lien rompu, Protection entrouverte — fixer cette ouverture jusqu’à la fin de la prochaine activation du Kabbaliste. Ne prolonge ni dégâts ni contrôle mental.\nConditions de résolution : Réaction 1 PA, 1/round, ouverture à 10 m ; une seule prolongation par ouverture, jusqu’à fin de prochaine activation, sans prolonger dégâts ou contrôle.","lore":"Une réussite qui ouvre brièvement une brèche peut être empêchée de retomber immédiatement. Le Kabbaliste fixe cet instant favorable et laisse au groupe le temps de l’exploiter avant que le monde ne reprenne sa forme.","groupe_actuel":"Kabbale — les Dix Sephiroth › Nesah — Victoire","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'kabbale_les_dix_sephiroth_nesah_victoire_victoire_contagieuse', 'Victoire contagieuse', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, passif","activation":"Deux alliés au maximum, toujours leurs propres PA et un moyen réel d’exploiter l’ouverture.","texte_court":"jusqu''à 2 autres alliés peuvent exploiter l''ouverture que tu maintiens, avec leurs PA et un moyen réel. Rien n''est offert.","texte_reference":"SR/R — Passif — Prérequis : Élan de Nesah. Une ouverture maintenue par Élan de Nesah peut être exploitée par jusqu’à deux autres alliés comme si elle était encore naturellement disponible. Aucun jet, attaque ou succès n’est offert gratuitement.\nConditions de résolution : Deux alliés au maximum, toujours leurs propres PA et un moyen réel d’exploiter l’ouverture.","lore":"Nesah fait circuler une ouverture comme une victoire dont plusieurs compagnons peuvent profiter. Ce qui a été entrouvert par l’un reste exploitable par quelques autres avant que le phénomène surnaturel ne se referme complètement.","groupe_actuel":"Kabbale — les Dix Sephiroth › Nesah — Victoire","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('couche', 'humain', 'humain_nizarites_asasiyun', 'Nizarites / Asāsīyūn', NULL, '{"nature":"humain","chemin":["Nizarites / Asāsīyūn"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'humain', 'humain_nizarites_asasiyun_arts_du_djinn', 'Arts du Djinn', NULL, '{"nature":"humain","forme":"une_porte","forme_lot":"1 porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"l''entrée garde son coût d''origine (2 PTV). Ressort déjà distinct du Shikigami (Onmyoji) : un Djinn a accepté un pacte et fusionne avec son maître ; un Shikigami peut être créé et porte des sceaux."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'nizarites_asasiyun_arts_du_djinn_et_doctrine_de_chasse_arts_du_djinn_pacte_du_djinn', 'Pacte du Djinn', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"entree","porte":null,"palier_double":null,"acces":"R, lien","activation":"Enregistrer référence de PNJ, accord et limites ; aucun Djinn créé par l’achat ni PA indépendant.","texte_court":"lien avec un Djinn compatible réellement rencontré, qui a accepté le pacte. Il suit les règles des Compagnons liés. L''achat ne crée pas le Djinn.","texte_reference":"R — Lien surnaturel. Établir un lien avec un Djinn compatible réellement rencontré et ayant accepté le pacte. Le Djinn est un compagnon réel et suit toutes les règles des Compagnons liés.\nConditions de résolution : Enregistrer référence de PNJ, accord et limites ; aucun Djinn créé par l’achat ni PA indépendant.","lore":"Un Djinn n’est ni acheté avec des PTV ni produit par un rite abstrait. Le Pacte fixe dans la Vérité une relation déjà consentie avec une créature réellement rencontrée, compagnon dont les désirs et les risques continuent d’exister hors du personnage.","groupe_actuel":"Nizarites / Asāsīyūn — Arts du Djinn et doctrine de chasse › Arts du Djinn","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'nizarites_asasiyun_arts_du_djinn_et_doctrine_de_chasse_arts_du_djinn_voix_du_compagnon', 'Voix du compagnon', NULL, '{"nature":"humain","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"Communication à 100 m, perception par ses sens pour 1 PA jusqu’à prochaine activation, même plan.","texte_court":"communication simple à 100 m, même plan. Pour 1 PA, tu perçois par ses sens jusqu''à ta prochaine activation.","texte_reference":"V/SR/R — Passif / 1 PA. Communication volontaire simple ; pour 1 PA, percevoir à travers les sens réels du Djinn.\nConditions de résolution : Communication à 100 m, perception par ses sens pour 1 PA jusqu’à prochaine activation, même plan.","lore":"Le lien du pacte commence comme une conversation qui n’a pas besoin de voix. En se concentrant davantage, le Nizarite peut aussi ouvrir ses perceptions sur celles du Djinn et regarder momentanément le monde depuis son compagnon.","groupe_actuel":"Nizarites / Asāsīyūn — Arts du Djinn et doctrine de chasse › Arts du Djinn","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'nizarites_asasiyun_arts_du_djinn_et_doctrine_de_chasse_arts_du_djinn_sens_jumeles', 'Sens jumelés', NULL, '{"nature":"humain","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, passif, après Voix du compagnon","activation":"Réutiliser portée/durée de Voix du compagnon, actions et défenses sur les PA du Nizarite.","texte_court":"ce que tu perçois par ton Djinn sert à cibler, réagir ou te défendre, avec un moyen valide et tes PA.","texte_reference":"SR/R — Passif — Prérequis : Voix du compagnon. Lorsque le Nizarite perçoit à travers son Djinn, ces perceptions peuvent servir à cibler, réagir ou défendre. L’action nécessite toujours un moyen physique ou surnaturel valide.\nConditions de résolution : Réutiliser portée/durée de Voix du compagnon, actions et défenses sur les PA du Nizarite.","lore":"À force de partager les sens du Djinn, le Nizarite apprend à traiter ce qu’il perçoit par lui comme une perception exploitable. Il peut viser ou défendre à partir de ce regard emprunté si son propre corps possède encore un moyen valable d’agir.","groupe_actuel":"Nizarites / Asāsīyūn — Arts du Djinn et doctrine de chasse › Arts du Djinn","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'nizarites_asasiyun_arts_du_djinn_et_doctrine_de_chasse_arts_du_djinn_possession_consentie', 'Possession consentie', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R, 1 PA, 1/scène","activation":"Choisir à l’achat une propriété réelle non chiffrée librement ; résistances plafonnées à Protection 3 typée, aucune copie d’Attribut/PA.","texte_court":"le Djinn fusionne avec toi pour la scène et te prête une propriété réelle choisie à l''achat (résistance plafonnée à Protection 3 typée, respiration, mouvement, perception ou contact élémentaire). Ni fiche, ni Attributs, ni PA.","texte_reference":"R — 1 PA — 1/Scène. Le Djinn fusionne volontairement avec le Nizarite pour la scène et lui confère une Manifestation prédéterminée correspondant à une propriété réelle du Djinn : résistance, respiration, mouvement, perception ou contact élémentaire. Pas de fiche complète du compagnon.\nConditions de résolution : Choisir à l’achat une propriété réelle non chiffrée librement ; résistances plafonnées à Protection 3 typée, aucune copie d’Attribut/PA.","lore":"Le Djinn entre volontairement dans son partenaire et superpose une part de sa Nature au corps humain. Une résistance, un mode de mouvement ou une perception définie devient accessible sans que le Nizarite cesse d’être lui-même ni obtienne la fiche complète de l’esprit.","groupe_actuel":"Nizarites / Asāsīyūn — Arts du Djinn et doctrine de chasse › Arts du Djinn","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'nizarites_asasiyun_arts_du_djinn_et_doctrine_de_chasse_arts_du_djinn_rappel_durgence', 'Rappel d''urgence', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R, réaction 1 PA, après Déchaîner le Djinn","activation":"Réaction 1 PA remplaçant l’activation de Déchaîner le Djinn ; même usage partagé de 1/scène, aucune interception gratuite.","texte_court":"Déchaîner le Djinn en réaction, sur son usage de la scène. Aucune action gratuite, aucune interception automatique.","texte_reference":"R — Réaction 1 PA — 1/Scène — Prérequis : Déchaîner le Djinn. Utiliser Déchaîner le Djinn comme Réaction plutôt que comme activation normale. Ne fournit aucune action gratuite au compagnon et ne constitue pas une interception automatique.\nConditions de résolution : Réaction 1 PA remplaçant l’activation de Déchaîner le Djinn ; même usage partagé de 1/scène, aucune interception gratuite.","lore":"Le pacte peut être tiré comme une corde lorsque le danger n’attend pas. Le Nizarite rappelle son Djinn au cœur d’une réaction défensive, sans que cette urgence donne au compagnon une action qu’il n’aurait pas dû posséder.","groupe_actuel":"Nizarites / Asāsīyūn — Arts du Djinn et doctrine de chasse › Arts du Djinn","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'nizarites_asasiyun_arts_du_djinn_et_doctrine_de_chasse_arts_du_djinn_dechainer_le_djinn', 'Déchaîner le Djinn', NULL, '{"nature":"humain","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, 1 PA, 1/scène","activation":"1 PA, 1/scène, apparition à 3 m dans un espace valide ; aucune traversée de sceau ou rappel d’un mort.","texte_court":"le Djinn apparaît à 3 m depuis son refuge, dans un espace valide. Il agit avec ses statistiques sur tes PA. Ne traverse pas un sceau ; ne rappelle pas un mort.","texte_reference":"R — 1 PA — 1/Scène. Invocation liée : rappeler le Djinn près du Nizarite depuis son refuge ou état compatible. Il agit avec ses propres statistiques mais consomme les PA du Nizarite.\nConditions de résolution : 1 PA, 1/scène, apparition à 3 m dans un espace valide ; aucune traversée de sceau ou rappel d’un mort.","lore":"Le pacte permet au Nizarite d’appeler son compagnon depuis le refuge ou l’état où il attend. Le Djinn vient comme individu réel, avec ses propres capacités et sa propre volonté, mais la scène continue de compter son action dans le rythme de son partenaire.","groupe_actuel":"Nizarites / Asāsīyūn — Arts du Djinn et doctrine de chasse › Arts du Djinn","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'nizarites_asasiyun_arts_du_djinn_et_doctrine_de_chasse_arts_du_djinn_echange_dancrage', 'Échange d''ancrage', NULL, '{"nature":"humain","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, 1 PA, 1/scène, 20 m, après Déchaîner le Djinn","activation":"1 PA, 1/scène, 20 m, Djinn manifesté et consentant, même plan ; destinations valides et barrières de transport respectées.","texte_court":"toi et ton Djinn manifesté et consentant échangez vos positions, même plan, destinations valides. Une barrière anti-transport bloque. Aucun coup gratuit.","texte_reference":"R — 1 PA — 1/Scène — Prérequis : Déchaîner le Djinn. Le Nizarite et son Djinn manifesté échangent instantanément leurs positions à courte ou moyenne portée. Les deux destinations doivent être valides ; les barrières anti-transport ou ruptures dimensionnelles appropriées bloquent l’échange. Aucun coup gratuit.\nConditions de résolution : 1 PA, 1/scène, 20 m, Djinn manifesté et consentant, même plan ; destinations valides et barrières de transport respectées.","lore":"Quand les deux partenaires sont manifestés dans le même espace, le pacte sait lequel est ancré où. Un geste inverse brutalement ces deux positions, échange interdit seulement lorsque l’une des destinations n’est pas réellement viable ou qu’une barrière bloque ce type de transport.","groupe_actuel":"Nizarites / Asāsīyūn — Arts du Djinn et doctrine de chasse › Arts du Djinn","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'nizarites_asasiyun_arts_du_djinn_et_doctrine_de_chasse_arts_du_djinn_incarnation_profonde', 'Incarnation profonde', NULL, '{"nature":"humain","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, 2 PA, 1/scène, après Possession consentie","activation":"Définir une seule capacité réelle à l’achat, coût et portée écrits ; 2 PA/1 scène pour l’accueil, usages ensuite payés, aucun nouveau pool ni copie complète.","texte_court":"pendant la Possession, une capacité active signature du Djinn, fixée à l''achat avec son coût et sa portée (souffle de feu, mouvement aérien, passage aquatique). Ses usages se paient ensuite ; jamais tous ses pouvoirs.","texte_reference":"R — 2 PA — 1/Scène — Prérequis : Possession consentie. Pendant Possession consentie, manifester pour la scène une capacité active signature prédéterminée du Djinn : souffle de feu, mouvement aérien, passage aquatique, etc. Elle est fixée par la Nature réelle du compagnon et ne donne jamais l’ensemble de ses pouvoirs.\nConditions de résolution : Définir une seule capacité réelle à l’achat, coût et portée écrits ; 2 PA/1 scène pour l’accueil, usages ensuite payés, aucun nouveau pool ni copie complète.","lore":"Pendant la possession consentie, le Nizarite peut laisser une propriété plus profonde du Djinn traverser son corps. Souffle, vol, passage aquatique ou autre signature choisie apparaît comme une extension unique du compagnon, jamais comme son catalogue entier de pouvoirs.","groupe_actuel":"Nizarites / Asāsīyūn — Arts du Djinn et doctrine de chasse › Arts du Djinn","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'humain', 'humain_nizarites_asasiyun_asasiyun_marquer_la_proie', 'Asāsīyūn · Marquer la proie', NULL, '{"nature":"humain","forme":"une_porte","forme_lot":"1 porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"bloc d''Accès de toute la tradition sorti de Dernier ancrage vers l''en-tête (correction)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'nizarites_asasiyun_arts_du_djinn_et_doctrine_de_chasse_doctrine_asasiyun_marque_de_la_proie', 'Marque de la proie', NULL, '{"nature":"humain","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, 1 PA","activation":"1 PA au contact ou après blessure ; Volonté + Maîtrise spirituelle contre Défense occulte hostile ; une proie active, durée jusqu’à rupture/retrait.","texte_court":"sur une proie identifiée, touchée, blessée ou au contact d''un rite, V + MS contre sa Défense occulte : une marque invisible jusqu''à retrait, rupture ou neutralisation durable. Une seule proie ; elle ne localise pas.","texte_reference":"SR/R — 1 PA. Sur une proie correctement identifiée, touchée, blessée ou accessible à un rite proche, poser une marque surnaturelle invisible. Une seule proie à la fois. Elle persiste jusqu’à retrait, rupture volontaire ou neutralisation durable ; elle ne localise pas à elle seule.\nConditions de résolution : 1 PA au contact ou après blessure ; Volonté + Maîtrise spirituelle contre Défense occulte hostile ; une proie active, durée jusqu’à rupture/retrait.","lore":"La Marque Asāsīyūn fixe surnaturellement l’identité d’une proie déjà correctement établie. Elle persiste comme lien de chasse et sert de support à la doctrine, mais ne dit jamais seule où l’ennemi se cache.","groupe_actuel":"Nizarites / Asāsīyūn — Arts du Djinn et doctrine de chasse › Doctrine Asāsīyūn","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'nizarites_asasiyun_arts_du_djinn_et_doctrine_de_chasse_doctrine_asasiyun_fenetre_jumelee', 'Fenêtre jumelée', NULL, '{"nature":"humain","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, passif, après Fenêtre de chasse et Voix du compagnon","activation":"Portée du lien de compagnon, un seul PA du maître pour l’action de Fenêtre.","texte_court":"Fenêtre de chasse se déclenche aussi quand ton Djinn perçoit la fuite. L''action simple est faite par toi ou par lui, toujours sur ton PA.","texte_reference":"SR/R — Passif — Prérequis : Fenêtre de chasse + Voix du compagnon. Fenêtre de chasse peut se déclencher lorsque c’est le Djinn qui perçoit la tentative de fuite de la proie. L’action simple autorisée peut être réalisée par le Nizarite ou son compagnon, mais dépense toujours le PA du Nizarite.\nConditions de résolution : Portée du lien de compagnon, un seul PA du maître pour l’action de Fenêtre.","lore":"La chasse n’a pas besoin que l’œil humain soit celui qui surprend la fuite. Si le Djinn voit la proie s’échapper, le pacte transmet l’instant au Nizarite et l’un des deux peut accomplir le geste autorisé par la Fenêtre avec le même temps d’action partagé.","groupe_actuel":"Nizarites / Asāsīyūn — Arts du Djinn et doctrine de chasse › Doctrine Asāsīyūn","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'nizarites_asasiyun_arts_du_djinn_et_doctrine_de_chasse_doctrine_asasiyun_traque_du_pacte', 'Traque du pacte', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, passif, après Marque de la proie et Pacte du Djinn","activation":"10 km maximum et même plan ; direction et quatre catégories de distance seulement, anti-divination opposée à la Puissance du lien.","texte_court":"toi et ton Djinn sentez la direction de la proie marquée à 10 km au plus, même plan, et si elle est très proche, proche, loin ou très loin. Un anti-divination s''oppose à la Puissance du lien.","texte_reference":"SR/R — Passif — Prérequis : Marque de la proie + Pacte du Djinn. Le Nizarite et son Djinn perçoivent la direction générale de la proie marquée tant qu’elle se trouve dans le même plan et la même grande région, ainsi qu’une impression très proche/proche/loin/très loin. Pas de GPS, distance exacte ou adresse ; un anti-divination adapté peut bloquer.\nConditions de résolution : 10 km maximum et même plan ; direction et quatre catégories de distance seulement, anti-divination opposée à la Puissance du lien.","lore":"La Marque de la proie résonne chez les deux partenaires du Pacte. Dans la même grande région et le même plan, Nizarite et Djinn ressentent de quel côté se poursuit la chasse et si la distance paraît faible ou immense, jamais une adresse ou des coordonnées.","groupe_actuel":"Nizarites / Asāsīyūn — Arts du Djinn et doctrine de chasse › Doctrine Asāsīyūn","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'nizarites_asasiyun_arts_du_djinn_et_doctrine_de_chasse_doctrine_asasiyun_contre_rite_du_temoin', 'Contre-rite du témoin', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, réaction 1 PA, 1/scène","activation":"Réaction 1 PA, 1/scène ; comprend une Défense active OU un déplacement normal OU une préparation défensive, pas de second coût ni deuxième action.","texte_court":"une capacité Active que toi ou ton Djinn avez vue reste mémorisée pour la scène. À sa prochaine activation par la même cible, tu la sens avant résolution et fais une Défense active, un déplacement, une préparation défensive ou une action défensive du Djinn. Ni attaque ni annulation.","texte_reference":"SR/R — Réaction 1 PA — 1/Scène. Après que le Nizarite ou son Djinn a vu une cible utiliser une capacité surnaturelle Active précise, sa signature reste mémorisée pour la scène. Lors de la prochaine activation de cette même capacité par cette même cible, le Nizarite reconnaît son déclenchement avant résolution même s’il serait normalement imperceptible ; il peut Défendre activement, se déplacer vers une protection, activer une préparation ou faire agir défensivement son Djinn. Pas d’attaque gratuite ni d’annulation.\nConditions de résolution : Réaction 1 PA, 1/scène ; comprend une Défense active OU un déplacement normal OU une préparation défensive, pas de second coût ni deuxième action.","lore":"Une capacité dont le Nizarite ou son Djinn a vu le déclenchement laisse pour la scène une mémoire de gestes, de tension ou de signature. À sa prochaine ouverture, cette mémoire prévient avant la résolution et offre une véritable réaction défensive, jamais une annulation gratuite.","groupe_actuel":"Nizarites / Asāsīyūn — Arts du Djinn et doctrine de chasse › Doctrine Asāsīyūn","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'nizarites_asasiyun_arts_du_djinn_et_doctrine_de_chasse_doctrine_asasiyun_sceau_de_poursuite', 'Sceau de poursuite', NULL, '{"nature":"humain","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, réaction 1 PA, 1/scène, 20 m, après Marque de la proie","activation":"Réaction 1 PA, 1/scène, proie perçue à 20 m ; opposition à la Puissance de fuite, coûts de la tentative perdus selon sa règle.","texte_court":"la proie marquée tente téléportation, sortie du plan, immatérialité ou abandon du corps pour fuir : V + MS contre sa résistance. Réussite : la tentative échoue et ses PA sont perdus. Pas contre course, véhicule ou vol.","texte_reference":"R — Réaction 1 PA — 1/Scène — Prérequis : Marque de la proie. Lorsqu’une proie marquée tente téléportation, sortie du plan physique, immatérialité rendant la chasse impossible ou abandon du corps pour fuir, Volonté + Maîtrise spirituelle contre sa résistance appropriée. En réussite, cette tentative échoue et les PA engagés sont perdus. Ne bloque pas course, véhicule ou vol physique.\nConditions de résolution : Réaction 1 PA, 1/scène, proie perçue à 20 m ; opposition à la Puissance de fuite, coûts de la tentative perdus selon sa règle.","lore":"Lorsqu’une proie marquée tente de quitter surnaturellement la chasse, le Sceau se tend et refuse la rupture. Il ne gêne ni course, ni véhicule, ni ailes physiques : seulement les échappatoires qui voudraient supprimer d’un coup le lien avec la scène.","groupe_actuel":"Nizarites / Asāsīyūn — Arts du Djinn et doctrine de chasse › Doctrine Asāsīyūn","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'nizarites_asasiyun_arts_du_djinn_et_doctrine_de_chasse_doctrine_asasiyun_dernier_ancrage', 'Dernier ancrage', NULL, '{"nature":"humain","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, passif, après Marque de la proie et Mise à mort préparée","activation":"Sans PA ajouté à Mise à mort, blocage local pour la scène seulement.","texte_court":"une Mise à mort préparée sur une proie marquée bloque aussi pour la scène les transferts locaux d''essence (corps voisin, réceptacle local, fuite spirituelle, saut, reconstitution). Ni phylactère distant, ni clone externe, ni résurrection supérieure.","texte_reference":"R — Passif — Prérequis : Marque de la proie + Mise à mort préparée. Lorsque Mise à mort préparée réussit sur une proie marquée, les transferts locaux d’essence qu’une neutralisation ordinaire ne suffirait pas à arrêter sont bloqués pendant la scène : possession d’un corps voisin, abandon vers un réceptacle local, fuite spirituelle, saut d’essence ou reconstitution locale. Ne détruit ni phylactère distant, ni clone externe, ni résurrection supérieure. Accès : Arts du Djinn N pour un véritable Nizarite, parfois O/N pour d’autres initiés ; Doctrine Asāsīyūn N pour le Nizarite Chasseur et X tant que le personnage n’est pas réellement Chasseur. Vaanesh et entités tutélaires majeures restent hors calibrage ordinaire.\nConditions de résolution : Sans PA ajouté à Mise à mort, blocage local pour la scène seulement.","lore":"Une proie marquée et correctement mise à mort ne doit pas échapper par un corps voisin ou un réceptacle local. Le Dernier ancrage ferme ces transferts de proximité pour la scène sans prétendre atteindre un phylactère lointain ou une résurrection d’un ordre supérieur.","groupe_actuel":"Nizarites / Asāsīyūn — Arts du Djinn et doctrine de chasse › Doctrine Asāsīyūn","statut_regle":"correction","changements":"bloc d''Accès de toute la tradition sorti de Dernier ancrage vers l''en-tête (correction)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'humain', 'humain_nizarites_asasiyun_asasiyun_balles_liees', 'Asāsīyūn · Balles liées', NULL, '{"nature":"humain","forme":"une_porte","forme_lot":"1 porte (courte)","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"aucun."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'nizarites_asasiyun_arts_du_djinn_et_doctrine_de_chasse_doctrine_asasiyun_balle_liee', 'Balle liée', NULL, '{"nature":"humain","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, préparation d''une minute par munition, après Pacte du Djinn","activation":"1 minute par munition existante, une propriété élémentaire réelle sans DGT ajouté, consommée au tir.","texte_court":"une munition Angélique accordée à ton Djinn compte comme Sacrée et porte sa nature élémentaire réelle contre une vulnérabilité authentique. Consommée au tir ; aucun dégât en plus.","texte_reference":"SR/R — Préparation. Préparer une munition Angélique accordée au Djinn. Elle compte comme Sacrée/Angélique et porte également la principale nature élémentaire réelle du compagnon pour l’exploitation d’une vulnérabilité authentique. Aucun bonus de dégâts.\nConditions de résolution : 1 minute par munition existante, une propriété élémentaire réelle sans DGT ajouté, consommée au tir.","lore":"Le Nizarite prépare une munition en accord avec son Djinn. Elle reçoit le caractère Angélique du rite et la principale nature élémentaire du compagnon, combinaison utile uniquement lorsqu’une faiblesse authentique répond vraiment à l’une de ces qualités.","groupe_actuel":"Nizarites / Asāsīyūn — Arts du Djinn et doctrine de chasse › Doctrine Asāsīyūn","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'nizarites_asasiyun_arts_du_djinn_et_doctrine_de_chasse_doctrine_asasiyun_trajectoire_du_djinn', 'Trajectoire du Djinn', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, passif, après Sens jumelés et Balle liée","activation":"Une seule source de Couvert partiel ignorée, aucun mur ou projectile supplémentaire.","texte_court":"si ton Djinn voit la cible et qu''un trajet ouvert existe, ton projectile corrige une fois sa course et ignore une source de Couvert partiel. Jamais un mur, une porte fermée ou un obstacle total.","texte_reference":"SR/R — Passif — Prérequis : Sens jumelés + Balle liée. Si le Djinn voit clairement la cible et qu’un trajet matériel ouvert existe entre le tireur et elle, le projectile peut corriger surnaturellement une fois sa trajectoire et ignorer une source de Couvert partiel. Ne traverse jamais mur plein, porte fermée ou obstacle total.\nConditions de résolution : Une seule source de Couvert partiel ignorée, aucun mur ou projectile supplémentaire.","lore":"Le Djinn qui voit la cible peut guider une Balle liée au travers d’un angle partiellement couvert. Le projectile corrige une fois sa ligne comme s’il suivait le regard du compagnon, mais aucun esprit ne lui apprend à traverser un mur plein.","groupe_actuel":"Nizarites / Asāsīyūn — Arts du Djinn et doctrine de chasse › Doctrine Asāsīyūn","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'nizarites_asasiyun_arts_du_djinn_et_doctrine_de_chasse_doctrine_asasiyun_projectile_dancrage', 'Projectile d''ancrage', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R, préparation d''une minute, après Déchaîner le Djinn","activation":"1 minute par projectile ; impact à 20 m maximum du maître pour servir d’arrivée, jusqu’à fin du round ; payer l’invocation et son usage commun.","texte_court":"s''il touche une cible ou une surface à 20 m au plus, ta prochaine invocation avant la fin du round peut faire apparaître le Djinn près de l''impact. L''invocation garde son coût et ses limites.","texte_reference":"R — Préparation — Prérequis : Déchaîner le Djinn. Préparer un projectile comme point d’arrivée. S’il touche une cible ou surface, la prochaine Invocation liée avant la fin du round peut manifester le Djinn près de l’impact plutôt que près du Nizarite. L’invocation conserve son coût et ses limites ; aucune action supplémentaire.\nConditions de résolution : 1 minute par projectile ; impact à 20 m maximum du maître pour servir d’arrivée, jusqu’à fin du round ; payer l’invocation et son usage commun.","lore":"Un projectile préparé peut devenir l’endroit où le pacte accroche sa prochaine manifestation. Après l’impact, le Djinn est rappelé près de cette balise plutôt que près du Nizarite, toujours selon le coût et les limites normales de l’invocation.","groupe_actuel":"Nizarites / Asāsīyūn — Arts du Djinn et doctrine de chasse › Doctrine Asāsīyūn","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'nizarites_asasiyun_arts_du_djinn_et_doctrine_de_chasse_doctrine_asasiyun_balle_dexil', 'Balle d''exil', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R, 1/scène, sans PA","activation":"Sans PA ajouté au tir, 1/scène après blessure réelle ; hôte actuel intact.","texte_court":"une munition Angélique qui blesse une entité possessive ou parasite l''empêche d''entrer dans un nouvel hôte jusqu''à la fin de sa prochaine activation. N''expulse pas l''hôte actuel.","texte_reference":"R — 1/Scène. Une munition Angélique infligeant au moins 1 dégât réel à une entité possessive, parasite spirituel ou créature capable d’entrer dans de nouveaux hôtes l’empêche d’entrer dans un nouvel hôte jusqu’à la fin de sa prochaine activation. N’expulse pas un hôte actuel.\nConditions de résolution : Sans PA ajouté au tir, 1/scène après blessure réelle ; hôte actuel intact.","lore":"Une munition angélique peut laisser sur l’esprit touché un refus temporaire du nouvel hôte. La Balle d’exil n’arrache pas une possession déjà installée ; elle empêche la créature blessée de sauter immédiatement dans un autre corps pour prolonger sa fuite.","groupe_actuel":"Nizarites / Asāsīyūn — Arts du Djinn et doctrine de chasse › Doctrine Asāsīyūn","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('couche', 'humain', 'humain_onmyoji', 'Onmyoji', NULL, '{"nature":"humain","chemin":["Onmyoji"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'humain', 'humain_onmyoji_shikigami', 'Shikigami', NULL, '{"nature":"humain","forme":"une_porte","forme_lot":"1 porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"l''entrée garde son coût d''origine (2 PTV) ; la voie n''a pas de palier II, aucun talent de ce coût n''existant."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'onmyoji_shikigami_sceaux_et_pactes_spirituels_shikigami_lien_du_shikigami', 'Lien du Shikigami', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"entree","porte":null,"palier_double":null,"acces":"SR/R, lien","activation":"Référence du Shikigami réel, consentement/rituel établi et profil, aucun familier gratuit.","texte_court":"lien avec un Shikigami compatible réellement rencontré, ou créé selon la tradition. C''est un compagnon réel ; aucun PTV n''achète la créature.","texte_reference":"SR/R — Lien surnaturel. Établir un lien avec un Shikigami compatible réellement rencontré ou créé selon la fiction de la tradition. Le Shikigami est un compagnon réel ; aucun PTV n’achète la créature.\nConditions de résolution : Référence du Shikigami réel, consentement/rituel établi et profil, aucun familier gratuit.","lore":"Le Lien ne crée pas une créature avec des points : il formalise une relation avec un Shikigami réellement rencontré ou créé dans la tradition. À partir de là, le compagnon fait partie de l’histoire du personnage avec sa propre existence.","groupe_actuel":"Onmyoji — Shikigami, sceaux et pactes spirituels › Shikigami","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'onmyoji_shikigami_sceaux_et_pactes_spirituels_shikigami_resonance_du_shikigami', 'Résonance du Shikigami', NULL, '{"nature":"humain","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R","activation":"Communication 100 m, sens pour 1 PA jusqu’à prochaine activation, même plan.","texte_court":"communication simple à 100 m, même plan. Pour 1 PA, tu perçois par ses sens jusqu''à ta prochaine activation.","texte_reference":"SR/R — Passif / 1 PA. Résonance liée : communication volontaire simple et perception temporaire par les sens du Shikigami pour 1 PA.\nConditions de résolution : Communication 100 m, sens pour 1 PA jusqu’à prochaine activation, même plan.","lore":"La Résonance maintient entre Onmyoji et Shikigami une conversation simple même sans voix. Avec davantage d’attention, le maître peut aussi percevoir brièvement par les sens propres de son compagnon.","groupe_actuel":"Onmyoji — Shikigami, sceaux et pactes spirituels › Shikigami","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'onmyoji_shikigami_sceaux_et_pactes_spirituels_shikigami_porte_sceau', 'Porte-sceau', NULL, '{"nature":"humain","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, passif","activation":"Le PA du maître paie la pose normale, jet physique hostile nécessaire, sceau préparé réellement consommé.","texte_court":"ton Shikigami transporte des sceaux préparés. Quand tu paies 1 PA pour le faire agir, il pose un sceau sur une cible ou une surface atteignable (jet physique contre une cible hostile).","texte_reference":"SR/R — Passif. Le Shikigami peut transporter des sceaux préparés. Quand l’Onmyoji dépense un PA pour le faire agir, il peut poser un sceau sur une cible ou surface réellement atteignable. Une cible hostile exige l’action physique appropriée du Shikigami.\nConditions de résolution : Le PA du maître paie la pose normale, jet physique hostile nécessaire, sceau préparé réellement consommé.","lore":"Le Shikigami devient la main rituelle distante de son maître. Il transporte un Fūin préparé puis le pose physiquement là où il peut vraiment atteindre, y compris sur une cible hostile s’il réussit à la toucher.","groupe_actuel":"Onmyoji — Shikigami, sceaux et pactes spirituels › Shikigami","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'onmyoji_shikigami_sceaux_et_pactes_spirituels_shikigami_invocation_du_shikigami', 'Invocation du Shikigami', NULL, '{"nature":"humain","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, 1 PA, 1/scène","activation":"1 PA, 1/scène, arrivée à 3 m depuis état compatible, aucun rappel d’un mort ou contournement de sceau.","texte_court":"il apparaît à 3 m depuis un état compatible. Il n''a pas de PA propres. Ne contourne pas un sceau ; ne rappelle pas un mort.","texte_reference":"R — 1 PA — 1/Scène. Invocation liée. Le Shikigami ne possède aucun pool de PA indépendant.\nConditions de résolution : 1 PA, 1/scène, arrivée à 3 m depuis état compatible, aucun rappel d’un mort ou contournement de sceau.","lore":"L’invocation rappelle le Shikigami lié dans la scène. Il vient comme compagnon véritable mais ne possède pas une réserve de temps parallèle : ce qu’il accomplit reste intégré aux actions de l’Onmyoji.","groupe_actuel":"Onmyoji — Shikigami, sceaux et pactes spirituels › Shikigami","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'onmyoji_shikigami_sceaux_et_pactes_spirituels_shikigami_ancrage_vivant', 'Ancrage vivant', NULL, '{"nature":"humain","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, 1 PA, 1/scène, après Porte-sceau","activation":"1 PA, 1/scène, un sceau déjà préparé de rayon 3 m maximum ; même durée et Puissance, finit avec neutralisation/renvoi du compagnon.","texte_court":"un sceau de zone préparé (3 m au plus) s''ancre sur ton Shikigami manifesté et se déplace avec lui. Un seul à la fois ; il cesse si le Shikigami est neutralisé ou renvoyé.","texte_reference":"R — 1/Scène — Prérequis : Porte-sceau. Un sceau normalement fixé à un lieu, seuil ou petite zone peut être ancré sur le Shikigami manifesté et se déplacer avec lui. Un seul sceau de zone à la fois ; l’effet cesse si le Shikigami est neutralisé ou renvoyé.\nConditions de résolution : 1 PA, 1/scène, un sceau déjà préparé de rayon 3 m maximum ; même durée et Puissance, finit avec neutralisation/renvoi du compagnon.","lore":"Un Shikigami peut devenir le support mobile d’un sceau normalement attaché au terrain. Tant que le compagnon reste manifesté, la petite zone rituelle voyage avec lui comme une bannière surnaturelle.","groupe_actuel":"Onmyoji — Shikigami, sceaux et pactes spirituels › Shikigami","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'humain', 'humain_onmyoji_fuin_sceaux', 'Fūin (sceaux)', NULL, '{"nature":"humain","forme":"une_porte","forme_lot":"1 porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"la règle des sceaux sort de Sceau d''Entrave et du Sceau du Silence vers l''en-tête (correction). Sceau du Silence inchangé, voir question 3."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'onmyoji_shikigami_sceaux_et_pactes_spirituels_fuin_sceaux_sceau_dentrave', 'Sceau d''Entrave', NULL, '{"nature":"humain","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, sceau","activation":"Sceau préparé 1 minute, pose 1 PA au contact ; opposition occulte, puis chaque fuite surnaturelle affronte sa Puissance ; scène ou retrait matériel du sceau.","texte_court":"chaque tentative de fuite surnaturelle de la cible doit vaincre la Puissance du sceau. Les déplacements physiques ordinaires restent possibles.","texte_reference":"Préparez un Sceau d’Entrave en 1 minute, puis posez-le pour 1 PA au contact. Une cible hostile oppose sa Défense occulte à Volonté + Maîtrise spirituelle. En cas de réussite, chacune de ses tentatives de fuite surnaturelle doit vaincre la Puissance fixée à la pose. Le sceau dure la scène ou jusqu’à son retrait matériel ; les déplacements physiques ordinaires restent possibles.","lore":"Le Sceau d’Entrave s’accroche au corps comme à son point de présence actuel. Téléportation, dissolution de fuite ou saut dimensionnel ne peuvent plus emporter ce corps aussi facilement, même si courir ou voler physiquement reste parfaitement possible.","groupe_actuel":"Onmyoji — Shikigami, sceaux et pactes spirituels › Fūin — Sceaux","statut_regle":"correction","changements":"la règle des sceaux sort de Sceau d''Entrave et du Sceau du Silence vers l''en-tête (correction). Sceau du Silence inchangé, voir question 3."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'onmyoji_shikigami_sceaux_et_pactes_spirituels_fuin_sceaux_sceau_du_silence', 'Sceau du Silence', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R, sceau, scène","activation":"Même préparation/pose que Sceau d’Entrave ; cible hostile oppose sa Défense occulte, durée scène, +1 PA non cumulable et jamais réduction d’un coût supérieur à 3.","texte_court":"les Talents Actifs de la cible coûtent +1 PA (maximum 3, sans cumul). Passifs, réactions et Nature ne sont pas touchés.","texte_reference":"R. Les Talents surnaturels Actifs de la cible coûtent +1 PA, maximum 3. Passifs, Réactions et Nature ne sont pas affectés.\nConditions de résolution : Même préparation/pose que Sceau d’Entrave ; cible hostile oppose sa Défense occulte, durée scène, +1 PA non cumulable et jamais réduction d’un coût supérieur à 3.","lore":"Collé sur sa cible, le Sceau du Silence alourdit chaque activation surnaturelle consciente. Les passifs et la Nature restent présents ; ce sont les gestes actifs qui semblent exiger une étape rituelle supplémentaire.","groupe_actuel":"Onmyoji — Shikigami, sceaux et pactes spirituels › Fūin — Sceaux","statut_regle":"correction","changements":"la règle des sceaux sort de Sceau d''Entrave et du Sceau du Silence vers l''en-tête (correction). Sceau du Silence inchangé, voir question 3."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'onmyoji_shikigami_sceaux_et_pactes_spirituels_fuin_sceaux_sceau_de_fermeture', 'Sceau de Fermeture', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, sceau, scène","activation":"Préparer 1 minute, poser 1 PA, ouverture de 3 m maximum ; scène ou rupture du support, Puissance de création pour les passages surnaturels.","texte_court":"sur une porte, fenêtre, portail ou seuil de 3 m au plus. Une entité spirituelle, immatérielle, invoquée ou en passage surnaturel doit vaincre ton V + MS pour le franchir. Ne bloque pas une brèche matérielle.","texte_reference":"SR/R. Apposé sur une porte, fenêtre, portail ou seuil clair, il oblige toute entité spirituelle, immatérielle, invoquée ou utilisant un passage surnaturel à vaincre Volonté + Maîtrise spirituelle de l’Onmyoji pour franchir la limite. Ne bloque pas une brèche ou destruction matérielle ordinaire.\nConditions de résolution : Préparer 1 minute, poser 1 PA, ouverture de 3 m maximum ; scène ou rupture du support, Puissance de création pour les passages surnaturels.","lore":"Posé sur un seuil véritable, le Fūin affirme que les voies spirituelles doivent respecter cette porte. Une créature immatérielle ou invoquée lutte contre le sceau pour passer, tandis qu’une masse physique peut toujours briser le cadre.","groupe_actuel":"Onmyoji — Shikigami, sceaux et pactes spirituels › Fūin — Sceaux","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'onmyoji_shikigami_sceaux_et_pactes_spirituels_fuin_sceaux_sceau_de_protection', 'Sceau de Protection', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, sceau, scène","activation":"Préparer 1 minute, poser 1 PA au contact ; scène, première intrusion par round seulement, une seule barrière surnaturelle équivalente s’applique.","texte_court":"sur une personne ou un objet, il intercepte la première tentative extérieure par round de possession, malédiction, corruption ou contrôle spirituel : elle doit d''abord vaincre ton V + MS.","texte_reference":"SR/R. Apposé sur une personne ou un objet, le sceau intercepte la première tentative extérieure de chaque round de possession, malédiction, corruption ou contrôle spirituel. La source doit d’abord vaincre Volonté + Maîtrise spirituelle de l’Onmyoji ; en réussite, l’effet résout ensuite normalement contre sa vraie cible.\nConditions de résolution : Préparer 1 minute, poser 1 PA au contact ; scène, première intrusion par round seulement, une seule barrière surnaturelle équivalente s’applique.","lore":"Le Sceau de Protection prend la première intrusion spirituelle à sa charge. Possession, malédiction, corruption ou contrôle doit traverser le Fūin avant d’atteindre la personne ou l’objet qu’il couvre.","groupe_actuel":"Onmyoji — Shikigami, sceaux et pactes spirituels › Fūin — Sceaux","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'onmyoji_shikigami_sceaux_et_pactes_spirituels_fuin_sceaux_contre_sceau', 'Contre-sceau', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, 1 PA au contact","activation":"1 PA au contact d’un dispositif accessible ; suspendre pour la scène, ne détruire que les effets temporaires dont le maintien cesse.","texte_court":"sur un sceau, une rune, un cercle, une marque rituelle ou un lien symbolique actif, V + MS contre sa Puissance. Réussite : neutralisé pour la scène ; un effet temporaire peut prendre fin.","texte_reference":"SR/R — 1 PA. Sur un sceau, rune, cercle, marque rituelle ou lien symbolique actif accessible, Volonté + Maîtrise spirituelle contre la Puissance du dispositif. En réussite, il est neutralisé pour la scène ; un effet temporaire peut simplement prendre fin.\nConditions de résolution : 1 PA au contact d’un dispositif accessible ; suspendre pour la scène, ne détruire que les effets temporaires dont le maintien cesse.","lore":"Le Contre-sceau répond à une écriture rituelle par une autre. L’Onmyoji cherche le point où rune, cercle ou marque tient sa fonction et l’annule pour la scène au lieu d’attaquer aveuglément le support entier.","groupe_actuel":"Onmyoji — Shikigami, sceaux et pactes spirituels › Fūin — Sceaux","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'onmyoji_shikigami_sceaux_et_pactes_spirituels_fuin_sceaux_grand_scellement', 'Grand Scellement', NULL, '{"nature":"humain","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, rituel d''une heure au moins, après Sceau d''Entrave et Sceau de Fermeture","activation":"Minimum 1 heure, ancrage concret, cible neutralisée et opposition à sa Défense occulte ; durée jusqu’à rupture du support, exigences majeures fixées avant rite.","texte_court":"une entité vaincue, immobilisée, volontaire ou piégée est scellée dans un objet, un lieu ou un sanctuaire, contre sa Défense occulte, jusqu''à la rupture du support. Puissances majeures : vrai nom, artefact, plusieurs officiants ou condition de scénario, fixés avant.","texte_reference":"R — Rituel prolongé — Prérequis : Sceau d’Entrave + Sceau de Fermeture. Une entité vaincue, immobilisée, volontaire ou déjà piégée peut être durablement scellée dans un objet, lieu, sanctuaire ou support rituel. Temps, préparation, matériaux et ancrage adaptés requis. Les puissances majeures peuvent exiger vrai nom, artefact, plusieurs officiants ou condition de scénario.\nConditions de résolution : Minimum 1 heure, ancrage concret, cible neutralisée et opposition à sa Défense occulte ; durée jusqu’à rupture du support, exigences majeures fixées avant rite.","lore":"Le Grand Scellement est une prison préparée, jamais un bouton lancé au milieu d’un duel. Entité déjà vaincue ou piégée, support adapté, matériaux et temps composent une architecture capable de retenir durablement ce qui y est enfermé.","groupe_actuel":"Onmyoji — Shikigami, sceaux et pactes spirituels › Fūin — Sceaux","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'humain', 'humain_onmyoji_exorcisme_et_noms', 'Exorcisme et noms', NULL, '{"nature":"humain","forme":"une_porte","forme_lot":"1 porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"**ressort propre ajouté** à Présence parasite : elle passe par un papier de sceau posé au contact (au lieu de 10 m) et l''occupant ne se sait pas repéré. Avant, elle était identique mot pour mot à Présence étrangère (Ephraïm)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'onmyoji_shikigami_sceaux_et_pactes_spirituels_exorcisme_et_noms_presence_parasite', 'Présence parasite', NULL, '{"nature":"humain","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, 1 PA, au contact","activation":"1 PA à 10 m, Esprit + Perception contre Puissance de dissimulation éventuelle ; présence extérieure distincte, jamais Nature intrinsèque.","texte_court":"tu poses un papier de sceau préparé sur une personne ou un objet ; il réagit si une présence spirituelle étrangère (possession, parasite) y est attachée. Une présence cachée oppose sa Puissance à ton Esprit + Perception. L''occupant ne sait pas qu''il a été repéré. Ne détecte pas une Nature.","texte_reference":"SR/R — 1 PA. Examiner une personne ou un objet pour détecter une présence spirituelle étrangère actuelle, possession ou parasite distinct. Une présence activement cachée peut s’y opposer. Ne détecte pas une Nature intrinsèque.\nConditions de résolution : 1 PA à 10 m, Esprit + Perception contre Puissance de dissimulation éventuelle ; présence extérieure distincte, jamais Nature intrinsèque.","lore":"La tradition sait reconnaître ce qui habite quelqu’un sans faire partie de lui. Possession et parasite spirituel laissent une présence étrangère perceptible, tandis qu’une Nature véritable ne devient pas suspecte simplement parce qu’elle est surnaturelle.","groupe_actuel":"Onmyoji — Shikigami, sceaux et pactes spirituels › Exorcisme et noms","statut_regle":"correction","changements":"**ressort propre ajouté** à Présence parasite : elle passe par un papier de sceau posé au contact (au lieu de 10 m) et l''occupant ne se sait pas repéré. Avant, elle était identique mot pour mot à Présence étrangère (Ephraïm)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'onmyoji_shikigami_sceaux_et_pactes_spirituels_exorcisme_et_noms_sceau_du_nom', 'Sceau du Nom', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, préparation de 10 minutes","activation":"10 minutes, nom véritable et trace authentique ; remplace seulement le contact pour un sceau compatible à 100 m, même plan, opposition normale et une cible nommée.","texte_court":"si tu connais le vrai nom d''une entité et une trace authentique, tu prépares un sceau ciblé sur elle. Posé sur un objet fortement lié ou une représentation rituelle, il remplace le contact jusqu''à 100 m, même plan. Ne découvre jamais le nom ; un nom civil ne suffit pas.","texte_reference":"SR/R — Préparation. Si le véritable nom surnaturel d’une entité est réellement connu, préparer un sceau ciblé sur elle. Le sceau peut être posé sur un objet personnel fortement lié, un support contenant une vraie trace ou une représentation rituelle appropriée ; il ne découvre jamais le nom et un nom civil ordinaire ne suffit pas.\nConditions de résolution : 10 minutes, nom véritable et trace authentique ; remplace seulement le contact pour un sceau compatible à 100 m, même plan, opposition normale et une cible nommée.","lore":"Un véritable nom surnaturel permet de préparer un sceau qui ne s’adresse qu’à l’entité qu’il désigne. L’Onmyoji doit déjà connaître ce nom et disposer d’un support pertinent ; le rite n’est jamais un moyen de le découvrir.","groupe_actuel":"Onmyoji — Shikigami, sceaux et pactes spirituels › Exorcisme et noms","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'onmyoji_shikigami_sceaux_et_pactes_spirituels_exorcisme_et_noms_faire_comparaitre_lesprit', 'Faire comparaître l''esprit', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R, 1 PA, 10 m","activation":"1 PA à 10 m, Volonté + Maîtrise spirituelle contre Défense occulte de l’occupant ; ciblable jusqu’à fin du prochain round.","texte_court":"sur un hôte portant une présence identifiée, V + MS contre sa Défense occulte. Réussite : jusqu''à la fin du prochain round, elle devient distincte et ciblable par sceaux, exorcismes et effets spirituels. Elle n''est pas expulsée.","texte_reference":"R — 1 PA. Sur un hôte portant une présence étrangère identifiée, Volonté + Maîtrise spirituelle contre l’entité. En réussite, jusqu’à la fin du prochain round elle devient distincte et ciblable par les sceaux, exorcismes et effets spirituels compatibles. Elle n’est pas expulsée.\nConditions de résolution : 1 PA à 10 m, Volonté + Maîtrise spirituelle contre Défense occulte de l’occupant ; ciblable jusqu’à fin du prochain round.","lore":"L’Onmyoji oblige l’occupant caché à devenir une présence rituelle distincte. Pendant quelques instants, sceaux et exorcismes savent enfin ce qu’ils visent, même si l’esprit reste encore installé dans son hôte.","groupe_actuel":"Onmyoji — Shikigami, sceaux et pactes spirituels › Exorcisme et noms","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'onmyoji_shikigami_sceaux_et_pactes_spirituels_exorcisme_et_noms_extraction_par_le_sceau', 'Extraction par le Sceau', NULL, '{"nature":"humain","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, 2 PA pose comprise, 1/scène, après Faire comparaître l''esprit","activation":"2 PA incluant la pose au contact, 1/scène ; occupant rendu distinct, opposition occulte, expulsion seulement.","texte_court":"sur un hôte dont l''esprit a été rendu distinct, V + MS contre sa Défense occulte. Réussite : la possession est rompue et l''entité expulsée.","texte_reference":"R — 2 PA — 1/Scène — Prérequis : Faire comparaître l’esprit. Apposer un sceau d’exorcisme sur un hôte dont l’esprit étranger a été rendu distinct. Volonté + Maîtrise spirituelle contre l’entité ; en réussite, la possession est rompue et l’entité expulsée.\nConditions de résolution : 2 PA incluant la pose au contact, 1/scène ; occupant rendu distinct, opposition occulte, expulsion seulement.","lore":"Après avoir rendu l’esprit étranger distinct de son hôte, l’Onmyoji colle sur cette séparation un sceau qui la rend effective. La possession se défait si l’entité cède, mais rien dans le papier ne prétend annihiler ce qui vient d’être expulsé.","groupe_actuel":"Onmyoji — Shikigami, sceaux et pactes spirituels › Exorcisme et noms","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'onmyoji_shikigami_sceaux_et_pactes_spirituels_exorcisme_et_noms_vase_de_souillure', 'Vase de Souillure', NULL, '{"nature":"humain","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, rituel de 10 minutes, 1/scène, après Contre-sceau ou Extraction par le Sceau","activation":"Voir la résolution détaillée","texte_court":"sur une cible consentante portant une malédiction, une corruption extérieure, une pollution spirituelle, une marque hostile ou un parasite mineur, V + MS contre sa Puissance. Réussite : l''effet passe dans un récipient préparé, sans être détruit. Briser le vase peut le libérer. Aucun point de Corruption effacé.","texte_reference":"R — Rituel — 1/Scène — Prérequis : Contre-sceau ou Extraction par le Sceau. Avec un récipient préparé et une cible consentante portant une malédiction, corruption extérieure, pollution spirituelle, marque hostile ou parasite mineur, Volonté + Maîtrise spirituelle contre l’effet. En réussite, l’effet est transféré dans le vase, pas détruit. Briser ou ouvrir le vase imprudemment peut le libérer ou le transmettre.\nConditions de résolution : 10 minutes, récipient préparé, une seule influence extérieure par vase ; opposition à sa Puissance, 1/scène ; libération selon l’effet réel, aucun point de Corruption effacé gratuitement.","lore":"Le Vase ne purifie pas en détruisant : il déplace. Malédiction, marque ou parasite mineur est attiré dans un récipient préparé, qui devient ensuite un objet réellement dangereux tant que ce qu’il contient n’a pas été traité.","groupe_actuel":"Onmyoji — Shikigami, sceaux et pactes spirituels › Exorcisme et noms","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'humain', 'humain_onmyoji_pactes_d_esprits', 'Pactes d''esprits', NULL, '{"nature":"humain","forme":"une_porte","forme_lot":"1 porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"la liste fermée des profils de Manifestation prêtée remonte de ses conditions vers le texte joueur."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'onmyoji_shikigami_sceaux_et_pactes_spirituels_pactes_desprits_pacte_de_faveur', 'Pacte de Faveur', NULL, '{"nature":"humain","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, rituel","activation":"Enregistrer esprit, accord, Affinité et limites du pacte, un seul actif ; achat sans créature offerte.","texte_court":"pacte avec un esprit compatible réellement rencontré. Il fixe une Affinité réelle (tempête, vent, feu, eau, rivière, montagne, forêt, ombre). Un seul pacte actif ; l''esprit n''est pas un second compagnon.","texte_reference":"SR/R — Rituel. Conclure un pacte avec un esprit naturel ou surnaturel compatible réellement rencontré. Le pacte définit une Affinité réelle — tempête, vent, feu, eau, rivière, montagne, forêt, ombre, etc. — et ne transforme pas l’esprit en second compagnon. Un seul pacte de faveur actif par défaut.\nConditions de résolution : Enregistrer esprit, accord, Affinité et limites du pacte, un seul actif ; achat sans créature offerte.","lore":"Le Pacte de Faveur est conclu avec un esprit que le personnage a réellement rencontré et qui accepte la relation. Il établit une Affinité précise sans faire de cette présence un second compagnon permanent soumis aux ordres de l’Onmyoji.","groupe_actuel":"Onmyoji — Shikigami, sceaux et pactes spirituels › Pactes d’esprits","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'onmyoji_shikigami_sceaux_et_pactes_spirituels_pactes_desprits_sceau_daffinite', 'Sceau d''Affinité', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, préparation, après Pacte de Faveur","activation":"Appliquer la préparation commune d’une minute, un support et une propriété réelle du pacte, sans DGT ni zone ajoutés.","texte_court":"un sceau préparé porte la nature du pacte. Aucun bonus chiffré, mais il exploite une vulnérabilité authentique ou interagit avec un effet qui exige cette nature.","texte_reference":"SR/R — Préparation — Prérequis : Pacte de Faveur. Un sceau préparé peut porter la nature réelle du pacte. Il ne donne aucun bonus numérique mais peut exploiter une vulnérabilité authentique ou interagir avec un effet qui exige cette nature.\nConditions de résolution : Appliquer la préparation commune d’une minute, un support et une propriété réelle du pacte, sans DGT ni zone ajoutés.","lore":"Le sceau préparé peut porter la nature de l’esprit allié comme une véritable correspondance. Feu, vent, rivière ou ombre devient pertinent lorsqu’une faiblesse ou un phénomène exige exactement cette qualité, sans fournir de bonus arbitraire.","groupe_actuel":"Onmyoji — Shikigami, sceaux et pactes spirituels › Pactes d’esprits","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'onmyoji_shikigami_sceaux_et_pactes_spirituels_pactes_desprits_souffle_emprunte', 'Souffle emprunté', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R, 1 PA, 1/scène, après Pacte de Faveur","activation":"Fixer une propriété permanente au pacte : Protection 3 contre un vecteur précis OU respiration/sens/mobilité réelle ; 1 PA, 1/scène, remplace une protection équivalente.","texte_court":"pour la scène, une propriété simple fixée au pacte : Protection 3 contre un vecteur précis, ou une respiration, un sens ou une mobilité réels. Remplace une protection équivalente.","texte_reference":"R — 1 PA — 1/Scène — Prérequis : Pacte de Faveur. Pour la scène, emprunter une seule propriété simple prédéterminée du véritable esprit : résistance électrique, perception de charges, résistance au feu, respiration aquatique, chute ralentie, etc. La propriété est fixée lors du pacte.\nConditions de résolution : Fixer une propriété permanente au pacte : Protection 3 contre un vecteur précis OU respiration/sens/mobilité réelle ; 1 PA, 1/scène, remplace une protection équivalente.","lore":"L’Onmyoji accueille pour une scène une propriété simple de son allié spirituel : respirer l’eau, résister au feu, sentir les charges ou chuter avec le vent. Le pacte a défini cette faveur bien avant que le besoin apparaisse.","groupe_actuel":"Onmyoji — Shikigami, sceaux et pactes spirituels › Pactes d’esprits","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'onmyoji_shikigami_sceaux_et_pactes_spirituels_pactes_desprits_manifestation_pretee', 'Manifestation prêtée', NULL, '{"nature":"humain","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, 2 PA, 1/scène, après Souffle emprunté","activation":"Voir la résolution détaillée","texte_court":"un profil fixé à l''achat : attaque DGT 7 à 10 m contre la Défense adaptée ; poussée de 3 m sur opposition ; manipulation d''un litre à 10 m ; ou Protection typée 3 pour un round.","texte_reference":"R — 2 PA — 1/Scène — Prérequis : Souffle emprunté. Manifester une capacité active signature prédéterminée de l’esprit : attaque de tempête DGT 7, poussée de vent, manipulation locale de l’eau, feu DGT 7, Protection 3 contre une famille cohérente pour un round, etc. Le pacte ne donne jamais « tous les pouvoirs de l’élément ».\nConditions de résolution : Fixer à l’achat un seul profil : attaque DGT 7 à 10 m contre Défense adaptée, poussée 3 m sur opposition, manipulation 1 litre à 10 m, OU Protection typée 3 pour un round ; 2 PA, 1/scène.","lore":"Un esprit allié peut prêter une seule expression active de sa Nature. Tempête, flamme, eau ou protection apparaît sous une forme définie par le pacte, signature réelle du partenaire plutôt qu’un accès général à tout un élément.","groupe_actuel":"Onmyoji — Shikigami, sceaux et pactes spirituels › Pactes d’esprits","statut_regle":"correction","changements":"la liste fermée des profils de Manifestation prêtée remonte de ses conditions vers le texte joueur."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('couche', 'humain', 'humain_neopaiens', 'Néopaïens', NULL, '{"nature":"humain","chemin":["Néopaïens"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'humain', 'humain_neopaiens_pratiques_neopaiennes', 'Pratiques néopaïennes', NULL, '{"nature":"humain","forme":"une_porte","forme_lot":"1 porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"aucun (le coût de 2 PTV d''Offrande de paix est celui de l''arbitrage du 30 septembre ; le livre V6 dit encore 3)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'neopaiens_pratiques_communes_et_mysteres_pratiques_neopaiennes_correspondance_sacree', 'Correspondance sacrée', NULL, '{"nature":"humain","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, rituel de 10 minutes","activation":"10 minutes sur un support réel au contact, valable pour le prochain rite dans la scène ; correspondance réelle, sans sacralité ou vulnérabilité universelle.","texte_court":"un symbole, objet, matériau, nom ou offrande devient pertinent pour le prochain rite de la scène qui exige cette correspondance. Aucune vulnérabilité créée.","texte_reference":"SR/R — Rituel. Consacrer un symbole, objet, matériau, image, nom ou offrande à une correspondance mythique réellement valable. Le support devient spirituellement pertinent pour les rites qui exigent cette correspondance. Ne crée aucune vulnérabilité.\nConditions de résolution : 10 minutes sur un support réel au contact, valable pour le prochain rite dans la scène ; correspondance réelle, sans sacralité ou vulnérabilité universelle.","lore":"Le néopaïen sait consacrer un support à ce qu’il représente réellement dans le mythe : plante, métal, image, nom ou offrande. La correspondance devient utilisable dans les rites appropriés sans inventer une faiblesse que la tradition n’a jamais reconnue.","groupe_actuel":"Néopaïens — pratiques communes et Mystères › Pratiques néopaïennes","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'neopaiens_pratiques_communes_et_mysteres_pratiques_neopaiennes_syncretisme_operatif', 'Syncrétisme opératif', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, passif","activation":"Noter l’équivalence au moment du rite, conserver composants matériels, coûts et opposition.","texte_court":"quand un rite exige un élément symbolique, tu le remplaces par un équivalent mythiquement cohérent d''une autre tradition. Composants, coûts et opposition restent ; « n''importe quoi » ne vaut pas.","texte_reference":"SR/R — Passif. Lorsqu’un rite exige un élément symbolique précis, substituer un équivalent mythiquement cohérent d’une autre tradition et le faire fonctionner métaphysiquement. La correspondance doit être réellement défendable dans la Vérité ; « n’importe quoi = n’importe quoi » est impossible.\nConditions de résolution : Noter l’équivalence au moment du rite, conserver composants matériels, coûts et opposition.","lore":"Le Syncrétisme ne dit pas que tous les symboles se valent ; il sait reconnaître lorsque deux traditions parlent réellement du même principe par des images différentes. Cette équivalence défendable permet alors à l’un de remplir la fonction rituelle de l’autre.","groupe_actuel":"Néopaïens — pratiques communes et Mystères › Pratiques néopaïennes","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'neopaiens_pratiques_communes_et_mysteres_pratiques_neopaiennes_memoire_du_lieu', 'Mémoire du lieu', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, 2 PA, 1/scène par lieu","activation":"2 PA, 1/scène/lieu ; manifestation surnaturelle majeure seulement, aucune identité automatique.","texte_court":"dans un lieu marqué par un événement surnaturel significatif, le MJ donne des impressions fragmentaires authentiques de la manifestation la plus forte. Jamais la scène complète ni les identités.","texte_reference":"SR/R — 2 PA — 1/Scène/lieu. Dans un lieu marqué par un événement surnaturel significatif, demander quelle manifestation majeure a laissé la trace la plus forte. Le MJ fournit impressions, images, sensations ou sons fragmentaires authentiques ; jamais la vidéo complète, les identités automatiques ou l’explication intégrale.\nConditions de résolution : 2 PA, 1/scène/lieu ; manifestation surnaturelle majeure seulement, aucune identité automatique.","lore":"Les lieux gardent surtout les événements surnaturels qui les ont profondément marqués. Le praticien en reçoit des fragments sensoriels — impression, son, image, odeur — comme les restes d’un souvenir sans montage ni commentaire explicatif.","groupe_actuel":"Néopaïens — pratiques communes et Mystères › Pratiques néopaïennes","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'neopaiens_pratiques_communes_et_mysteres_pratiques_neopaiennes_cercle_des_temoins', 'Cercle des témoins', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, préparation de 10 minutes","activation":"10 minutes de préparation ; ils remplissent les rôles matériels/symboliques autorisés, jamais un rang, talent ou pouvoir exigé ; Assistance +2 totale inchangée.","texte_court":"des personnes consentantes non initiées tiennent de vraies fonctions rituelles (point du cercle, offrande, refrain, nombre minimal d''officiants). Elles ne gagnent aucun pouvoir ; l''Assistance reste limitée à +2 au total.","texte_reference":"SR/R — Rituel. Des personnes consentantes non initiées peuvent remplir de vraies fonctions rituelles : tenir un point du cercle, porter l’offrande, maintenir un refrain, soutenir un symbole, compter dans un nombre minimal d’officiants. Elles n’acquièrent aucun pouvoir personnel. Une Assistance normale éventuelle reste limitée à +2 total.\nConditions de résolution : 10 minutes de préparation ; ils remplissent les rôles matériels/symboliques autorisés, jamais un rang, talent ou pouvoir exigé ; Assistance +2 totale inchangée.","lore":"Un rite communautaire n’exige pas que chaque main soit initiée. Des témoins consentants peuvent tenir le cercle, porter l’offrande ou soutenir le refrain et devenir de vrais participants symboliques sans recevoir pour autant le moindre pouvoir propre.","groupe_actuel":"Néopaïens — pratiques communes et Mystères › Pratiques néopaïennes","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'neopaiens_pratiques_communes_et_mysteres_pratiques_neopaiennes_offrande_de_paix', 'Offrande de paix', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, 2 PA, 1/scène, 10 m","activation":"2 PA, 1/scène, entité à 10 m ; accord surnaturel protégeant les interlocuteurs nommés pendant l’échange loyal, sans forcer l’acceptation.","texte_court":"tu proposes une trêve à une entité. Si elle accepte, un accord surnaturel protège les interlocuteurs nommés de leurs actes hostiles pendant cet échange loyal. La fin de l''échange ou la mauvaise foi y met fin.","texte_reference":"Pour 2 PA, une fois par scène, proposez une trêve à une entité à 10 m. Si elle accepte, un accord surnaturel protège les interlocuteurs nommés contre les actes hostiles des parties pendant cet échange loyal. Le refus reste possible ; la fin de l’échange ou la rupture de bonne foi met fin à la trêve.","lore":"Une offrande pertinente reconnaît d’abord la Nature de l’entité à laquelle elle s’adresse. Si celle-ci accepte de bonne foi, un espace de négociation s’ouvre où l’attaque immédiate cesse d’être la première réponse, sans obliger l’esprit à devenir amical.","groupe_actuel":"Néopaïens — pratiques communes et Mystères › Pratiques néopaïennes","statut_regle":"correction","changements":"aucun (le coût de 2 PTV d''Offrande de paix est celui de l''arbitrage du 30 septembre ; le livre V6 dit encore 3)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'humain', 'humain_neopaiens_mystere_des_morts_et_des_ancetres', 'Mystère des Morts et des Ancêtres', NULL, '{"nature":"humain","forme":"une_porte","forme_lot":"1 porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"aucun."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'neopaiens_pratiques_communes_et_mysteres_mystere_des_morts_et_des_ancetres_veillee_des_morts', 'Veillée des morts', NULL, '{"nature":"humain","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, rituel de 10 minutes","activation":"10 minutes sur le lieu ou au contact du support ; communication de 5 minutes maximum avec ce qui est réellement présent, aucune réponse forcée.","texte_court":"auprès d''un mort récent, d''une tombe ou d''une hantise, ce qui est réellement présent peut communiquer 5 minutes. Rien n''est rappelé ni forcé.","texte_reference":"SR/R — Rituel. Auprès d’un mort récent, d’une tombe ou d’une hantise, toute âme ou tout écho encore réellement présent peut se manifester suffisamment pour une brève communication. Ne rappelle pas une âme déjà partie, ne ressuscite pas et ne force pas la réponse.\nConditions de résolution : 10 minutes sur le lieu ou au contact du support ; communication de 5 minutes maximum avec ce qui est réellement présent, aucune réponse forcée.","lore":"La Veillée donne aux morts encore proches un moment où ils peuvent se rendre perceptibles. Une âme partie ne revient pas pour satisfaire la curiosité des vivants, mais ce qui demeure réellement là peut trouver assez de présence pour quelques mots.","groupe_actuel":"Néopaïens — pratiques communes et Mystères › Mystère des Morts et des Ancêtres","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'neopaiens_pratiques_communes_et_mysteres_mystere_des_morts_et_des_ancetres_guider_le_defunt', 'Guider le défunt', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, rituel de 10 minutes, après Veillée","activation":"10 minutes, âme présente et attachement identifié ; opposition à sa Puissance, choix de partir laissé à l’esprit, exigences propres aux ancrages majeurs.","texte_court":"sur une âme errante retenue par un attachement identifié, V + MS contre ce qui la retient. Réussite : l''ancrage est rompu ; l''esprit choisit ce qu''il fait.","texte_reference":"SR/R — Rituel — Prérequis : Veillée des morts. Sur une âme errante ou un fantôme retenu par un attachement identifiable, Volonté + Maîtrise spirituelle contre ce qui le retient. En réussite, l’ancrage est rompu ; l’esprit choisit ensuite ce qu’il fait. Ce n’est pas une destruction.\nConditions de résolution : 10 minutes, âme présente et attachement identifié ; opposition à sa Puissance, choix de partir laissé à l’esprit, exigences propres aux ancrages majeurs.","lore":"Un fantôme retenu par un lieu, un objet ou une dette peut être aidé à délier ce qui le garde ici. Le néopaïen ouvre la voie ; il ne détruit pas l’esprit et ne choisit pas à sa place ce qu’il fera une fois libre.","groupe_actuel":"Néopaïens — pratiques communes et Mystères › Mystère des Morts et des Ancêtres","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'neopaiens_pratiques_communes_et_mysteres_mystere_des_morts_et_des_ancetres_appel_des_ancetres', 'Appel des ancêtres', NULL, '{"nature":"humain","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, rituel de 30 minutes, 1/scénario, après Veillée","activation":"30 minutes, 1/scénario, famille ou continuité réelle ; une question, connaissance authentique ou ignorance, jamais savoir omniscient du Néant.","texte_court":"autour d''une famille, communauté ou lignée à laquelle un participant appartient réellement, une question sur un ennemi, un rite, un événement ou une dette. Réponse vraie si un ancêtre la connaissait ; sinon « je ne sais pas ».","texte_reference":"R — 1/Scénario — Prérequis : Veillée des morts. Rite autour d’une famille, communauté, lignée ou tradition à laquelle le Chasseur ou un participant appartient réellement. Appeler les échos de cette continuité et poser une question sur un ancien ennemi, rite, événement ou dette. Réponse vraie seulement si un ancêtre appelé connaissait réellement l’information ; sinon « je ne sais pas ».\nConditions de résolution : 30 minutes, 1/scénario, famille ou continuité réelle ; une question, connaissance authentique ou ignorance, jamais savoir omniscient du Néant.","lore":"L’Appel ne convoque pas une bibliothèque des morts ; il s’adresse à une continuité réelle de famille, communauté ou tradition. Les Ancêtres répondent seulement avec ce qu’ils ont effectivement su de leur vivant, y compris par un simple aveu d’ignorance.","groupe_actuel":"Néopaïens — pratiques communes et Mystères › Mystère des Morts et des Ancêtres","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'humain', 'humain_neopaiens_mystere_de_la_terre_et_de_la_chasse', 'Mystère de la Terre et de la Chasse', NULL, '{"nature":"humain","forme":"une_porte","forme_lot":"1 porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"aucun. La voie n''a pas de palier II, aucun talent de ce coût n''existant."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'neopaiens_pratiques_communes_et_mysteres_mystere_de_la_terre_et_de_la_chasse_terre_troublee', 'Terre troublée', NULL, '{"nature":"humain","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, 1 PA, 10 m","activation":"1 PA, sol naturel continu dans un rayon de 10 m, passage des dernières 24 h ; direction grossière sans quantité ni identité.","texte_court":"sur un sol naturel continu, tu sens si une présence surnaturelle étrangère est passée dans les dernières 24 heures : oui ou non, direction générale, passage isolé ou répété. Ni identité, ni nombre.","texte_reference":"SR/R — 1 PA. Dans un environnement offrant une continuité naturelle suffisante, sentir si une présence surnaturelle étrangère au lieu l’a récemment traversé : intrusion oui/non, direction générale, passage isolé ou répété. Ne révèle ni identité, espèce, nombre exact ni piste parfaite.\nConditions de résolution : 1 PA, sol naturel continu dans un rayon de 10 m, passage des dernières 24 h ; direction grossière sans quantité ni identité.","lore":"Une présence étrangère laisse parfois dans un milieu naturel une perturbation plus profonde que des empreintes. Le néopaïen ressent que quelque chose de surnaturel a traversé ce lieu et de quel côté le trouble se prolonge, sans savoir encore qui marchait là.","groupe_actuel":"Néopaïens — pratiques communes et Mystères › Mystère de la Terre et de la Chasse","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'neopaiens_pratiques_communes_et_mysteres_mystere_de_la_terre_et_de_la_chasse_trace_que_rien_nefface', 'Trace que rien n''efface', NULL, '{"nature":"humain","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"SR/R, rituel de 10 minutes, scénario, après Terre troublée","activation":"10 minutes depuis trace authentique, scénario ; un seul suivi actif, aucun franchissement automatique d’une téléportation.","texte_court":"à partir d''une trace réelle d''une proie identifiée et d''une correspondance, ses pouvoirs ne peuvent plus effacer toute trace de son passage en milieu naturel. Pistage, Perception ou Investigation restent nécessaires. Un seul suivi actif.","texte_reference":"SR/R — Rituel — Prérequis : Terre troublée. À partir d’une trace réelle d’une proie identifiée et d’une correspondance appropriée, jusqu’à la fin du scénario les pouvoirs surnaturels de la proie ne peuvent éliminer absolument toute trace de son passage dans un environnement naturel. Pistage, Perception ou Investigation restent nécessaires pour trouver les traces qui subsistent.\nConditions de résolution : 10 minutes depuis trace authentique, scénario ; un seul suivi actif, aucun franchissement automatique d’une téléportation.","lore":"À partir d’une trace authentique, le Mystère lie la proie à la terre qu’elle traverse. Ses pouvoirs peuvent masquer, brouiller ou raréfier la piste, mais plus l’effacer absolument : quelque chose demeure toujours à trouver pour qui sait vraiment pister.","groupe_actuel":"Néopaïens — pratiques communes et Mystères › Mystère de la Terre et de la Chasse","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'neopaiens_pratiques_communes_et_mysteres_mystere_de_la_terre_et_de_la_chasse_cercle_de_chasse', 'Cercle de chasse', NULL, '{"nature":"humain","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, rituel de 10 minutes, 1/scène","activation":"10 minutes, rayon 20 m clairement borné, 1/scène ; proie identifiée, Puissance de création, sorties physiques et destruction d’ancrages possibles.","texte_court":"une zone naturelle bornée de 20 m de rayon est vouée à la chasse d''une proie identifiée. Toute sortie par téléportation, passage dimensionnel, immatérialité ou fuite spirituelle doit vaincre ton V + MS. Elle peut sortir en courant.","texte_reference":"R — Rituel préparé — 1/Scène. Consacrer une zone naturelle clairement bornée à la chasse d’une proie identifiée. Tant qu’elle reste dans la zone, toute sortie par téléportation, passage dimensionnel, immatérialité franchissant la limite ou fuite spirituelle doit vaincre Volonté + Maîtrise spirituelle du Chasseur. La cible peut physiquement sortir en courant.\nConditions de résolution : 10 minutes, rayon 20 m clairement borné, 1/scène ; proie identifiée, Puissance de création, sorties physiques et destruction d’ancrages possibles.","lore":"Le Cercle de chasse consacre un morceau de terre comme territoire de poursuite. La proie reste libre de courir hors de ses limites, mais une fuite qui voudrait simplement disparaître au-delà du monde doit d’abord vaincre le rite qui l’a désignée.","groupe_actuel":"Néopaïens — pratiques communes et Mystères › Mystère de la Terre et de la Chasse","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'humain', 'humain_neopaiens_mystere_du_foyer_et_des_seuils', 'Mystère du Foyer et des Seuils', NULL, '{"nature":"humain","forme":"une_porte","forme_lot":"1 porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"aucun."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'neopaiens_pratiques_communes_et_mysteres_mystere_du_foyer_et_des_seuils_droit_dhospitalite', 'Droit d''hospitalité', NULL, '{"nature":"humain","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, rituel d''une minute intégré à l''accueil","activation":"Rituel de 1 minute intégré à l’accueil ; nommer hôte, invités et protégés, jusqu’au départ ou rupture de l’accord ; aucune protection ajoutée rétroactivement.","texte_court":"une entité qui a demandé ou accepté l''hospitalité du véritable occupant doit vaincre ton V + MS pour attaquer l''hôte ou les personnes nommées, jusqu''à son départ. L''hôte perd la protection s''il attaque, piège ou viole l''accord.","texte_reference":"SR/R — Rituel social. Lorsqu’une entité surnaturelle entre volontairement dans un lieu après avoir demandé, reçu ou explicitement accepté l’hospitalité du véritable occupant, sceller cette hospitalité. Jusqu’à son départ ou rupture des termes, l’invité doit vaincre Volonté + Maîtrise spirituelle pour attaquer directement l’hôte ou les personnes explicitement protégées. L’hôte perd la protection s’il attaque, piège ou viole lui-même l’accord.\nConditions de résolution : Rituel de 1 minute intégré à l’accueil ; nommer hôte, invités et protégés, jusqu’au départ ou rupture de l’accord ; aucune protection ajoutée rétroactivement.","lore":"Le Droit d’hospitalité transforme l’accueil accepté en règle réciproque. L’invité surnaturel trouve plus difficile d’attaquer son hôte tant que celui-ci respecte lui-même la paix du foyer et les termes qui ont ouvert la porte.","groupe_actuel":"Néopaïens — pratiques communes et Mystères › Mystère du Foyer et des Seuils","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'neopaiens_pratiques_communes_et_mysteres_mystere_du_foyer_et_des_seuils_feu_du_foyer', 'Feu du foyer', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, 2 PA, scène","activation":"2 PA au foyer réel, rayon 3 m, scène ; première intrusion par round pour le refuge entier, Puissance fixée au rituel.","texte_court":"au véritable foyer d''un lieu habité, rayon de 3 m. La première tentative extérieure par round de posséder, expulser ou pénétrer l''esprit d''un occupant doit d''abord vaincre ton V + MS, fixé au rite.","texte_reference":"SR/R — 2 PA — Scène. Autour d’un véritable centre symbolique d’un lieu habité, établir un refuge spirituel. La première tentative extérieure de chaque round cherchant à posséder, expulser surnaturellement, arracher spirituellement ou pénétrer directement l’esprit d’un occupant protégé doit d’abord vaincre Volonté + Maîtrise spirituelle du néopaïen ; en réussite, la cible résiste ensuite normalement.\nConditions de résolution : 2 PA au foyer réel, rayon 3 m, scène ; première intrusion par round pour le refuge entier, Puissance fixée au rituel.","lore":"Autour du véritable cœur d’un lieu habité, le Feu du foyer crée une chaleur spirituelle qui protège ceux qui y appartiennent momentanément. Les intrusions visant directement leur âme ou leur esprit doivent d’abord traverser cette hospitalité sacrée.","groupe_actuel":"Néopaïens — pratiques communes et Mystères › Mystère du Foyer et des Seuils","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'neopaiens_pratiques_communes_et_mysteres_mystere_du_foyer_et_des_seuils_maison_fermee', 'Maison fermée', NULL, '{"nature":"humain","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, rituel de 10 minutes, scène","activation":"10 minutes, un bâtiment habité ou camp de rayon 20 m maximum, scène ; ancrages sur les limites, ouvertures physiques ordinaires conservées.","texte_court":"les limites d''une maison, d''un refuge ou d''un camp habité (20 m au plus). Une entité extérieure ne peut entrer ou sortir par apparition, téléportation, intrusion spirituelle ou passage dimensionnel sans vaincre ton V + MS. Portes et fenêtres fonctionnent normalement.","texte_reference":"R — Rituel. Consacrer les limites d’une maison, appartement, refuge ou camp réellement occupé. Pour la scène, une entité extérieure ne peut entrer ou sortir par apparition, téléportation, intrusion spirituelle ou passage dimensionnel sans vaincre Volonté + Maîtrise spirituelle. N’arrête ni porte, fenêtre, mur cassé ni sortie physique.\nConditions de résolution : 10 minutes, un bâtiment habité ou camp de rayon 20 m maximum, scène ; ancrages sur les limites, ouvertures physiques ordinaires conservées.","lore":"Le rite ferme les limites surnaturelles d’un refuge réellement occupé. Une entité peut encore pousser une porte, briser une fenêtre ou sortir à pied ; elle ne peut plus traiter l’intérieur comme un espace où apparition et passage dimensionnel ignorent le seuil.","groupe_actuel":"Néopaïens — pratiques communes et Mystères › Mystère du Foyer et des Seuils","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'humain', 'humain_neopaiens_mystere_des_presages_et_du_destin', 'Mystère des Présages et du Destin', NULL, '{"nature":"humain","forme":"une_porte","forme_lot":"1 porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"aucun."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'neopaiens_pratiques_communes_et_mysteres_mystere_des_presages_et_du_destin_augure', 'Augure', NULL, '{"nature":"humain","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, rituel de 10 minutes, 1/scène","activation":"10 minutes, 1/scène, action prévue dans l’heure ; réponse sur forces déjà présentes, aucune garantie ni changement rétroactif de menace.","texte_court":"pour une action prévue dans l''heure, le MJ dit favorable, neutre ou menaçant selon les forces surnaturelles déjà en place. Ni garantie, ni danger qui n''existe pas encore.","texte_reference":"SR/R — Rituel — 1/Scène. Formuler une action précise de futur proche. Le MJ indique favorable, neutre ou menaçant selon les forces surnaturelles immédiates déjà en place autour de ce choix. Ne dit pas « bonne idée ? », ne garantit aucune victoire et ne détecte pas un danger qui n’existe pas encore.\nConditions de résolution : 10 minutes, 1/scène, action prévue dans l’heure ; réponse sur forces déjà présentes, aucune garantie ni changement rétroactif de menace.","lore":"L’Augure interroge les forces surnaturelles déjà tendues autour d’un choix prochain. Les signes disent si cette voie semble favorable, neutre ou menaçante, sans transformer un présage en garantie ni inventer un péril qui n’existe pas encore.","groupe_actuel":"Néopaïens — pratiques communes et Mystères › Mystère des Présages et du Destin","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'neopaiens_pratiques_communes_et_mysteres_mystere_des_presages_et_du_destin_reconnaitre_lheure', 'Reconnaître l''heure', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, réaction 1 PA, 1/scène, après Augure","activation":"Réaction 1 PA incluant l’action simple, 1/scène ; même menace qu’Augure, déplacement normal ou préparation prête, aucune attaque.","texte_court":"quand la menace annoncée par l''Augure se manifeste, tu sens « c''est maintenant » et fais une action simple : te déplacer, te mettre à couvert, protéger quelqu''un ou activer une préparation. Pas d''attaque.","texte_reference":"SR/R — Réaction 1 PA — 1/Scène — Prérequis : Augure. Lorsqu’une menace précise révélée par Augure commence effectivement à se manifester, le Chasseur reconnaît « c’est maintenant » avant sa résolution et peut effectuer une action simple exclusivement destinée à se déplacer, se mettre à couvert, protéger quelqu’un ou activer une préparation déjà prête. Pas d’attaque gratuite.\nConditions de résolution : Réaction 1 PA incluant l’action simple, 1/scène ; même menace qu’Augure, déplacement normal ou préparation prête, aucune attaque.","lore":"Un présage déjà reçu peut soudain devenir reconnaissable dans le monde réel. Le Chasseur comprend que « c’est maintenant » une fraction de seconde avant le danger annoncé et peut accomplir le geste simple qu’il avait encore le temps de préparer.","groupe_actuel":"Néopaïens — pratiques communes et Mystères › Mystère des Présages et du Destin","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'neopaiens_pratiques_communes_et_mysteres_mystere_des_presages_et_du_destin_refuser_le_destin_impose', 'Refuser le destin imposé', NULL, '{"nature":"humain","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, réaction 1 PA, 1/scène, 10 m","activation":"Réaction 1 PA, 1/scène, soi ou allié à 10 m ; opposition à la Puissance de la fatalité précise avant résolution, suspension de scène sans défaire tout le pacte.","texte_court":"un pouvoir impose une fatalité, une malédiction conditionnelle ou un résultat prédéterminé à toi ou à un allié : V + MS contre sa Puissance. Réussite : la conséquence est suspendue pour la scène. Pas contre une balle ni une mortalité ordinaire.","texte_reference":"R — Réaction 1 PA — 1/Scène. Lorsqu’un pouvoir surnaturel impose directement une fatalité, destinée, malédiction conditionnelle, événement inévitable ou résultat prédéterminé au Chasseur ou à un allié proche, Volonté + Maîtrise spirituelle contre la Puissance de l’effet. En réussite, la conséquence est suspendue pour la scène. Ne fonctionne pas contre balle, décision humaine, conséquence logique ou mortalité ordinaire.\nConditions de résolution : Réaction 1 PA, 1/scène, soi ou allié à 10 m ; opposition à la Puissance de la fatalité précise avant résolution, suspension de scène sans défaire tout le pacte.","lore":"Le Mystère distingue le destin de la simple conséquence. Lorsqu’une puissance surnaturelle prétend imposer directement une fatalité ou un résultat écrit d’avance, le néopaïen peut refuser pour un temps que cette prophétie devienne loi.","groupe_actuel":"Néopaïens — pratiques communes et Mystères › Mystère des Présages et du Destin","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'humain', 'humain_neopaiens_mystere_des_serments_et_du_sacrifice', 'Mystère des Serments et du Sacrifice', NULL, '{"nature":"humain","forme":"une_porte","forme_lot":"1 porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"aucun. Prix consenti reste à l''appréciation du MJ (pas de barème dans les sources)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'neopaiens_pratiques_communes_et_mysteres_mystere_des_serments_et_du_sacrifice_serment_veritable', 'Serment véritable', NULL, '{"nature":"humain","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, rituel de 10 minutes","activation":"10 minutes, parties consentantes et texte clair ; un serment suivi à la fois jusqu’à accomplissement/rupture, sans localisation ni contrainte ajoutée.","texte_court":"deux parties consentantes déclarent un serment clair. Tu sais ensuite s''il reste intact ou a été volontairement rompu. Ni où, ni pourquoi ; il n''oblige pas à obéir.","texte_reference":"SR/R — Rituel. Deux parties consentantes déclarent un serment clair. Le néopaïen sait ensuite si le serment reste intact ou a été volontairement rompu. Il ne sait pas automatiquement où, pourquoi ni par qui lorsqu’il existe plusieurs parties. Le serment n’oblige pas à obéir.\nConditions de résolution : 10 minutes, parties consentantes et texte clair ; un serment suivi à la fois jusqu’à accomplissement/rupture, sans localisation ni contrainte ajoutée.","lore":"Le Serment véritable est d’abord une parole volontaire entendue par la Vérité. Après le rite, le néopaïen sait si cette parole tient encore ou si quelqu’un l’a consciemment rompue, sans recevoir le récit complet de la trahison.","groupe_actuel":"Néopaïens — pratiques communes et Mystères › Mystère des Serments et du Sacrifice","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'neopaiens_pratiques_communes_et_mysteres_mystere_des_serments_et_du_sacrifice_prix_consenti', 'Prix consenti', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, 1/scène","activation":"2 PTV et 1/scène ; sacrifice concret et durable défini avant rite, aucune substitution cosmologique automatique.","texte_court":"quand un rite manque une condition ou un coût symbolique, tu offres un sacrifice personnel concret et durable, défini avant le rite, si le MJ juge l''équivalence suffisante. Jamais de l''argent trivial à la place d''une condition cosmologique.","texte_reference":"SR/R — 1/Scène. Lorsqu’un rite manque une condition ou un coût symbolique impossible à satisfaire immédiatement, offrir un sacrifice personnel réellement significatif et durable comme substitution si le MJ juge l’équivalence métaphysique suffisante. Ne remplace jamais une condition cosmologique par de l’argent trivial.\nConditions de résolution : 1/scène ; sacrifice concret et durable défini avant rite, aucune substitution cosmologique automatique.","lore":"Certains rites exigent moins un objet précis qu’un prix dont le sens est équivalent. Le néopaïen peut offrir quelque chose de personnel, durable et réellement coûteux pour combler ce manque, jamais transformer quelques dollars en substitut d’une condition cosmologique.","groupe_actuel":"Néopaïens — pratiques communes et Mystères › Mystère des Serments et du Sacrifice","statut_regle":"correction","changements":"aucun. Prix consenti reste à l''appréciation du MJ (pas de barème dans les sources)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'neopaiens_pratiques_communes_et_mysteres_mystere_des_serments_et_du_sacrifice_lier_par_le_serment', 'Lier par le serment', NULL, '{"nature":"humain","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, rituel de 10 minutes, après Serment véritable","activation":"Voir la résolution détaillée","texte_court":"une créature accepte librement un accord écrit. Quand elle tente de le violer, sa Volonté + Force Mentale contre ton V + MS, fixé au pacte ; échec, elle ne peut pas commettre l''acte maintenant (une tentative par clause et par scène).","texte_reference":"R — Rituel — Prérequis : Serment véritable. Une créature surnaturelle accepte volontairement un accord formulé clairement. Les clauses deviennent un lien surnaturel jusqu’à accomplissement ou rupture. Lorsqu’elle tente directement de violer l’accord, Volonté + Force Mentale contre Volonté + Maîtrise spirituelle de l’officiant ; en échec, elle ne peut accomplir l’acte à cet instant et peut retenter plus tard. Le consentement initial ne peut jamais être forcé par ce Talent.\nConditions de résolution : 10 minutes, parties consentantes, clauses écrites ; une tentative de violation par scène pour la même clause, contre Puissance fixée au pacte ; réussite n’efface pas les autres clauses.","lore":"Une créature qui accepte librement un accord peut voir ses propres paroles devenir un lien réel. Le serment ne force jamais le consentement initial ; il donne seulement aux clauses acceptées assez de poids pour retenir celui qui tente ensuite de les violer.","groupe_actuel":"Néopaïens — pratiques communes et Mystères › Mystère des Serments et du Sacrifice","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('couche', 'humain', 'humain_chasse_fantastique', 'Chasse Fantastique', NULL, '{"nature":"humain","chemin":["Chasse Fantastique"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'humain', 'humain_chasse_fantastique_voie_des_limiers', 'Voie des Limiers', NULL, '{"nature":"humain","forme":"une_porte","forme_lot":"1 porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"en-tête d''Écho du passage complété (réaction 1 PA). Ressort déjà distinct des autres marques : la Marque du Limier interdit l''effacement de la piste."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'chasse_fantastique_la_venerie_surnaturelle_voie_des_limiers_marque_du_limier', 'Marque du Limier', NULL, '{"nature":"humain","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, 1 PA","activation":"1 PA après contact/blessure ou un round d’observation directe à 20 m ; une proie, jusqu’à neutralisation ou rupture volontaire ; piste réelle toujours nécessaire.","texte_court":"après contact, blessure ou un round d''observation à 20 m d''une proie identifiée, tu fixes sa signature de chasse. Une seule proie. Ses pouvoirs ne peuvent plus effacer toute trace : Pistage, Perception ou Investigation trouvent encore quelque chose.","texte_reference":"SR/R — 1 PA. Après avoir touché, blessé ou suffisamment observé une proie correctement identifiée, fixer sa signature de chasse. Une seule proie active. Tant que la Marque demeure, ses pouvoirs surnaturels ne peuvent supprimer toute possibilité de retrouver une trace : Pistage, Investigation ou Perception peuvent encore trouver quelque chose là où la piste aurait dû être entièrement effacée.\nConditions de résolution : 1 PA après contact/blessure ou un round d’observation directe à 20 m ; une proie, jusqu’à neutralisation ou rupture volontaire ; piste réelle toujours nécessaire.","lore":"La Marque du Limier fixe dans l’esprit du chasseur la signature d’une proie réellement rencontrée. Elle ne révèle pas sa position ; elle empêche surtout le surnaturel d’effacer toute conséquence de son passage comme si elle n’avait jamais été là.","groupe_actuel":"Chasse Fantastique — la Vénerie surnaturelle › Voie des Limiers","statut_regle":"correction","changements":"en-tête d''Écho du passage complété (réaction 1 PA). Ressort déjà distinct des autres marques : la Marque du Limier interdit l''effacement de la piste."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'chasse_fantastique_la_venerie_surnaturelle_voie_des_limiers_la_vraie_bete', 'La vraie bête', NULL, '{"nature":"humain","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, passif, après Marque du Limier","activation":"Perception directe actuelle exigée, pas d’alarme de proximité ni de lecture des doubles non perçus.","texte_court":"quand la proie marquée se cache par métamorphose, duplication, illusion ou échange de corps, tu reconnais la vraie quand tu la perçois. Une cible Voilée reste humaine à tes yeux ; tu sais seulement « c''est elle ».","texte_reference":"SR/R — Passif — Prérequis : Marque du Limier. Lorsqu’une proie marquée utilise métamorphose, duplication, illusion, échange apparent de corps ou autre moyen surnaturel pour masquer laquelle est la vraie proie, le Limier reconnaît le véritable individu lorsqu’il le perçoit directement. Une cible V reste visuellement humaine ; il sait simplement « c’est elle ».\nConditions de résolution : Perception directe actuelle exigée, pas d’alarme de proximité ni de lecture des doubles non perçus.","lore":"Une proie marquée conserve quelque chose que métamorphose, double ou illusion ne parviennent plus à remplacer. Le Limier reconnaît l’individu véritable lorsqu’il l’a sous les yeux, même si le monde lui présente un autre visage.","groupe_actuel":"Chasse Fantastique — la Vénerie surnaturelle › Voie des Limiers","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'chasse_fantastique_la_venerie_surnaturelle_voie_des_limiers_echo_du_passage', 'Écho du passage', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, réaction 1 PA, 20 m","activation":"Réaction 1 PA, proie marquée perçue à 20 m ; type et départ de transition seulement, direction si arrivée dans les 100 m.","texte_court":"quand la proie marquée quitte la zone par portail, seuil, téléportation ou transition, tu perçois le type de transition, son point de départ et si elle reste dans la même couche ; direction si elle arrive à 100 m au plus.","texte_reference":"SR/R — Réaction. Lorsqu’une proie marquée et perçue quitte brutalement la zone par portail, seuil, déplacement spirituel, téléportation ou transition inter-couche, percevoir l’écho : type général de transition, point de départ et si la destination semble rester dans la même couche. Si l’arrivée est proche dans le même environnement, direction générale. Aucun suivi automatique.\nConditions de résolution : Réaction 1 PA, proie marquée perçue à 20 m ; type et départ de transition seulement, direction si arrivée dans les 100 m.","lore":"Quand la proie franchit brutalement une frontière, le Limier ressent la cicatrice laissée par son départ. Type de transition, point d’arrachement et proximité éventuelle de l’arrivée composent un écho, pas une laisse qui suivrait automatiquement la cible.","groupe_actuel":"Chasse Fantastique — la Vénerie surnaturelle › Voie des Limiers","statut_regle":"correction","changements":"en-tête d''Écho du passage complété (réaction 1 PA). Ressort déjà distinct des autres marques : la Marque du Limier interdit l''effacement de la piste."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'chasse_fantastique_la_venerie_surnaturelle_voie_des_limiers_forcer_le_passage', 'Forcer le passage', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R, réaction 1 PA, 1/scène, après Écho du passage","activation":"Réaction 1 PA, 1/scène ; passage atteignable avec un Déplacement normal de soi ou monture, taille et autorisations respectées, pas de téléportation sans portail.","texte_court":"quand la proie marquée emprunte un passage traversable (portail, brèche, seuil dimensionnel), tu le franchis avant qu''il se ferme, avec ta monture si elle peut y entrer. Pas après une téléportation sans passage.","texte_reference":"R — Réaction 1 PA — 1/Scène — Prérequis : Écho du passage. Lorsqu’une proie marquée emprunte un passage réellement traversable — portail, brèche, seuil dimensionnel, porte spirituelle — et que le Limier est assez proche, il peut le franchir avant fermeture, avec sa Monture de Chasse si elle peut réellement y entrer. Ne suit pas une téléportation pure sans passage.\nConditions de résolution : Réaction 1 PA, 1/scène ; passage atteignable avec un Déplacement normal de soi ou monture, taille et autorisations respectées, pas de téléportation sans portail.","lore":"Le Limier connaît la différence entre perdre une proie et arriver une seconde trop tard au même seuil. Si le passage est encore là, il se jette dedans avant sa fermeture et refuse que la porte surnaturelle lui claque au museau.","groupe_actuel":"Chasse Fantastique — la Vénerie surnaturelle › Voie des Limiers","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'chasse_fantastique_la_venerie_surnaturelle_voie_des_limiers_hallali', 'Hallali', NULL, '{"nature":"humain","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, 1 PA, 20 m, 1/scène, après Marque du Limier","activation":"1 PA à 20 m, 1/scène ; le MJ vérifie ≤25 % PV, opposition occulte ; taxe +1 non cumulable, fuite physique conservée.","texte_court":"sur la proie marquée à 25 % de ses PV ou moins, V + MS contre Défense occulte. Réussite, jusqu''à la fin de sa prochaine activation : elle ne peut effacer sa signature ni se rendre inaccessible, et ses capacités de rupture coûtent +1 PA (maximum 3). Elle peut courir, voler, se battre.","texte_reference":"R — 1 PA — 1/Scène — Prérequis : Marque du Limier. Sur une proie marquée à 25 % de PV ou moins, Volonté + Maîtrise spirituelle contre Défense occulte. En réussite, jusqu’à la fin de sa prochaine activation elle ne peut effacer sa signature de chasse, devenir volontairement totalement inaccessible par immatérialité/retrait spirituel, et les capacités spécifiquement destinées à rompre la chasse coûtent +1 PA, maximum 3. Elle peut encore courir, voler ou se battre.\nConditions de résolution : 1 PA à 20 m, 1/scène ; le MJ vérifie ≤25 % PV, opposition occulte ; taxe +1 non cumulable, fuite physique conservée.","lore":"Le Hallali est réservé à la proie déjà poussée vers sa fin. Sa Trace devient presque impossible à étouffer et les échappatoires surnaturelles se referment autour d’elle, tandis que courir ou combattre restent des choix parfaitement possibles.","groupe_actuel":"Chasse Fantastique — la Vénerie surnaturelle › Voie des Limiers","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'humain', 'humain_chasse_fantastique_chevauchee', 'Chevauchée', NULL, '{"nature":"humain","forme":"une_porte","forme_lot":"1 porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"aucun. La voie demande une Monture de Chasse réelle, acquise dans la fiction."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'chasse_fantastique_la_venerie_surnaturelle_chevauchee_monture_du_seuil', 'Monture du seuil', NULL, '{"nature":"humain","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, passif","activation":"Même passage et même déplacement, aucune monture créée ni privilège de seuil supplémentaire.","texte_court":"quand un passage surnaturel te laisse passer, ta Monture de Chasse le franchit avec toi si elle peut l''emprunter. Ni taille, ni scellement, ni incompatibilité contournés.","texte_reference":"SR/R — Passif. Lorsqu’un passage surnaturel autorise normalement le Veneur à le franchir, sa Monture de Chasse peut le traverser avec lui si elle peut réellement emprunter ce passage. Ne contourne ni limite de taille, ni scellement, ni incompatibilité de Nature.\nConditions de résolution : Même passage et même déplacement, aucune monture créée ni privilège de seuil supplémentaire.","lore":"Une Monture de Chasse apprend à reconnaître les seuils que son cavalier peut lui-même emprunter. Elle suit à travers le passage comme un compagnon lié à la Vénerie, avec les mêmes contraintes de taille, de sceau et de Nature que tout être réel.","groupe_actuel":"Chasse Fantastique — la Vénerie surnaturelle › Chevauchée","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'chasse_fantastique_la_venerie_surnaturelle_chevauchee_meme_selle_meme_destin', 'Même selle, même destin', NULL, '{"nature":"humain","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, passif","activation":"Monture réelle liée et montée, Puissance du jet du Veneur contre tentative surnaturelle.","texte_court":"tant que tu es monté, un effet surnaturel qui cherche à te séparer de ta Monture doit vaincre ton V + MS. Chocs et chutes ordinaires fonctionnent.","texte_reference":"SR/R — Passif. Tant que le Veneur est monté, un effet surnaturel hostile visant spécifiquement à séparer directement le cavalier de sa Monture doit vaincre Volonté + Maîtrise spirituelle. Les chocs et séparations physiques ordinaires fonctionnent normalement.\nConditions de résolution : Monture réelle liée et montée, Puissance du jet du Veneur contre tentative surnaturelle.","lore":"Cavalier et Monture finissent par former un couple que les pouvoirs de séparation peinent à défaire. Ce lien n’empêche ni une chute ni un choc ; il refuse seulement qu’une volonté étrangère les traite comme deux pièces faciles à arracher l’une à l’autre.","groupe_actuel":"Chasse Fantastique — la Vénerie surnaturelle › Chevauchée","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'chasse_fantastique_la_venerie_surnaturelle_chevauchee_prendre_le_vent', 'Prendre le vent', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, passif, après Fenêtre de chasse","activation":"2 PTV et Fenêtre de chasse ; un PA, déplacement normal de la monture, pas cavalier plus monture successivement.","texte_court":"monté, l''action simple de Fenêtre de chasse peut utiliser le déplacement de ta monture. Toujours 1 PA, pas de mouvement en plus.","texte_reference":"SR/R — Passif — Prérequis : Fenêtre de chasse. Lorsque Fenêtre de chasse se déclenche alors que le Chasseur est monté, l’action simple autorisée peut employer le déplacement réel de sa Monture plutôt que le déplacement personnel. Toujours 1 PA ; aucun mouvement supplémentaire.\nConditions de résolution : Fenêtre de chasse ; un PA, déplacement normal de la monture, pas cavalier plus monture successivement.","lore":"Quand une proie cherche la fuite, le Veneur monté répond avec les jambes de sa Monture. La Fenêtre de chasse devient alors un bond de selle, un détour brutal ou une ruée exactement aussi réelle que le déplacement de la bête le permet.","groupe_actuel":"Chasse Fantastique — la Vénerie surnaturelle › Chevauchée","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'chasse_fantastique_la_venerie_surnaturelle_chevauchee_charge_irreelle', 'Charge irréelle', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R, 1/round, après Marque du Limier","activation":"Payer déplacement puis attaque de mêlée, 1/round, cible partiellement immatérielle réellement à portée.","texte_court":"après t''être rapproché d''une proie marquée avec ta monture, ta prochaine attaque de mêlée de l''activation peut toucher une cible partiellement immatérielle ou en phase. Aucun bonus.","texte_reference":"R — 1/round. Après avoir utilisé sa Monture pour se rapprocher directement d’une proie marquée, la prochaine attaque de mêlée avant la fin de l’activation peut affecter une cible partiellement immatérielle ou en phase. Aucun bonus d’attaque, de DGT ou d’Armure ignorée.\nConditions de résolution : Payer déplacement puis attaque de mêlée, 1/round, cible partiellement immatérielle réellement à portée.","lore":"Dans la Chevauchée, l’élan de la Monture entraîne la lame jusque sur le bord du monde matériel. Une proie en phase ou à demi immatérielle peut encore être heurtée lorsque cavalier et bête arrivent sur elle comme une seule charge.","groupe_actuel":"Chasse Fantastique — la Vénerie surnaturelle › Chevauchée","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'chasse_fantastique_la_venerie_surnaturelle_chevauchee_chevauchee_sauvage', 'Chevauchée sauvage', NULL, '{"nature":"humain","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, 2 PA, 1/scène","activation":"2 PA, 1/scène ; franchissement limité au Déplacement de la monture, opposition à la Puissance, espace d’arrivée valide, jamais matière pleine ordinaire.","texte_court":"toi et ta monture forcez une frontière surnaturelle ou une barrière de déplacement, V + MS contre sa Puissance. Réussite : vous traversez ensemble, dans la limite de son Déplacement. Jamais de la matière pleine.","texte_reference":"R — 2 PA — 1/Scène. Le Veneur et sa Monture forcent une frontière surnaturelle ou barrière de déplacement qui leur ferme la route. Volonté + Maîtrise spirituelle contre la Puissance de la barrière ; en réussite, ils traversent ensemble. Ne permet jamais de traverser une masse de matière ordinaire.\nConditions de résolution : 2 PA, 1/scène ; franchissement limité au Déplacement de la monture, opposition à la Puissance, espace d’arrivée valide, jamais matière pleine ordinaire.","lore":"La Chevauchée sauvage traite une frontière surnaturelle comme une haie à franchir. Veneur et Monture forcent ensemble le passage si celui-ci appartient réellement à la route, mais aucun galop ne transforme un mur ordinaire en portail.","groupe_actuel":"Chasse Fantastique — la Vénerie surnaturelle › Chevauchée","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'humain', 'humain_chasse_fantastique_tempete_de_la_chasse', 'Tempête de la Chasse', NULL, '{"nature":"humain","forme":"une_porte","forme_lot":"1 porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"aucun. Ressort déjà distinct des autres zones d''interdiction : la Tempête ne touche que la Magie."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'chasse_fantastique_la_venerie_surnaturelle_tempete_de_la_chasse_flair_de_la_tempete', 'Flair de la Tempête', NULL, '{"nature":"humain","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, passif, 10 m","activation":"Détection passive à 10 m ; un usage réellement magique actif, direction seulement, dissimulation dédiée peut opposer sa Puissance.","texte_court":"tu sens quand une Magie explicite est activement utilisée près de toi : présence, direction, et si visible, si le foyer est une créature, un objet ou le lieu. Ni école, ni sort, ni identité.","texte_reference":"SR/R — Passif. Percevoir instinctivement lorsqu’une Magie explicite est activement utilisée à proximité : présence, direction générale et, si visible, si le foyer vient plutôt d’une créature, d’un objet ou du lieu. Ne révèle ni école, sort, identité ni fonctionnement.\nConditions de résolution : Détection passive à 10 m ; un usage réellement magique actif, direction seulement, dissimulation dédiée peut opposer sa Puissance.","lore":"Pour ceux qui ont appris à sentir la Tempête, une magie proche change la pression du monde. Le Veneur perçoit qu’un foyer travaille et d’où vient grossièrement le trouble, sans que cette sensation lui explique quel sort est lancé.","groupe_actuel":"Chasse Fantastique — la Vénerie surnaturelle › Tempête de la Chasse","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'chasse_fantastique_la_venerie_surnaturelle_tempete_de_la_chasse_vent_de_rupture', 'Vent de rupture', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R, réaction 1 PA, 1/round","activation":"Réaction 1 PA après votre défense réussie, 1/round ; dissiper seulement la part persistante appliquée à vous, ni dégâts déjà subis ni effets sur autrui.","texte_court":"après ta Défense ou résistance réussie contre un effet magique qui te vise, ses composantes persistantes sur toi sont dissipées. Pas les autres pouvoirs surnaturels.","texte_reference":"R — Réaction 1 PA — 1/round. Après une Défense ou résistance réussie contre un effet explicitement magique qui cible le Chasseur, les composantes persistantes de cet effet sur lui sont également dissipées. Ne concerne pas les pouvoirs surnaturels non magiques.\nConditions de résolution : Réaction 1 PA après votre défense réussie, 1/round ; dissiper seulement la part persistante appliquée à vous, ni dégâts déjà subis ni effets sur autrui.","lore":"Un Veneur qui vient de repousser une magie peut laisser le Vent de rupture balayer ce qu’elle cherchait encore à maintenir sur lui. L’effet persistant part avec le courant, tandis que les autres formes de surnaturel restent étrangères à cette discipline.","groupe_actuel":"Chasse Fantastique — la Vénerie surnaturelle › Tempête de la Chasse","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'chasse_fantastique_la_venerie_surnaturelle_tempete_de_la_chasse_courant_dissipateur', 'Courant dissipateur', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R, 1 PA, 10 m, 1/scène","activation":"1 PA à 10 m, 1/scène ; un effet magique actif perçu, opposition à sa Puissance, durée courte inchangée.","texte_court":"contre un effet magique actif perçu (barrière, enchantement, sort maintenu, illusion, invocation), V + MS contre sa Puissance. Réussite : suspendu jusqu''à la fin de la prochaine activation de sa source. Pas la Nature de Mage.","texte_reference":"R — 1 PA — 1/Scène. Diriger un fragment du courant anti-magique contre un effet magique actif et perceptible. Volonté + Maîtrise spirituelle contre sa Puissance ; en réussite, l’effet est suspendu jusqu’à la fin de la prochaine activation de sa source. Peut viser barrière, enchantement, sort maintenu, illusion magique ou invocation soutenue ; pas Nature de Mage ou effet devenu autonome.\nConditions de résolution : 1 PA à 10 m, 1/scène ; un effet magique actif perçu, opposition à sa Puissance, durée courte inchangée.","lore":"La Tempête de la Chasse porte un courant qui ne nourrit pas la magie : il la défait. Le Veneur dirige cette turbulence contre une structure active et cherche à la dénouer assez longtemps pour que le sort cesse de tenir.","groupe_actuel":"Chasse Fantastique — la Vénerie surnaturelle › Tempête de la Chasse","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'chasse_fantastique_la_venerie_surnaturelle_tempete_de_la_chasse_foudre_dispersante', 'Foudre dispersante', NULL, '{"nature":"humain","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, réaction 1 PA, 20 m, 1/scène, après Courant dissipateur","activation":"Réaction 1 PA, 1/scène, activation magique à 20 m perçue ; premier effet instantané résolu, aucune composante persistante ensuite, opposition à sa Puissance.","texte_court":"quand une Magie est activée, V + MS contre sa Puissance. Réussite : son premier effet instantané se produit, puis sa structure se brise ; rien de persistant ne demeure.","texte_reference":"R — Réaction 1 PA — 1/Scène — Prérequis : Courant dissipateur. Lorsqu’une Magie est activée à portée de perception, Volonté + Maîtrise spirituelle contre son résultat d’activation ou sa Puissance. En réussite, elle produit son premier effet instantané puis sa structure est brisée : aucune composante persistante ne demeure. Ne remonte pas le temps pour annuler ce qui vient déjà d’arriver.\nConditions de résolution : Réaction 1 PA, 1/scène, activation magique à 20 m perçue ; premier effet instantané résolu, aucune composante persistante ensuite, opposition à sa Puissance.","lore":"La Foudre dispersante frappe après que la magie a déjà eu le temps d’exister une première fois. Elle ne nie pas l’instant passé : elle brise ce qui devait persister, comme un éclair déchirant les attaches encore tendues du sort.","groupe_actuel":"Chasse Fantastique — la Vénerie surnaturelle › Tempête de la Chasse","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'chasse_fantastique_la_venerie_surnaturelle_tempete_de_la_chasse_vortex_de_la_chasse', 'Vortex de la Chasse', NULL, '{"nature":"humain","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, 2 PA puis 1 PA par round, 1/scène, après Courant dissipateur","activation":"2 PA, rayon 3 m, maintien 1 PA/round, 1/scène ; alliés compris, Puissance fixée au départ, −2 Protection magique minimum 0, une seule barrière équivalente.","texte_court":"dans 3 m autour de toi, alliés compris, toute nouvelle Magie Active doit aussi vaincre ton V + MS, fixé au départ ; en échec, PA dépensés et rien ne se forme. Les Protections magiques y perdent 2 (minimum 0).","texte_reference":"R — 2 PA — maintien 1 PA/round — 1/Scène — Prérequis : Courant dissipateur. Créer autour de soi un micro-écho du courant de la Chasse. Dans quelques mètres, toute nouvelle Magie Active doit également vaincre Volonté + Maîtrise spirituelle du Chasseur ; en échec les PA sont dépensés mais l’effet ne se structure pas. Les Protections explicitement magiques subissent −2 Protection. Passifs, Nature et effets autonomes persistent.\nConditions de résolution : 2 PA, rayon 3 m, maintien 1 PA/round, 1/scène ; alliés compris, Puissance fixée au départ, −2 Protection magique minimum 0, une seule barrière équivalente.","lore":"Le Vortex est une petite tempête anti-magique maintenue autour du Chasseur. Chaque nouvelle construction magique doit parvenir à se former dans ce vent contraire, et les protections faites de sortilèges y perdent une partie de leur assise.","groupe_actuel":"Chasse Fantastique — la Vénerie surnaturelle › Tempête de la Chasse","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'humain', 'humain_chasse_fantastique_art_de_la_venerie', 'Art de la Vénerie', NULL, '{"nature":"humain","forme":"une_porte","forme_lot":"1 porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"en-tête tronqué de Grande Chasse réparé (« Prérequis : Cor de ch »). Ressort déjà distinct de la Battue sacrée (Arianwen) : ici la proie doit porter la Marque du Limier."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'chasse_fantastique_la_venerie_surnaturelle_art_de_la_venerie_cor_de_chasse', 'Cor de chasse', NULL, '{"nature":"humain","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"V/SR/R, 1 PA, scène","activation":"1 PA, trois membres volontaires à 20 m, scène ; partage de marque tant qu’un membre perçoit la proie et que le groupe reste dans les 100 m.","texte_court":"désigne une proie portant la Marque du Limier. Jusqu''à 3 membres volontaires à 20 m la traitent comme marquée pour leurs talents de Chasse Fantastique, tant qu''un membre la perçoit et que le groupe reste dans 100 m.","texte_reference":"V/SR/R — 1 PA. Désigner une proie portant la Marque du Limier. Jusqu’à trois membres consentants de la Chasse peuvent la considérer comme marquée pour leurs propres Talents de Chasse Fantastique tant qu’au moins un membre du groupe la perçoit directement. Pas de GPS ni de localisation si personne ne la perçoit.\nConditions de résolution : 1 PA, trois membres volontaires à 20 m, scène ; partage de marque tant qu’un membre perçoit la proie et que le groupe reste dans les 100 m.","lore":"Le Cor de chasse transmet moins un son qu’une désignation. Une proie déjà prise par un Limier devient la même proie pour les Veneurs qui répondent à l’appel, tant que quelqu’un la garde réellement dans la chasse.","groupe_actuel":"Chasse Fantastique — la Vénerie surnaturelle › Art de la Vénerie","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'chasse_fantastique_la_venerie_surnaturelle_art_de_la_venerie_relais_des_limiers', 'Relais des Limiers', NULL, '{"nature":"humain","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, passif, après Cor de chasse","activation":"Membres encore liés par Cor de chasse, proie vue par un membre ; aucun sens partagé, mur et vecteur de défense restent pertinents.","texte_court":"tant qu''un membre voit la proie désignée, les autres ne peuvent pas être Surpris par elle. Aucun sens partagé.","texte_reference":"SR/R — Passif — Prérequis : Cor de chasse. Tant qu’un membre du groupe perçoit clairement la proie désignée, les autres membres ne peuvent pas être considérés comme Surpris par une action provenant directement de cette proie. Ils ne voient pas à travers ses yeux.\nConditions de résolution : Membres encore liés par Cor de chasse, proie vue par un membre ; aucun sens partagé, mur et vecteur de défense restent pertinents.","lore":"Les Limiers apprennent à faire circuler l’alerte sans partager leurs yeux. Si l’un tient la proie dans son attention, les autres sentent assez son attaque pour ne pas la recevoir comme un coup venu de nulle part.","groupe_actuel":"Chasse Fantastique — la Vénerie surnaturelle › Art de la Vénerie","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'chasse_fantastique_la_venerie_surnaturelle_art_de_la_venerie_rabattre_la_proie', 'Rabattre la proie', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"V/SR/R, réaction 1 PA, 1/round","activation":"Le second intervenant doit posséder Rabattre la proie ; réaction 1 PA, 1/round, une action simple à portée normale, aucune attaque ou action offerte à un allié.","texte_court":"quand la proie désignée rompt le contact avec un membre et entre dans ta zone d''intervention, tu fais une action simple pour fermer cette voie de fuite. Pas d''attaque. Il faut posséder ce talent pour l''utiliser.","texte_reference":"V/SR/R — Réaction 1 PA — 1/round. Lorsqu’une proie désignée se déplace volontairement pour rompre le contact avec un membre de la Chasse et entre dans la zone d’intervention d’un autre, ce second membre peut effectuer une action simple visant uniquement à fermer la nouvelle voie de fuite : déplacement, porte, monture, dispositif préparé. Pas d’attaque gratuite.\nConditions de résolution : Le second intervenant doit posséder Rabattre la proie ; réaction 1 PA, 1/round, une action simple à portée normale, aucune attaque ou action offerte à un allié.","lore":"Une battue réussie ne suit pas simplement la fuite : elle lui donne une direction. Quand la proie change de ligne, le Veneur déjà placé devant elle ferme le nouvel espace et transforme son mouvement en piège.","groupe_actuel":"Chasse Fantastique — la Vénerie surnaturelle › Art de la Vénerie","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'chasse_fantastique_la_venerie_surnaturelle_art_de_la_venerie_battue_volante', 'Battue volante', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R, passif","activation":"Deux positions à 20 m, +1 PA de fuite non cumulable avec une autre battue, sans abaisser un coût >3.","texte_court":"deux membres coordonnés perçoivent la même proie marquée depuis deux positions à 20 m. Ses capacités de fuite immédiate coûtent +1 PA (maximum 3, sans cumul de battues).","texte_reference":"R — Passif. Si au moins deux membres coordonnés perçoivent la même proie marquée depuis des positions différentes, les capacités surnaturelles directement destinées à quitter immédiatement la zone coûtent +1 PA, maximum 3.\nConditions de résolution : Deux positions à 20 m, +1 PA de fuite non cumulable avec une autre battue, sans abaisser un coût >3.","lore":"La Chasse Fantastique ne laisse pas une proie s’échapper par magie dès que plusieurs Veneurs referment le cercle. Deux regards venus d’angles distincts suffisent à donner au territoire lui-même l’allure d’une battue qui se resserre.","groupe_actuel":"Chasse Fantastique — la Vénerie surnaturelle › Art de la Vénerie","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'chasse_fantastique_la_venerie_surnaturelle_art_de_la_venerie_grande_chasse', 'Grande Chasse', NULL, '{"nature":"humain","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, 1 PA par participant, au moins 3, 1/scène, après Cor de chasse et Battue volante","activation":"3 participants à 20 m de la proie, 1 PA chacun, 1/scène ; rayon d’engagement 20 m, opposition à la meilleure Puissance fixée au rite, cesse sous trois participants.","texte_court":"tant que trois participants restent engagés à 20 m : la proie reste identifiée par tous tant qu''un la perçoit, ne peut effacer sa trace, et doit vaincre le meilleur V + MS du groupe, fixé au rite, pour quitter la zone par un moyen surnaturel. Vous savez quand elle tente de rompre. Aucun PA ni attaque gratuits.","texte_reference":"R — 3 PA répartis entre au moins 3 participants — 1/Scène — Prérequis : Cor de chasse + Battue volante. Tant que trois participants restent opérationnels et engagés, la proie reste identifiée par tous tant qu’un membre la perçoit, ne peut supprimer entièrement sa Trace de chasse et doit vaincre la meilleure Volonté + Maîtrise spirituelle des participants pour quitter la zone par un passage ou déplacement surnaturel. Les Chasseurs savent immédiatement quand elle tente une rupture surnaturelle, mais ne gagnent aucun PA ni attaque gratuite.\nConditions de résolution : 3 participants à 20 m de la proie, 1 PA chacun, 1/scène ; rayon d’engagement 20 m, opposition à la meilleure Puissance fixée au rite, cesse sous trois participants.","lore":"La Grande Chasse commence lorsque plusieurs Veneurs cessent d’être des chasseurs séparés. Leur poursuite forme une seule meute surnaturelle : la Trace ne disparaît plus facilement et toute fuite hors de la scène doit lutter contre cette volonté collective.","groupe_actuel":"Chasse Fantastique — la Vénerie surnaturelle › Art de la Vénerie","statut_regle":"correction","changements":"en-tête tronqué de Grande Chasse réparé (« Prérequis : Cor de ch »). Ressort déjà distinct de la Battue sacrée (Arianwen) : ici la proie doit porter la Marque du Limier."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('couche', 'humain', 'humain_lueurs_d_azmenor', 'Lueurs d''Azménor', NULL, '{"nature":"humain","chemin":["Lueurs d''Azménor"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'humain', 'humain_lueurs_d_azmenor_visions_des_menaces', 'Visions des Menaces', NULL, '{"nature":"humain","forme":"une_porte","forme_lot":"1 porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"en-tête de Seuil de catastrophe complété (1 PA)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'lueurs_dazmenor_visions_et_neant_visions_des_menaces_echo_de_menace', 'Écho de Menace', NULL, '{"nature":"humain","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, passif, 1/scène, 20 m","activation":"Passif, 1/scène, rayon 20 m ; seul début effectif d’une menace surnaturelle latente, aucune identité ou direction ajoutée.","texte_court":"quand une puissance latente devient une Menace active, tu sens que « quelque chose vient de commencer ». Rien de plus.","texte_reference":"SR/R — Passif — 1/Scène. Lorsqu’une puissance surnaturelle jusque-là latente dans l’environnement commence effectivement à devenir une Menace active, le Lueur ressent brusquement que « quelque chose vient de commencer ». Aucun renseignement automatique sur la nature, l’identité ou la solution.\nConditions de résolution : Passif, 1/scène, rayon 20 m ; seul début effectif d’une menace surnaturelle latente, aucune identité ou direction ajoutée.","lore":"Lorsqu’une puissance latente cesse d’attendre et devient vraiment une Menace, le Lueur ressent l’instant de son démarrage. Il sait que quelque chose vient de commencer, et rien de plus jusqu’à ce que l’enquête donne un visage à cette alerte.","groupe_actuel":"Lueurs d’Azménor — visions et Néant › Visions des Menaces","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'lueurs_dazmenor_visions_et_neant_visions_des_menaces_vision_de_menace', 'Vision de Menace', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, rituel de 10 minutes, 1/scénario","activation":"10 minutes, 1/scénario ; menace déjà en mouvement dans les prochaines 24 h, fragment vrai lié à la cible désignée, vision vide si rien de pertinent.","texte_court":"sur une personne, un lieu, un objet ou une situation, le MJ donne un fragment vrai de la Menace déjà en mouvement la plus susceptible de la frapper dans les 24 heures. Vision vide s''il n''y en a pas.","texte_reference":"SR/R — Rituel — 1/Scénario. Méditer sur une personne, un lieu, un objet ou une situation réellement désignable et demander quelle Menace surnaturelle déjà en mouvement est la plus susceptible de le frapper prochainement. Le MJ donne un fragment sensoriel vrai : image, parole, sensation, symbole réellement lié ou scène très courte. Si aucune Menace pertinente n’est déjà en mouvement, la vision reste vide.\nConditions de résolution : 10 minutes, 1/scénario ; menace déjà en mouvement dans les prochaines 24 h, fragment vrai lié à la cible désignée, vision vide si rien de pertinent.","lore":"En méditant sur une personne, un lieu ou un objet précis, le Lueur laisse le Néant lui montrer la Menace surnaturelle déjà en train de s’en approcher. La vision vient sous forme de fragment vrai, jamais d’encyclopédie ni de prophétie inventant un danger absent.","groupe_actuel":"Lueurs d’Azménor — visions et Néant › Visions des Menaces","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'lueurs_dazmenor_visions_et_neant_visions_des_menaces_fil_de_convergence', 'Fil de convergence', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, 1 PA, 1/scène","activation":"1 PA, 1/scène ; deux éléments personnellement perçus, lien surnaturel réel seulement.","texte_court":"deux éléments surnaturels que tu as perçus appartiennent-ils à la même Menace ? Oui, non ou lien indirect. Jamais la nature du lien.","texte_reference":"SR/R — 1 PA — 1/Scène. Après avoir personnellement perçu deux phénomènes, individus, objets ou manifestations surnaturelles, demander s’ils appartiennent réellement à la même Menace ou chaîne surnaturelle. Réponse : oui / non / lien indirect. Le Talent n’explique pas la nature du lien.\nConditions de résolution : 1 PA, 1/scène ; deux éléments personnellement perçus, lien surnaturel réel seulement.","lore":"Deux phénomènes surnaturels peuvent sembler voisins sans appartenir à la même histoire. Le Fil de convergence répond uniquement à cette question de parenté : même Menace, aucun lien, ou connexion indirecte encore à découvrir.","groupe_actuel":"Lueurs d’Azménor — visions et Néant › Visions des Menaces","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'lueurs_dazmenor_visions_et_neant_visions_des_menaces_seuil_de_catastrophe', 'Seuil de catastrophe', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, 1 PA, 1/scène","activation":"1 PA, 1/scène ; une condition concrète déjà en place pour le prochain seuil seulement, aucune solution automatiquement donnée.","texte_court":"sur une Menace identifiée, le MJ indique une condition concrète, déjà en place, qui lui ferait franchir son prochain seuil. Pas la solution.","texte_reference":"SR/R — 1/Scène. Sur une Menace réellement identifiée, demander quel événement concret permettrait à cette Menace de franchir son prochain seuil d’aggravation. Le MJ indique une condition réelle déjà inscrite dans la situation. Le Talent ne donne pas la solution permettant de l’empêcher.\nConditions de résolution : 1 PA, 1/scène ; une condition concrète déjà en place pour le prochain seuil seulement, aucune solution automatiquement donnée.","lore":"Une Menace en mouvement possède souvent un prochain point de bascule déjà inscrit dans la situation. Le Lueur voit l’événement qui lui permettrait de franchir ce seuil, mais pas la méthode qui empêcherait nécessairement qu’il survienne.","groupe_actuel":"Lueurs d’Azménor — visions et Néant › Visions des Menaces","statut_regle":"correction","changements":"en-tête de Seuil de catastrophe complété (1 PA)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'lueurs_dazmenor_visions_et_neant_visions_des_menaces_avenir_sans_intervention', 'Avenir sans intervention', NULL, '{"nature":"humain","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, rituel de 30 minutes, 1/scénario, après Vision de Menace","activation":"30 minutes, 1/scénario, une conséquence majeure et un signe d’invalidation, jamais destin fixé par le MJ après usage.","texte_court":"le MJ donne une conséquence majeure probable si personne n''intervient, un fragment de la scène, et un signe concret qui montrera que cet avenir cesse d''être valable. Jamais un destin fixé.","texte_reference":"R — Rituel — 1/Scénario — Prérequis : Vision de Menace. Contempler la trajectoire probable d’une Menace si personne n’intervient significativement. Le MJ donne une conséquence majeure probable, un fragment de la scène correspondante et un signe concret indiquant que cet avenir commence à ne plus être valable. Il ne s’agit jamais d’un destin fixe.\nConditions de résolution : 30 minutes, 1/scénario, une conséquence majeure et un signe d’invalidation, jamais destin fixé par le MJ après usage.","lore":"Le Lueur contemple non le destin, mais l’inertie actuelle d’une Menace. Si personne ne change significativement la situation, une conséquence majeure se dessine avec le signe concret qui permettra plus tard de savoir que cette trajectoire a cessé d’être valable.","groupe_actuel":"Lueurs d’Azménor — visions et Néant › Visions des Menaces","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'humain', 'humain_lueurs_d_azmenor_purge_du_neant', 'Purge du Néant', NULL, '{"nature":"humain","forme":"une_porte","forme_lot":"1 porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"aucun. Purger la corruption est cohérent avec le chapitre Corruption (« moyen rare et explicitement capable de purifier la Source », points indiqués seulement). Ressorts déjà distincts : Silence de la Marque suspend une marque (une activation), l''Excommunication de Magdalena un canal (la scène)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'lueurs_dazmenor_visions_et_neant_purge_du_neant_toucher_dabsence', 'Toucher d''Absence', NULL, '{"nature":"humain","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, 1 PA, au contact","activation":"1 PA au contact ; famille générale seulement, masquage actif opposable, aucune révélation de fiche.","texte_court":"une modification surnaturelle est-elle intrinsèque ou imposée ? Si imposée, sa famille générale : Magie, Fléau, divine, possession ou autre source étrangère. Ni nom ni fonctionnement ; un masquage s''y oppose.","texte_reference":"SR/R — 1 PA. Au contact d’une créature affectée par une modification surnaturelle, déterminer si cette modification est intrinsèque à ce qu’elle est ou imposée de l’extérieur. Dans ce second cas, reconnaître sa famille générale : Magie, Fléau, divine, possession/parasitisme ou autre source étrangère comparable. Aucun nom ni fonctionnement précis.\nConditions de résolution : 1 PA au contact ; famille générale seulement, masquage actif opposable, aucune révélation de fiche.","lore":"Au contact, le Lueur sent si une modification appartient à l’être ou si elle lui a été ajoutée. Dans ce second cas, l’Absence reconnaît grossièrement la famille de l’intrus — Magie, Fléau, divin, possession ou autre puissance étrangère.","groupe_actuel":"Lueurs d’Azménor — visions et Néant › Purge du Néant","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'lueurs_dazmenor_visions_et_neant_purge_du_neant_purger_la_corruption', 'Purger la corruption', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R, rituel d''une heure, 1/scénario par cible, après Toucher d''Absence","activation":"1 heure, consentement, opposition à la Puissance ; retirer 1 point maximum par cible et scénario tous officiants confondus, aucune purification intrinsèque.","texte_court":"sur une cible consentante dont la Corruption vient d''une source surnaturelle extérieure, V + MS contre la Puissance de la source. Réussite : retire 1 point de Corruption (1 au plus par cible et par scénario, tous officiants confondus).","texte_reference":"R — Rituel prolongé — 1/Scénario par cible — Prérequis : Toucher d’Absence. Sur une cible consentante dont la Corruption provient réellement d’une source surnaturelle extérieure, Volonté + Maîtrise spirituelle contre la Puissance de cette source. En réussite, retirer 1 point de Corruption. Ne purifie ni une Nature ni une transformation devenue intrinsèque et ne retire pas une corruption volontairement embrassée devenue structurelle.\nConditions de résolution : 1 heure, consentement, opposition à la Puissance ; retirer 1 point maximum par cible et scénario tous officiants confondus, aucune purification intrinsèque.","lore":"La Purge du Néant traite certains points de Corruption comme la trace encore active d’une intrusion. Lorsque la souillure vient vraiment de l’extérieur et n’a pas été embrassée comme part de soi, un long rite peut en retrancher une parcelle.","groupe_actuel":"Lueurs d’Azménor — visions et Néant › Purge du Néant","statut_regle":"correction","changements":"aucun. Purger la corruption est cohérent avec le chapitre Corruption (« moyen rare et explicitement capable de purifier la Source », points indiqués seulement). Ressorts déjà distincts : Silence de la Marque suspend une marque (une activation), l''Excommunication de Magdalena un canal (la scène)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'lueurs_dazmenor_visions_et_neant_purge_du_neant_defaire_la_chair_faussee', 'Défaire la chair faussée', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R, 2 PA au contact, ou rituel d''une heure","activation":"2 PA au contact pour effet temporaire/maintenu ; 1 heure pour modification durable encore soutenue ; opposition à sa Puissance, aucune reconstruction anatomique.","texte_court":"sur une altération corporelle imposée de l''extérieur, V + MS contre sa source. Une transformation temporaire prend fin (2 PA) ; une modification durable encore soutenue est retirée (1 heure). Ni Nature, ni physiologie naturelle, ni prothèse.","texte_reference":"R — 2 PA ou rituel selon la gravité. Sur une altération corporelle surnaturelle imposée de l’extérieur, Volonté + Maîtrise spirituelle contre sa source. Une transformation temporaire ou maintenue peut prendre fin ; une modification durable mais encore surnaturellement soutenue peut être retirée par un rituel prolongé. Ne retire jamais une physiologie naturelle, une Nature, une prothèse ou une modification matérielle autonome.\nConditions de résolution : 2 PA au contact pour effet temporaire/maintenu ; 1 heure pour modification durable encore soutenue ; opposition à sa Puissance, aucune reconstruction anatomique.","lore":"Le Lueur cherche dans la chair la transformation qui n’en fait pas vraiment partie. Si une puissance extérieure la soutient encore, le Néant peut retirer cette forme imposée sans prendre pour cible la physiologie naturelle ou une modification devenue matériellement autonome.","groupe_actuel":"Lueurs d’Azménor — visions et Néant › Purge du Néant","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'lueurs_dazmenor_visions_et_neant_purge_du_neant_silence_de_la_marque', 'Silence de la Marque', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R, 1 PA, 10 m, 1/scène","activation":"1 PA à 10 m, 1/scène ; une marque identifiée, opposition à sa Puissance, suspension de ses bénéfices actifs jusqu’à fin de prochaine activation.","texte_court":"sur une marque extérieure identifiée (faveur, bénédiction, pacte, investiture, marque divine ou de Fléau), V + MS contre sa Puissance. Réussite : ses bénéfices actifs sont suspendus jusqu''à la fin de la prochaine activation de la cible. Ni Nature, ni Patron, ni Empreinte.","texte_reference":"R — 1 PA — 1/Scène. Après avoir identifié une marque surnaturelle extérieure — faveur, bénédiction, pacte, sceau d’investiture, marque divine ou de Fléau — opposer Volonté + Maîtrise spirituelle à sa Puissance. En réussite, les bénéfices actifs directement accordés par cette marque sont suspendus jusqu’à la fin de la prochaine activation de la cible. Ne retire ni Nature, ni Patron, ni Empreinte fondamentale.\nConditions de résolution : 1 PA à 10 m, 1/scène ; une marque identifiée, opposition à sa Puissance, suspension de ses bénéfices actifs jusqu’à fin de prochaine activation.","lore":"Une faveur ou une marque extérieure peut être privée momentanément de sa voix. Le Lueur n’arrache ni Patron ni identité profonde ; il place seulement dans le silence les bénéfices que ce lien accordait activement.","groupe_actuel":"Lueurs d’Azménor — visions et Néant › Purge du Néant","statut_regle":"correction","changements":"aucun. Purger la corruption est cohérent avec le chapitre Corruption (« moyen rare et explicitement capable de purifier la Source », points indiqués seulement). Ressorts déjà distincts : Silence de la Marque suspend une marque (une activation), l''Excommunication de Magdalena un canal (la scène)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'lueurs_dazmenor_visions_et_neant_purge_du_neant_puits_dabsence', 'Puits d''Absence', NULL, '{"nature":"humain","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, 3 PA au contact, 1/scène, après Purger la corruption et Défaire la chair faussée","activation":"3 PA au contact, 1/scène ; même jet comparé séparément à chaque Puissance extérieure ; seuls effets vaincus suspendus, bénéfiques inclus.","texte_court":"un seul jet de V + MS, opposé séparément à chaque influence extérieure de corruption, de chair faussée ou de délégation présente. Seules les vaincues sont suspendues pour la scène, bénéfiques comprises. Ni Nature ni Corruption acquise.","texte_reference":"Pour 3 PA au contact, une fois par scène, opposez un même jet de Volonté + Maîtrise spirituelle séparément à la Puissance de chaque influence extérieure de corruption, de chair faussée ou de délégation surnaturelle présente. Seuls les effets vaincus sont suspendus pour la scène, y compris les effets bénéfiques. Ni Nature intrinsèque ni Corruption acquise ne sont supprimées.","lore":"Le Puits d’Absence est volontairement indifférent à la notion de bénéfice. Sur une cible offerte au rite, il fait taire pour la scène les influences extérieures de Magie, Fléau ou Marque divine, bénédictions comme malédictions, en laissant intact ce qui est réellement intrinsèque.","groupe_actuel":"Lueurs d’Azménor — visions et Néant › Purge du Néant","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'humain', 'humain_lueurs_d_azmenor_extinction', 'Extinction', NULL, '{"nature":"humain","forme":"une_porte","forme_lot":"1 porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"**ressort propre ajouté** à Interdit du Néant : l''extinction est muette (la cible ignore sa source) et ne vise qu''une famille reconnue. Avant, il était identique à Interdit de Bina (Kabbale)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'lueurs_dazmenor_visions_et_neant_extinction_signature_de_puissance', 'Signature de Puissance', NULL, '{"nature":"humain","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, passif","activation":"Manifestation directement perçue, pas d’analyse d’une Nature inactive ni d’identification automatique de source personnelle.","texte_court":"quand tu assistes à l''usage d''un pouvoir Actif, tu reconnais sa famille énergétique (magique, divine, Fléau, spirituelle, biologique, technomagique, Néant), et si deux capacités vues semblent venir de la même source. Ni nom, ni fiche.","texte_reference":"SR/R — Passif. Lorsqu’il assiste directement à l’utilisation d’un pouvoir surnaturel Actif, le Lueur reconnaît sa famille énergétique fondamentale : magique, divine, Fléau, spirituelle, biologique surnaturelle, technomagique, Néant ou équivalent. Il peut également reconnaître que deux capacités déjà observées semblent venir de la même source fondamentale. Aucun nom de Talent ni fiche de personnage.\nConditions de résolution : Manifestation directement perçue, pas d’analyse d’une Nature inactive ni d’identification automatique de source personnelle.","lore":"Les Lueurs ne lisent pas une fiche invisible : ils reconnaissent la texture fondamentale de ce qu’ils voient agir. Magie, divin, Fléau, esprit, biologie surnaturelle ou technomagie laissent des signatures assez différentes pour être comparées entre elles.","groupe_actuel":"Lueurs d’Azménor — visions et Néant › Extinction","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'lueurs_dazmenor_visions_et_neant_extinction_vide_entre_les_gestes', 'Vide entre les gestes', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R, réaction 1 PA, 1/scène par cible, 10 m","activation":"Réaction 1 PA immédiatement après l’usage observé à 10 m, 1/scène/cible ; une taxe en attente par capacité, +1 non cumulable, pas de réduction d’un coût >3.","texte_court":"juste après qu''une cible a utilisé une capacité Active, V + MS contre sa Défense occulte. Réussite : sa prochaine utilisation de cette capacité dans la scène coûte +1 PA (maximum 3). Une seule taxe en attente par capacité.","texte_reference":"R — Réaction 1 PA — 1/Scène par cible. Après avoir observé une cible utiliser une capacité surnaturelle Active, Volonté + Maîtrise spirituelle contre sa Défense occulte ou résistance appropriée. En réussite, la prochaine utilisation de cette capacité précise avant la fin de la scène coûte +1 PA, maximum 3. Une seule application en attente par capacité.\nConditions de résolution : Réaction 1 PA immédiatement après l’usage observé à 10 m, 1/scène/cible ; une taxe en attente par capacité, +1 non cumulable, pas de réduction d’un coût >3.","lore":"Après avoir vu un pouvoir s’ouvrir une première fois, le Lueur sait où glisser un fragment d’Absence avant son prochain usage. La même activation devient plus laborieuse, comme si un geste supplémentaire devait désormais franchir le vide installé entre ses étapes.","groupe_actuel":"Lueurs d’Azménor — visions et Néant › Extinction","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'lueurs_dazmenor_visions_et_neant_extinction_fracture_dextinction', 'Fracture d''Extinction', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R, 1/scène, sans PA","activation":"1/scène après blessure, opposition de Volonté + Maîtrise spirituelle à la Puissance de cette Protection ; suspension courte, aucune Armure matérielle retirée.","texte_court":"après une blessure, V + MS contre la Puissance d''une Protection active identifiée de la cible. Réussite : cette Protection est suspendue jusqu''à la fin de sa prochaine activation. Aucune armure matérielle retirée.","texte_reference":"Une fois par scène, après une blessure réelle, sans PA supplémentaire, opposez Volonté + Maîtrise spirituelle à la Puissance d’une Protection active identifiée de la cible. Une réussite suspend cette seule Protection jusqu’à la fin de sa prochaine activation. Aucune Armure matérielle n’est retirée.","lore":"Une Signature reconnue donne au Lueur une prise sur la protection qui en procède. La blessure ouvre une fracture jusque dans ce rempart et le fait taire brièvement sans affecter l’armure matérielle portée dessous.","groupe_actuel":"Lueurs d’Azménor — visions et Néant › Extinction","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'lueurs_dazmenor_visions_et_neant_extinction_interdit_du_neant', 'Interdit du Néant', NULL, '{"nature":"humain","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, 1 PA, 10 m, 1/scène, après Signature de Puissance","activation":"1 PA à 10 m, 1/scène ; une capacité Active seulement, pas de famille entière ni de Nature.","texte_court":"l''extinction est muette : la cible ne sait pas d''où elle vient. Sur une capacité Active que tu as vue et dont tu as reconnu la famille, V + MS contre sa Défense occulte. Réussite : elle ne peut être activée jusqu''à la fin de la prochaine activation de la cible. Jamais une Nature entière ni « toute sa Magie ».","texte_reference":"R — 1 PA — 1/Scène — Prérequis : Signature de Puissance. Après avoir personnellement observé une capacité Active précise, Volonté + Maîtrise spirituelle contre la Défense occulte ou résistance appropriée de la cible. En réussite, cette capacité précise ne peut plus être activée jusqu’à la fin de la prochaine activation de la cible. Ne permet jamais d’interdire une Nature entière ou « toute sa Magie ».\nConditions de résolution : 1 PA à 10 m, 1/scène ; une capacité Active seulement, pas de famille entière ni de Nature.","lore":"Le Néant peut nier une possibilité précise sans prétendre avaler toute une Nature. Après avoir observé une capacité, le Lueur désigne exactement ce geste surnaturel et lui oppose pour quelques secondes un vide où il refuse de prendre forme.","groupe_actuel":"Lueurs d’Azménor — visions et Néant › Extinction","statut_regle":"correction","changements":"**ressort propre ajouté** à Interdit du Néant : l''extinction est muette (la cible ignore sa source) et ne vise qu''une famille reconnue. Avant, il était identique à Interdit de Bina (Kabbale)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'lueurs_dazmenor_visions_et_neant_extinction_chambre_dextinction', 'Chambre d''Extinction', NULL, '{"nature":"humain","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, 2 PA puis 1 PA par round, 1/scène","activation":"2 PA, rayon 3 m, maintien 1 PA/round, 1/scène ; famille reconnue définie par le référentiel, alliés compris, Puissance fixée au départ, aucune Natures/passifs annulés.","texte_court":"choisis une famille de puissance que tu as déjà reconnue. Dans 3 m autour de toi, alliés compris, toute nouvelle activation de cette famille doit aussi vaincre ton V + MS, fixé au départ ; en échec, PA dépensés et rien ne se forme. Passifs, Natures et effets autonomes continuent.","texte_reference":"R — 2 PA — maintien 1 PA/round — 1/Scène. Choisir une famille de puissance déjà personnellement reconnue. Dans quelques mètres autour du Lueur, toute nouvelle activation de cette famille doit également vaincre Volonté + Maîtrise spirituelle du Lueur. En échec, les PA sont dépensés mais l’effet n’arrive pas à se structurer. Passifs, Natures et effets déjà autonomes continuent.\nConditions de résolution : 2 PA, rayon 3 m, maintien 1 PA/round, 1/scène ; famille reconnue définie par le référentiel, alliés compris, Puissance fixée au départ, aucune Natures/passifs annulés.","lore":"La Chambre d’Extinction fait du Lueur un petit foyer de Néant dirigé contre une famille de puissance qu’il connaît déjà. Les nouvelles manifestations doivent parvenir à se structurer dans cette absence, tandis que les Natures et les effets devenus autonomes restent au-delà de sa portée.","groupe_actuel":"Lueurs d’Azménor — visions et Néant › Extinction","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'humain', 'humain_lueurs_d_azmenor_les_voix_dans_le_vide', 'Les Voix dans le Vide', NULL, '{"nature":"humain","forme":"une_porte","forme_lot":"1 porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"en-têtes complétés (1 PA ou réaction 1 PA) pour La voix derrière le mensonge, Conseil inhumain et Dernière Lueur. Ressort déjà distinct de Refus de mourir (Indépendants) : la Lueur est sauvée de tout effet surnaturel, une fois par scénario, pour 3 PTV ; le Survivant seulement d''une famille déjà affrontée."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'lueurs_dazmenor_visions_et_neant_les_voix_dans_le_vide_avertissement_impossible', 'Avertissement impossible', NULL, '{"nature":"humain","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, passif, 1/scène","activation":"Passif 1/scène ; uniquement votre action volontaire déclenchant immédiatement un phénomène surnaturel latent.","texte_court":"quand ton action volontaire va déclencher un piège ou phénomène surnaturel latent indétectable, une voix t''avertit une fraction de seconde avant. Tu peux renoncer ; tu ne sais pas ce qui allait arriver.","texte_reference":"SR/R — Passif — 1/Scène. Lorsqu’une action volontaire du personnage va déclencher immédiatement un piège ou phénomène surnaturel latent qu’il ne pouvait raisonnablement détecter, une voix, une sensation ou une vision l’avertit une fraction de seconde avant. Il peut renoncer à l’action. Il ne sait pas nécessairement ce qui allait arriver.\nConditions de résolution : Passif 1/scène ; uniquement votre action volontaire déclenchant immédiatement un phénomène surnaturel latent.","lore":"Les Voix ne préviennent pas de tous les dangers ; elles choisissent parfois celui que le Lueur allait déclencher de sa propre main sans aucun moyen de le savoir. Une image, un mot ou un frisson arrive juste assez tôt pour qu’il puisse s’arrêter.","groupe_actuel":"Lueurs d’Azménor — visions et Néant › Les Voix dans le Vide","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'lueurs_dazmenor_visions_et_neant_les_voix_dans_le_vide_la_voix_derriere_le_mensonge', 'La voix derrière le mensonge', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, réaction 1 PA, 1/scène","activation":"Réaction 1 PA, 1/scène ; nouvelle résistance complète contre la Puissance de la falsification actuelle, contradiction réelle, aucun nettoyage général de mémoire.","texte_court":"sous illusion, perception falsifiée, mémoire modifiée ou réalité mentale imposée, la Voix montre une contradiction réelle : nouveau test complet contre la Puissance de l''effet, même s''il n''en prévoit pas.","texte_reference":"SR/R — Réaction — 1/Scène. Sous illusion surnaturelle, falsification de perception, modification explicite de mémoire ou réalité mentale imposée, la Voix montre une contradiction réelle. Le personnage obtient immédiatement un nouveau test de résistance même si l’effet n’en prévoyait normalement pas. Ne concerne pas les corrections ordinaires de l’Hologramme auxquelles un véritable Chasseur n’est déjà plus soumis de la même manière.\nConditions de résolution : Réaction 1 PA, 1/scène ; nouvelle résistance complète contre la Puissance de la falsification actuelle, contradiction réelle, aucun nettoyage général de mémoire.","lore":"Sous une illusion ou une réalité mentale imposée, la Voix pointe une contradiction qui appartient réellement à la scène. Ce détail n’explique pas toute la falsification ; il suffit à rappeler au Lueur qu’il existe quelque chose contre quoi résister.","groupe_actuel":"Lueurs d’Azménor — visions et Néant › Les Voix dans le Vide","statut_regle":"correction","changements":"en-têtes complétés (1 PA ou réaction 1 PA) pour La voix derrière le mensonge, Conseil inhumain et Dernière Lueur. Ressort déjà distinct de Refus de mourir (Indépendants) : la Lueur est sauvée de tout effet surnaturel, une fois par scénario, pour 3 PTV ; le Survivant seulement d''une famille déjà affrontée."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'lueurs_dazmenor_visions_et_neant_les_voix_dans_le_vide_conseil_inhumain', 'Conseil inhumain', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, 1 PA, 1/scène","activation":"1 PA, 1/scène ; une action actuellement réalisable pour survivre à la prochaine activation, réponse vide si aucune possibilité, action ensuite payée normalement.","texte_court":"face à un danger surnaturel immédiat mal compris : « Quelle action à ma portée pourrait me faire survivre aux prochaines secondes ? » Le MJ donne une réponse concrète s''il en existe une. L''action se paie normalement.","texte_reference":"SR/R — 1/Scène. Face à un danger surnaturel immédiat dont le personnage comprend insuffisamment le fonctionnement, demander : « Quelle action actuellement à ma portée pourrait me permettre de survivre aux prochaines secondes ? » S’il existe une réponse concrète, le MJ en donne une. Le Talent ne promet ni victoire, ni faiblesse complète, ni solution de scénario.\nConditions de résolution : 1 PA, 1/scène ; une action actuellement réalisable pour survivre à la prochaine activation, réponse vide si aucune possibilité, action ensuite payée normalement.","lore":"Face à quelques secondes incompréhensibles, le Lueur peut demander au Vide non comment gagner, mais comment ne pas mourir tout de suite. La réponse est souvent froide et concrète, limitée aux actions réellement disponibles dans la scène.","groupe_actuel":"Lueurs d’Azménor — visions et Néant › Les Voix dans le Vide","statut_regle":"correction","changements":"en-têtes complétés (1 PA ou réaction 1 PA) pour La voix derrière le mensonge, Conseil inhumain et Dernière Lueur. Ressort déjà distinct de Refus de mourir (Indépendants) : la Lueur est sauvée de tout effet surnaturel, une fois par scénario, pour 3 PTV ; le Survivant seulement d''une famille déjà affrontée."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'lueurs_dazmenor_visions_et_neant_les_voix_dans_le_vide_contempler_labsence', 'Contempler l''Absence', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R, 1 PA, 10 m, 1/scène","activation":"1 PA, 10 m, 1/scène, jusqu’à fin du round ; phénomènes actifs d’effacement seulement, aucune carte générale du surnaturel.","texte_court":"jusqu''à la fin du round, tu perçois comme des vides les phénomènes actifs qui effacent ou excluent quelque chose de la Création (annihilation, brèche vers le Néant, disparition, désintégration). Rien d''autre.","texte_reference":"R — 1 PA — 1/Scène. Jusqu’à la fin du round, percevoir comme des vides ou déchirures les phénomènes surnaturels actifs qui retirent, annihilent, effacent ou excluent quelque chose de la Création : zone d’annihilation, brèche vers le Néant, disparition active, effet de désintégration surnaturelle ou principe comparable. Ce n’est pas une perception universelle du surnaturel.\nConditions de résolution : 1 PA, 10 m, 1/scène, jusqu’à fin du round ; phénomènes actifs d’effacement seulement, aucune carte générale du surnaturel.","lore":"Le Néant se reconnaît moins à ce qu’il montre qu’à ce qu’il retire. Pendant un instant, annihilation, brèche et effacement surnaturel apparaissent au Lueur comme des manques actifs dans la Création, trous que les sens ordinaires prendraient pour du rien.","groupe_actuel":"Lueurs d’Azménor — visions et Néant › Les Voix dans le Vide","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'lueurs_dazmenor_visions_et_neant_les_voix_dans_le_vide_derniere_lueur', 'Dernière Lueur', NULL, '{"nature":"humain","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, réaction 1 PA, 1/scénario","activation":"Réaction 1 PA, 1/scénario ; seuil de Mort +1 PV, pas de soin au-delà ni protection future, un seul sauvetage surnaturel par conséquence.","texte_court":"quand un effet surnaturel devrait t''amener à ton seuil de Mort ou au-delà, tu restes 1 PV au-dessus. Ni soin, ni protection contre le coup suivant ; un seul sauvetage par conséquence.","texte_reference":"R — Réaction — 1/Scénario. Lorsqu’un effet surnaturel devrait immédiatement amener le personnage à son seuil de Mort ou au-delà, il reste à 1 PV au-dessus de son seuil de Mort. Il n’est ni guéri ni protégé contre le coup suivant.\nConditions de résolution : Réaction 1 PA, 1/scénario ; seuil de Mort +1 PV, pas de soin au-delà ni protection future, un seul sauvetage surnaturel par conséquence.","lore":"Au moment où une puissance surnaturelle devrait pousser le corps au-delà de son dernier seuil, quelque chose refuse encore de s’éteindre. La Dernière Lueur ne guérit rien : elle conserve seulement un souffle de plus entre le personnage et la Mort.","groupe_actuel":"Lueurs d’Azménor — visions et Néant › Les Voix dans le Vide","statut_regle":"correction","changements":"en-têtes complétés (1 PA ou réaction 1 PA) pour La voix derrière le mensonge, Conseil inhumain et Dernière Lueur. Ressort déjà distinct de Refus de mourir (Indépendants) : la Lueur est sauvée de tout effet surnaturel, une fois par scénario, pour 3 PTV ; le Survivant seulement d''une famille déjà affrontée."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('couche', 'humain', 'humain_xenoshield', 'Xenoshield', NULL, '{"nature":"humain","chemin":["Xenoshield"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'humain', 'humain_xenoshield_detection_d_intrusion', 'Détection d''intrusion', NULL, '{"nature":"humain","forme":"une_porte","forme_lot":"1 porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"aucun."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'xenoshield_contre_intrusion_extral_detection_dintrusion_incompatibilite', 'Incompatibilité', NULL, '{"nature":"humain","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"V/SR/R, 1 PA, 3 m ou au contact d''un échantillon","activation":"1 PA, sujet à 3 m ou échantillon au contact ; exogénéité seulement, aucune hostilité ni forme vraie révélée.","texte_court":"tu sais si une créature, une trace ou un échantillon repose sur une biologie extraterrestre, même sous un camouflage parfait. Sous Hologramme : l''exogénéité seulement, jamais la forme, l''espèce ou les intentions.","texte_reference":"V/SR/R — 1 PA. En examinant directement une créature, un échantillon, une trace biologique ou une signature physique exploitable, déterminer si la continuité observée repose sur une biologie extraterrestre réelle, même lorsqu’un camouflage technologique ou biologique parfait empêcherait normalement de le prouver. Sous Hologramme, le Talent peut révéler l’exogénéité, jamais la véritable forme, l’espèce ou les intentions.\nConditions de résolution : 1 PA, sujet à 3 m ou échantillon au contact ; exogénéité seulement, aucune hostilité ni forme vraie révélée.","lore":"Un échantillon ou une signature physique peut révéler qu’une biologie n’appartient pas à la continuité terrestre même lorsque son camouflage est excellent. Le diagnostic établit l’exogénéité, jamais la véritable apparence ni les intentions cachées derrière elle.","groupe_actuel":"Xenoshield — contre-intrusion Extral › Détection d’intrusion","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'xenoshield_contre_intrusion_extral_detection_dintrusion_residu_dintrusion', 'Résidu d''intrusion', NULL, '{"nature":"humain","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"V/SR/R, 1 PA, 10 m","activation":"1 PA, rayon 10 m, fonctionnement alien dans les dernières 24 h ; indice résiduel uniquement, analyses techniques ensuite normales.","texte_court":"dans un lieu où une technologie extraterrestre a fonctionné dans les dernières 24 heures, tu perçois la rupture résiduelle et son point général. Investigation et Technologie font le reste.","texte_reference":"V/SR/R — 1 PA. Sur un lieu où une technologie extraterrestre a récemment fonctionné, percevoir une rupture résiduelle de paradigme même lorsqu’aucune trace conventionnelle exploitable n’aurait dû subsister. Le Talent indique qu’une technologie non terrestre a agi et le point général concerné ; Investigation et Technologie servent ensuite à exploiter cette information.\nConditions de résolution : 1 PA, rayon 10 m, fonctionnement alien dans les dernières 24 h ; indice résiduel uniquement, analyses techniques ensuite normales.","lore":"Une technologie non terrestre peut laisser derrière elle une rupture de paradigme là où aucun résidu matériel exploitable ne subsiste. Xenoshield repère le point où l’activité étrangère a eu lieu ; l’enquête ordinaire doit ensuite construire le reste.","groupe_actuel":"Xenoshield — contre-intrusion Extral › Détection d’intrusion","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'xenoshield_contre_intrusion_extral_detection_dintrusion_faux_humain', 'Faux humain', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, passif","activation":"À 2 PTV, après un round d’observation à 10 m, détecter passivement la falsification corporelle ; Incompatibilité reste nécessaire pour prouver la biologie extraterrestre.","texte_court":"après un round d''observation directe à 10 m, tu détectes une falsification de la physiologie d''une cible. Ni biologie extraterrestre ni hostilité prouvées : Incompatibilité reste nécessaire.","texte_reference":"Après un round d’observation directe d’une cible à 10 m, vous détectez passivement une falsification de sa physiologie ou de sa continuité corporelle. Cette constatation ne prouve ni une biologie extraterrestre ni une hostilité : Incompatibilité reste nécessaire pour établir l’exogénéité.","lore":"Certains camouflages aliens trompent parfaitement les analyses profanes tout en restant construits sur une continuité étrangère. Après observation suffisante, Xenoshield ressent cette incohérence et sait que le corps présenté n’est pas réellement ce qu’il prétend être.","groupe_actuel":"Xenoshield — contre-intrusion Extral › Détection d’intrusion","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'xenoshield_contre_intrusion_extral_detection_dintrusion_signature_impossible', 'Signature impossible', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, 1 PA, au contact ou 3 m","activation":"1 PA au contact d’un échantillon/appareil ou cible à 3 m ; répertoire des paradigmes réellement étudiés, aucune connaissance d’utilisation gratuite.","texte_court":"tu reconnais le paradigme d''une civilisation déjà étudiée, même si matériaux, architecture et apparence ont été changés. Aucun mode d''emploi offert.","texte_reference":"SR/R — 1 PA. Après avoir réellement étudié une technologie ou biologie d’une civilisation, reconnaître le même paradigme profond même si quelqu’un a volontairement changé matériaux, architecture, composants, apparence et signatures conventionnelles au point de rendre toute filiation profane indémontrable.\nConditions de résolution : 1 PA au contact d’un échantillon/appareil ou cible à 3 m ; répertoire des paradigmes réellement étudiés, aucune connaissance d’utilisation gratuite.","lore":"Après avoir étudié une civilisation, Xenoshield reconnaît sa manière profonde de résoudre un problème même lorsque matériaux, coque et signatures ont été volontairement changés. Le paradigme technique survit aux maquillages plus longtemps que l’apparence.","groupe_actuel":"Xenoshield — contre-intrusion Extral › Détection d’intrusion","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'xenoshield_contre_intrusion_extral_detection_dintrusion_pont_fantome', 'Pont fantôme', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R, 2 PA, 1/scène","activation":"2 PA, 1/scène, portée réelle du capteur plafonnée à 100 m, scène ; nœuds/transmissions actifs seulement, aucune compatibilité Neurodive ou décryption accordée.","texte_court":"avec un capteur terrestre adapté (100 m au plus), tu cartographies un réseau extraterrestre local : nœuds actifs, relais, directions. Aucun décryptage.","texte_reference":"R — 2 PA — 1/Scène. Avec un système terrestre de détection ou de transmission adapté, capter et cartographier localement un réseau extraterrestre utilisant un mode de communication normalement incompatible avec le matériel disponible. Identifier nœuds actifs, relais et directions de transmission. Aucun décryptage automatique du contenu, de l’identité ou de l’intention.\nConditions de résolution : 2 PA, 1/scène, portée réelle du capteur plafonnée à 100 m, scène ; nœuds/transmissions actifs seulement, aucune compatibilité Neurodive ou décryption accordée.","lore":"Avec un système terrestre adapté, Xenoshield force une écoute locale sur un mode de communication qui devrait lui être incompatible. Nœuds et directions apparaissent sur la carte sans que le contenu chiffré ou l’identité des interlocuteurs soit soudain décrypté.","groupe_actuel":"Xenoshield — contre-intrusion Extral › Détection d’intrusion","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'humain', 'humain_xenoshield_xenobiologie_hostile', 'Xénobiologie hostile', NULL, '{"nature":"humain","forme":"une_porte","forme_lot":"1 porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"en-tête de Contamination croisée complété (réaction 1 PA). Ressort déjà distinct des autres résistances accordées : ici Vigueur + Constitution et un agent biologique étranger."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'xenoshield_contre_intrusion_extral_xenobiologie_hostile_point_de_rupture', 'Point de rupture', NULL, '{"nature":"humain","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, 1 PA, 10 m","activation":"1 PA à 10 m après adaptation observée ; indiquer un point matériel effectivement atteignable, sans inventer vulnérabilité ni retirer sa protection.","texte_court":"après avoir vu une adaptation biologique extraordinaire, tu identifies un point matériel atteignable pour la perturber. Aucune vulnérabilité inventée.","texte_reference":"SR/R — 1 PA. Après avoir vu une créature utiliser une adaptation biologique extraordinaire précise, identifier un vecteur matériel concret permettant d’intervenir sur cette adaptation. Le Xenoshield ne comprend pas nécessairement toute l’anatomie ; il sait où ou comment il devient possible de perturber ce mécanisme.\nConditions de résolution : 1 PA à 10 m après adaptation observée ; indiquer un point matériel effectivement atteignable, sans inventer vulnérabilité ni retirer sa protection.","lore":"Voir une adaptation biologique en fonctionnement suffit parfois à comprendre où le monde matériel peut réellement agir sur elle. Xenoshield identifie le vecteur — organe, échange, stimulus ou point d’accès — sans prétendre avoir déjà cartographié toute l’anatomie extraterrestre.","groupe_actuel":"Xenoshield — contre-intrusion Extral › Xénobiologie hostile","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'xenoshield_contre_intrusion_extral_xenobiologie_hostile_blessure_xenologique', 'Blessure xénologique', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R, 1/scène, sans PA, après Point de rupture","activation":"Voir la résolution détaillée","texte_court":"après avoir blessé un Extral dont le mécanisme est identifié, Esprit + Science contre Vigueur + Constitution : un processus biologique observé (régénération, respiration secondaire, adhérence, changement de forme) est suspendu jusqu''à la fin de sa prochaine activation.","texte_reference":"R — 1/Scène — Prérequis : Point de rupture. Après une attaque réussie infligeant au moins 1 dégât réel à un Extral dont le mécanisme biologique concerné a été identifié, suspendre un processus biologique extraordinaire observé jusqu’à la fin de sa prochaine activation : régénération, respiration secondaire, adhérence, changement biologique de forme, production organique active ou équivalent cohérent.\nConditions de résolution : 1/scène après blessure du mécanisme identifié ; Esprit + Science adaptée contre Vigueur + Constitution, suspension jusqu’à fin de prochaine activation ; aucun organe vital supprimé.","lore":"Une attaque peut être placée pour atteindre le mécanisme biologique extraordinaire plutôt que la seule chair autour de lui. Après une vraie blessure, régénération, adhérence ou autre adaptation observée peut se taire jusqu’à la prochaine activation.","groupe_actuel":"Xenoshield — contre-intrusion Extral › Xénobiologie hostile","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'xenoshield_contre_intrusion_extral_xenobiologie_hostile_agent_incompatible', 'Agent incompatible', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, préparation de 4 heures, après Point de rupture","activation":"4 heures, laboratoire et échantillon ; une dose par préparation, exposition réelle, Vigueur + Constitution contre résultat de création ; une adaptation inhibée pour la scène.","texte_court":"avec échantillon et laboratoire, une dose d''inhibiteur contre un mécanisme identifié. Exposition réelle : Vigueur + Constitution contre ton résultat ; une adaptation inhibée pour la scène. Ni laboratoire ni matériaux fournis.","texte_reference":"SR/R — Préparation — Prérequis : Point de rupture. Avec échantillon, laboratoire terrestre adapté et temps, produire en quelques heures un inhibiteur temporaire contre un mécanisme biologique alien déjà identifié, même lorsque sa biochimie est trop étrangère pour que l’infrastructure disponible puisse normalement concevoir un agent fonctionnel. Le Talent ne fournit ni laboratoire ni matières premières.\nConditions de résolution : 4 heures, laboratoire et échantillon ; une dose par préparation, exposition réelle, Vigueur + Constitution contre résultat de création ; une adaptation inhibée pour la scène.","lore":"Une biologie alien comprise peut être attaquée même lorsque la pharmacologie terrestre ne possède normalement aucun produit adapté. Avec laboratoire, échantillon et temps, Xenoshield fabrique un inhibiteur temporaire contre le mécanisme précis déjà identifié.","groupe_actuel":"Xenoshield — contre-intrusion Extral › Xénobiologie hostile","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'xenoshield_contre_intrusion_extral_xenobiologie_hostile_contamination_croisee', 'Contamination croisée', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R, réaction 1 PA, 1/scène, 10 m","activation":"Réaction 1 PA, 1/scène, allié à 10 m ; nouveau test complet ou Vigueur + Constitution contre Puissance, sans antidote ou soin automatique.","texte_court":"un allié est exposé à une toxine, un parasite ou un agent infectieux non terrestre : tu le reconnais et il fait un nouveau test (sinon Vigueur + Constitution contre la Puissance de l''agent). Ni antidote ni soin.","texte_reference":"R — Réaction — 1/Scène. Lorsqu’un personnage proche est exposé à une toxine extraterrestre, un parasite biologique alien, un agent infectieux non terrestre ou une contamination organique inconnue, identifier immédiatement qu’il s’agit d’une interaction biologique étrangère et lui accorder un nouveau test de résistance. Si aucun test n’est normalement prévu, utiliser Vigueur + Constitution contre la Puissance de l’agent.\nConditions de résolution : Réaction 1 PA, 1/scène, allié à 10 m ; nouveau test complet ou Vigueur + Constitution contre Puissance, sans antidote ou soin automatique.","lore":"Toxine, parasite ou infection extraterrestre provoque des signes que Xenoshield sait reconnaître immédiatement comme interaction biologique étrangère. Cette identification permet au corps exposé de reprendre sa lutte avec une réponse adaptée au fait qu’il ne s’agit pas d’un agent terrestre.","groupe_actuel":"Xenoshield — contre-intrusion Extral › Xénobiologie hostile","statut_regle":"correction","changements":"en-tête de Contamination croisée complété (réaction 1 PA). Ressort déjà distinct des autres résistances accordées : ici Vigueur + Constitution et un agent biologique étranger."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'xenoshield_contre_intrusion_extral_xenobiologie_hostile_effondrement_adaptatif', 'Effondrement adaptatif', NULL, '{"nature":"humain","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, 1/scène, sans PA, après Blessure xénologique","activation":"1/scène après blessure ; Esprit + Science adaptée contre Vigueur + Constitution pour adaptation biologique, Puissance pour soutien technomagique distinct, sans deux défenses.","texte_court":"après avoir blessé une créature qui utilise une adaptation, Esprit + Science contre Vigueur + Constitution (Puissance pour un soutien technomagique) : l''adaptation choisie est neutralisée pour la scène. Jamais un cœur vital.","texte_reference":"R — 1/Scène — Prérequis : Blessure xénologique. Après avoir infligé au moins 1 dégât réel à une créature utilisant actuellement une adaptation biologique extraordinaire, Esprit + Science appropriée contre sa résistance biologique ou occulte. En réussite, une adaptation biologique active choisie est neutralisée jusqu’à la fin de la scène. Ne peut supprimer un cœur biologique fondamental de manière à provoquer une mort automatique.\nConditions de résolution : 1/scène après blessure ; Esprit + Science adaptée contre Vigueur + Constitution pour adaptation biologique, Puissance pour soutien technomagique distinct, sans deux défenses.","lore":"Lorsqu’une adaptation alien active a déjà été blessée et comprise, Xenoshield peut provoquer son effondrement pour toute la scène. La neutralisation vise la fonction extraordinaire, jamais le cœur vital dont la suppression transformerait l’analyse en mise à mort automatique.","groupe_actuel":"Xenoshield — contre-intrusion Extral › Xénobiologie hostile","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'humain', 'humain_xenoshield_contre_technologie', 'Contre-technologie', NULL, '{"nature":"humain","forme":"une_porte","forme_lot":"1 porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"en-tête de Court-circuit de paradigme complété (1 PA)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'xenoshield_contre_intrusion_extral_contre_technologie_interface_heretique', 'Interface hérétique', NULL, '{"nature":"humain","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, 1 PA","activation":"1 PA ; interface réellement atteignable, tests techniques et verrous biologiques intacts.","texte_court":"tu tentes d''utiliser une interface extraterrestre qui n''est pas faite pour toi. Les tests techniques et les verrous biologiques absolus restent ; tu accèdes aux fonctions identifiables.","texte_reference":"SR/R — 1 PA. Tenter d’utiliser une interface extraterrestre qui n’a pas été conçue pour la physiologie ou le paradigme du personnage, à condition qu’une interface réelle existe. Le test technique reste nécessaire lorsqu’il y a difficulté réelle. Permet des fonctions identifiables ; n’accorde ni compréhension complète ni contournement automatique d’un verrou biologique absolu.\nConditions de résolution : 1 PA ; interface réellement atteignable, tests techniques et verrous biologiques intacts.","lore":"Une interface étrangère reste une interface lorsqu’elle possède réellement commandes et retours exploitables. Xenoshield accepte de l’utiliser contre son ergonomie ou son paradigme d’origine sans confondre accès possible, compréhension complète et verrou biologique absolu.","groupe_actuel":"Xenoshield — contre-intrusion Extral › Contre-technologie","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'xenoshield_contre_intrusion_extral_contre_technologie_court_circuit_de_paradigme', 'Court-circuit de paradigme', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R, 1 PA, 1/scène","activation":"1 PA, 1/scène, interaction matérielle réelle ; Esprit + Technologie contre sécurité/Puissance du système, une fonction observée suspendue brièvement.","texte_court":"après avoir vu une technologie extraterrestre utiliser une fonction Active, interaction matérielle et Esprit + Technologie contre sa sécurité. Réussite : cette fonction est coupée jusqu''à la fin de la prochaine activation de son utilisateur.","texte_reference":"R — 1/Scène. Après avoir observé une technologie extraterrestre utiliser une fonction Active, provoquer une interruption ponctuelle par une interaction appropriée. En réussite, cette fonction précise ne peut plus être réutilisée jusqu’à la fin de la prochaine activation de son utilisateur. L’appareil entier n’est pas neutralisé.\nConditions de résolution : 1 PA, 1/scène, interaction matérielle réelle ; Esprit + Technologie contre sécurité/Puissance du système, une fonction observée suspendue brièvement.","lore":"Une fonction technologique observée révèle assez de son paradigme pour être interrompue ponctuellement. Xenoshield vise cette fonction exacte, pas l’appareil entier, et force son utilisateur à attendre avant de la réemployer.","groupe_actuel":"Xenoshield — contre-intrusion Extral › Contre-technologie","statut_regle":"correction","changements":"en-tête de Court-circuit de paradigme complété (1 PA)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'xenoshield_contre_intrusion_extral_contre_technologie_fenetre_de_brouillage', 'Fenêtre de brouillage', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R, réaction 1 PA, 1/scène","activation":"Réaction 1 PA, 1/scène ; portée effective de l’émetteur, une transmission précise, matériel non offert.","texte_court":"quand un appareil extraterrestre tente transmission, verrouillage, guidage, synchronisation ou télécommande, ton émetteur introduit une interférence : Esprit + Technologie contre le système ; réussite, l''échange échoue cette fois.","texte_reference":"R — Réaction 1 PA — 1/Scène. Lorsqu’un appareil extraterrestre perçu tente transmission, verrouillage de cible, guidage, synchronisation distante ou télécommande, utiliser un émetteur disponible pour introduire une interférence malgré l’incompatibilité de paradigme. Esprit + Technologie contre le système ; en réussite l’échange échoue cette fois-ci. Le Talent ne fournit pas le matériel.\nConditions de résolution : Réaction 1 PA, 1/scène ; portée effective de l’émetteur, une transmission précise, matériel non offert.","lore":"Au moment précis d’une transmission, d’un verrouillage ou d’un guidage alien, Xenoshield injecte avec un émetteur disponible une interférence que ce système n’était pas censé comprendre. Le matériel reste indispensable : la doctrine ne crée pas une radio dans les mains vides.","groupe_actuel":"Xenoshield — contre-intrusion Extral › Contre-technologie","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'xenoshield_contre_intrusion_extral_contre_technologie_boucle_de_retour', 'Boucle de retour', NULL, '{"nature":"humain","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, réaction 1 PA, 1/scène, après Court-circuit","activation":"Réaction 1 PA, 1/scène après votre Défense réussie ; fonction étudiée et vecteur matériel compatible, suspension seule, aucune attaque réfléchie.","texte_court":"quand une technologie déjà étudiée agit sur toi et que ta Défense ou résistance réussit, tu renvoies une contre-interaction par le même vecteur : la fonction est coupée jusqu''à la fin de la prochaine activation de sa source. Aucune attaque renvoyée.","texte_reference":"R — Réaction 1 PA — 1/Scène — Prérequis : Court-circuit de paradigme. Lorsqu’une technologie alien déjà étudiée agit directement sur le Xenoshield et que celui-ci réussit sa Défense ou résistance, renvoyer une contre-interaction par le même vecteur. La fonction utilisée est neutralisée jusqu’à la fin de la prochaine activation de sa source. Nécessite un moyen matériel permettant réellement l’interaction ; aucun effet sur biologie pure, Magie ou phénomène non technologique.\nConditions de résolution : Réaction 1 PA, 1/scène après votre Défense réussie ; fonction étudiée et vecteur matériel compatible, suspension seule, aucune attaque réfléchie.","lore":"Quand une technologie alien vient agir directement par un vecteur que Xenoshield a déjà réussi à repousser, celui-ci peut renvoyer l’interaction dans le même canal. La fonction source se grippe brièvement comme si son propre langage venait de se retourner contre elle.","groupe_actuel":"Xenoshield — contre-intrusion Extral › Contre-technologie","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'xenoshield_contre_intrusion_extral_contre_technologie_rupture_de_systeme', 'Rupture de système', NULL, '{"nature":"humain","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, 2 PA, 1/scène, après Court-circuit","activation":"2 PA, 1/scène ; interface, signal ou connexion matérielle réellement accessible, portée de ce moyen, Esprit + Technologie contre sécurité, une fonction Active pour la scène.","texte_court":"sur un dispositif dont tu as vu une fonction, par interface, signal ou connexion, Esprit + Technologie contre sa sécurité. Réussite : une fonction Active choisie est coupée pour la scène.","texte_reference":"R — 2 PA — 1/Scène — Prérequis : Court-circuit de paradigme. Sur un dispositif alien perçu dont au moins une fonction a déjà été observée, Esprit + Technologie contre sa sécurité ou résistance. En réussite, choisir une fonction technologique Active : elle est neutralisée jusqu’à la fin de la scène. Les fonctions indépendantes continuent et l’appareil n’est pas nécessairement détruit.\nConditions de résolution : 2 PA, 1/scène ; interface, signal ou connexion matérielle réellement accessible, portée de ce moyen, Esprit + Technologie contre sécurité, une fonction Active pour la scène.","lore":"Après avoir étudié une fonction alien en activité, Xenoshield peut pousser son contre-paradigme assez loin pour la neutraliser pendant toute la scène. Les autres sous-systèmes restent pourtant présents : saboter une fonction n’est pas vaporiser la machine.","groupe_actuel":"Xenoshield — contre-intrusion Extral › Contre-technologie","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'humain', 'humain_xenoshield_confinement_et_interception', 'Confinement et interception', NULL, '{"nature":"humain","forme":"une_porte","forme_lot":"1 porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"aucun. Ressort déjà distinct des autres zones d''interdiction : la Zone morte ne coupe que la technologie extraterrestre."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'xenoshield_contre_intrusion_extral_confinement_et_interception_marque_dinterception', 'Marque d''interception', NULL, '{"nature":"humain","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, 1 PA, analyse à 3 m ou échantillon","activation":"1 PA, analyse directe à 3 m ou échantillon ; une cible jusqu’à rupture volontaire, reconnaissance sur perception réelle, alerte d’extraction à 20 m maximum.","texte_court":"une seule cible. Tu la reconnais malgré changement d''identifiant, usurpation électronique ou camouflage technologique du même paradigme, et tu es averti quand son extraction technologique commence à 20 m au plus.","texte_reference":"SR/R — 1 PA. Après avoir analysé directement une cible, son équipement ou sa signature, fixer une signature d’interception. Une seule cible active. Le Xenoshield reconnaît ensuite la même cible malgré changement d’identifiant, spoofing électronique ou camouflage technologique du même paradigme. Il est également averti lorsqu’une extraction technologique de cette cible commence à portée de perception.\nConditions de résolution : 1 PA, analyse directe à 3 m ou échantillon ; une cible jusqu’à rupture volontaire, reconnaissance sur perception réelle, alerte d’extraction à 20 m maximum.","lore":"Après étude directe, une cible reçoit une signature d’interception qui survit aux changements d’identifiants et au camouflage du même paradigme technologique. Xenoshield ne sait pas où elle se trouve à distance ; il sait surtout quand cette signature recommence à préparer une extraction sous ses yeux.","groupe_actuel":"Xenoshield — contre-intrusion Extral › Confinement et interception","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'xenoshield_contre_intrusion_extral_confinement_et_interception_accrocher_le_signal', 'Accrocher le signal', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R, réaction 1 PA, 1/scène, après Marque d''interception","activation":"Réaction 1 PA, 1/scène ; portée réelle du matériel, opposition au système ; extraction reprend à l’échéance si conditions intactes, sans deuxième taxe automatique.","texte_court":"quand la cible marquée tente une extraction à distance, Esprit + Technologie contre le système : le processus est retardé jusqu''à la fin de sa prochaine activation.","texte_reference":"R — Réaction 1 PA — 1/Scène — Prérequis : Marque d’interception. Lorsqu’une cible marquée tente une extraction technologique à distance, utiliser un équipement compatible et opposer Esprit + Technologie au système d’extraction. En réussite, le processus est retardé jusqu’à la fin de la prochaine activation de la cible. Il n’est pas annulé définitivement.\nConditions de résolution : Réaction 1 PA, 1/scène ; portée réelle du matériel, opposition au système ; extraction reprend à l’échéance si conditions intactes, sans deuxième taxe automatique.","lore":"Une extraction alien laisse forcément un échange entre la cible et quelque chose qui vient la récupérer. Xenoshield accroche ce trafic avec son propre matériel et retarde le processus en refusant de lâcher le signal avant la prochaine fenêtre.","groupe_actuel":"Xenoshield — contre-intrusion Extral › Confinement et interception","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'xenoshield_contre_intrusion_extral_confinement_et_interception_mettre_a_terre', 'Mettre à terre', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R, réaction 1 PA, 1/scène, après Marque d''interception et Fenêtre de chasse","activation":"Voir la résolution détaillée","texte_court":"exception à Fenêtre de chasse : quand la cible marquée engage un déplacement extraordinaire par un mécanisme identifié, une attaque comprise dans la réaction. Blessure au mécanisme : ce mode est coupé jusqu''à la fin de sa prochaine activation.","texte_reference":"Exception explicite à Fenêtre de chasse : en réaction pour 1 PA, une fois par scène, lorsqu’une cible marquée engage un déplacement extraordinaire par un mécanisme identifié, effectuez UNE attaque comprise dans cette réaction, à portée réelle de votre arme. Une blessure réelle du mécanisme suspend ce seul mode de déplacement jusqu’à la fin de la prochaine activation de la cible. Aucun second PA de Fenêtre de chasse ni attaque supplémentaire.","lore":"Quand la proie tente de quitter physiquement le combat grâce à un mécanisme alien déjà identifié, Xenoshield frappe précisément ce système pendant la Fenêtre de chasse. Une vraie blessure peut alors neutraliser brièvement le moyen de mobilité sans créer un coup supplémentaire.","groupe_actuel":"Xenoshield — contre-intrusion Extral › Confinement et interception","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'xenoshield_contre_intrusion_extral_confinement_et_interception_zone_morte', 'Zone morte', NULL, '{"nature":"humain","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, 2 PA puis 1 PA par round, 1/scène","activation":"2 PA, rayon 3 m, maintien 1 PA/round, 1/scène ; appareils alliés compris, Puissance Esprit + Technologie fixée au départ, aucun blocage de biologie ou Magie.","texte_court":"avec un brouilleur, dans 3 m, appareils alliés compris, les communications, rappels, guidages et commandes distantes extraterrestres doivent vaincre ton Esprit + Technologie, fixé au départ. Ni Magie, ni télépathie, ni biologie.","texte_reference":"R — 2 PA — maintien 1 PA/round — 1/Scène. Avec un dispositif d’interférence approprié, créer une petite zone dans laquelle communications, rappels, guidages et commandes distantes extraterrestres doivent vaincre Esprit + Technologie du Xenoshield pour fonctionner. Ne bloque ni Magie, ni télépathie naturelle, ni biologie autonome.\nConditions de résolution : 2 PA, rayon 3 m, maintien 1 PA/round, 1/scène ; appareils alliés compris, Puissance Esprit + Technologie fixée au départ, aucun blocage de biologie ou Magie.","lore":"Le dispositif de brouillage crée un espace hostile aux communications extraterrestres. Rappel, guidage et télécommande doivent réussir à traverser ce bruit technique, tandis que télépathie naturelle, Magie et biologie autonome continuent de fonctionner selon leurs propres lois.","groupe_actuel":"Xenoshield — contre-intrusion Extral › Confinement et interception","statut_regle":"correction","changements":"aucun. Ressort déjà distinct des autres zones d''interdiction : la Zone morte ne coupe que la technologie extraterrestre."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'xenoshield_contre_intrusion_extral_confinement_et_interception_pas_de_recuperation', 'Pas de récupération', NULL, '{"nature":"humain","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, passif, après Marque d''interception et Mise à mort préparée","activation":"Bloquer les protocoles locaux identifiés pour la scène lors de Mise à mort, pas détruire un drone/sauvegarde distant ni empêcher une récupération physique ultérieure.","texte_court":"une Mise à mort préparée sur une cible extraterrestre bloque aussi pour la scène ses protocoles locaux identifiés (extraction du corps, téléchargement neural local, téléportation post-mortem, balise, drone récupérateur). Rien de distant.","texte_reference":"R — Passif — Prérequis : Marque d’interception + Mise à mort préparée. Lorsqu’une cible alien est neutralisée par Mise à mort préparée, neutraliser également ses protocoles de récupération immédiate correctement identifiés : extraction automatique du corps, upload neural local, téléportation post-mortem, balise de rappel ou drone récupérateur automatique. Ne détruit ni sauvegarde distante, ni clone ailleurs, ni récupération physique ultérieure.\nConditions de résolution : Bloquer les protocoles locaux identifiés pour la scène lors de Mise à mort, pas détruire un drone/sauvegarde distant ni empêcher une récupération physique ultérieure.","lore":"Une neutralisation n’est pas durable si un drone, un upload ou une balise emporte aussitôt la cible. Xenoshield inclut ces protocoles locaux dans sa préparation de mise à mort et les coupe avec le reste, sans atteindre les sauvegardes et clones situés ailleurs.","groupe_actuel":"Xenoshield — contre-intrusion Extral › Confinement et interception","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('couche', 'humain', 'humain_chasseurs_independants', 'Chasseurs indépendants', NULL, '{"nature":"humain","chemin":["Chasseurs indépendants"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'humain', 'humain_chasseurs_independants_survivant_de_l_impossible', 'Survivant de l''impossible', NULL, '{"nature":"humain","forme":"une_porte","forme_lot":"1 porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"en-têtes complétés (réaction 1 PA) pour Réflexe traumatique, Refus de mourir et Retour du prédateur."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'chasseurs_independants_heritages_modulaires_survivant_de_limpossible_reflexe_traumatique', 'Réflexe traumatique', NULL, '{"nature":"humain","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"V/SR/R, réaction 1 PA, 1/scène","activation":"Réaction 1 PA, 1/scène, une Défense ou protection simple seulement, aucune attaque supplémentaire.","texte_court":"quand une famille déjà affrontée déclenche contre toi une capacité que tu as déjà subie, tu fais une Défense active ou une action simple de protection, même Surpris. Aucun PA gratuit.","texte_reference":"V/SR/R — Réaction — 1/Scène. Lorsqu’une famille surnaturelle déjà réellement affrontée déclenche contre le Chasseur une capacité qu’il a personnellement déjà subie, il peut dépenser un PA déjà disponible pour effectuer une Défense active ou une action simple de protection même s’il aurait normalement été Surpris. Aucun PA gratuit.\nConditions de résolution : Réaction 1 PA, 1/scène, une Défense ou protection simple seulement, aucune attaque supplémentaire.","lore":"Un traumatisme peut devenir un réflexe utile lorsqu’il revient sous la même forme. Le corps du Survivant reconnaît une capacité déjà subie et trouve assez tôt la réaction de protection qu’il n’avait pas su produire la première fois.","groupe_actuel":"Chasseurs indépendants — Héritages modulaires › Survivant de l’impossible","statut_regle":"correction","changements":"en-têtes complétés (réaction 1 PA) pour Réflexe traumatique, Refus de mourir et Retour du prédateur."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'chasseurs_independants_heritages_modulaires_survivant_de_limpossible_refus_de_mourir', 'Refus de mourir', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"V/SR/R, réaction 1 PA, 1/scénario","activation":"Réaction 1 PA, 1/scénario, famille réellement affrontée, seuil de Mort +1 PV et règle d’un seul sauvetage par conséquence.","texte_court":"quand une conséquence surnaturelle d''une famille déjà affrontée devrait te faire franchir ton seuil de Mort, tu restes 1 PV au-dessus. Ni soin, ni protection contre le coup suivant.","texte_reference":"V/SR/R — Réaction — 1/Scénario. Lorsqu’une conséquence surnaturelle provenant d’une famille déjà réellement affrontée devrait lui faire franchir son seuil de Mort, le Chasseur reste à 1 PV au-dessus du seuil de Mort. Aucun soin ni protection contre le coup suivant.\nConditions de résolution : Réaction 1 PA, 1/scénario, famille réellement affrontée, seuil de Mort +1 PV et règle d’un seul sauvetage par conséquence.","lore":"Le Survivant a déjà franchi une fois la distance entre « impossible » et « encore vivant ». Face à une famille d’horreurs qu’il connaît réellement, ce vieux refus peut lui laisser un dernier souffle là où la conséquence aurait dû dépasser son seuil de mort.","groupe_actuel":"Chasseurs indépendants — Héritages modulaires › Survivant de l’impossible","statut_regle":"correction","changements":"en-têtes complétés (réaction 1 PA) pour Réflexe traumatique, Refus de mourir et Retour du prédateur."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'chasseurs_independants_heritages_modulaires_survivant_de_limpossible_cicatrice_revelatrice', 'Cicatrice révélatrice', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, passif, 10 m","activation":"Une cicatrice et une famille choisies à l’achat, détection passive à 10 m ; aucun dommage initial inventé ni source précisément localisée.","texte_court":"choisis à l''achat une cicatrice surnaturelle réelle et sa famille. Quand cette famille agit près de toi, la cicatrice réagit : tu sais que c''est là, pas où.","texte_reference":"SR/R — Passif. Choisir une altération surnaturelle durable réelle laissée par le passé : morsure, brûlure, marque de possession, cicatrice magique, implantation étrangère ou équivalent. Lorsque la même famille de puissance agit dans l’environnement immédiat, la cicatrice réagit. Le Chasseur sait uniquement que quelque chose de cette nature est actif à proximité.\nConditions de résolution : Une cicatrice et une famille choisies à l’achat, détection passive à 10 m ; aucun dommage initial inventé ni source précisément localisée.","lore":"La cicatrice surnaturelle n’est jamais complètement silencieuse. Quand la même famille de puissance travaille à proximité, elle tire, brûle ou résonne d’une manière que seul le survivant peut interpréter comme l’annonce d’un phénomène déjà connu.","groupe_actuel":"Chasseurs indépendants — Héritages modulaires › Survivant de l’impossible","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'chasseurs_independants_heritages_modulaires_survivant_de_limpossible_retour_du_predateur', 'Retour du prédateur', NULL, '{"nature":"humain","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, réaction 1 PA, 1/scène, après Cicatrice révélatrice","activation":"Réaction 1 PA, 1/scène ; exactement l’effet correspondant à la cicatrice, Volonté + Maîtrise spirituelle contre Puissance ; annule sur vous seulement.","texte_court":"quand une créature de cette famille déclenche contre toi exactement le type d''effet qui t''a marqué, V + MS contre sa Puissance. Réussite : il échoue sur toi cette fois.","texte_reference":"R — 1/Scène — Prérequis : Cicatrice révélatrice. Lorsqu’une créature de la famille correspondante déclenche contre le Chasseur exactement le type d’effet qui avait causé sa Cicatrice, Volonté + Maîtrise spirituelle contre la Puissance de l’effet. En réussite, l’effet échoue sur lui cette fois-ci.\nConditions de résolution : Réaction 1 PA, 1/scène ; exactement l’effet correspondant à la cicatrice, Volonté + Maîtrise spirituelle contre Puissance ; annule sur vous seulement.","lore":"Retour du prédateur rend tangible une structure cachée du monde. Ce qui n’était jusque-là qu’une intuition spirituelle ou occulte acquiert des contours assez nets pour être saisi, déplacé, renforcé ou contrarié par la volonté.","groupe_actuel":"Chasseurs indépendants — Héritages modulaires › Survivant de l’impossible","statut_regle":"correction","changements":"en-têtes complétés (réaction 1 PA) pour Réflexe traumatique, Refus de mourir et Retour du prédateur."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'humain', 'humain_chasseurs_independants_tradition_familiale', 'Tradition familiale', NULL, '{"nature":"humain","forme":"une_porte","forme_lot":"1 porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"Rite de la maison n''est plus « défini avec le MJ » : les quatre profils fermés de ses conditions deviennent le seul choix (correction de l''incohérence entre texte et conditions)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'chasseurs_independants_heritages_modulaires_tradition_familiale_signe_de_la_maison', 'Signe de la maison', NULL, '{"nature":"humain","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, préparation de 10 minutes, 24 heures","activation":"10 minutes, un seuil de 3 m, objet ou rayon 3 m ; 24 h ou premier déclenchement, signe visible au retour, aucune notification distante ajoutée.","texte_court":"un seuil de 3 m, un objet ou un rayon de 3 m. Si un représentant de la proie traditionnelle le franchit ou l''active, le signe change, même sans trace normale. Il ne localise pas.","texte_reference":"SR/R — Préparation. Préparer un seuil, un objet ou une petite zone contre la proie traditionnelle de la famille. Si un représentant de cette famille franchit ou active le dispositif, le signe se modifie surnaturellement même si le passage n’a laissé aucune trace normale ou était spirituel. Le Talent ne localise pas ensuite la créature.\nConditions de résolution : 10 minutes, un seuil de 3 m, objet ou rayon 3 m ; 24 h ou premier déclenchement, signe visible au retour, aucune notification distante ajoutée.","lore":"Le Signe de la maison attend une créature bien précise plutôt qu’un intrus quelconque. Si la proie historique franchit le seuil ou touche le support, le symbole change et témoigne de son passage même lorsqu’aucune trace matérielle n’aurait subsisté.","groupe_actuel":"Chasseurs indépendants — Héritages modulaires › Tradition familiale","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'chasseurs_independants_heritages_modulaires_tradition_familiale_rite_de_la_maison', 'Rite de la maison', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, rituel de 10 minutes, scène","activation":"Choisir UNE fonction à l’achat : seuil 3 m, détection 10 m, blocage de régénération un round ou refuge 3 m ; 10 minutes, scène, opposition à la Puissance pour effet hostile.","texte_court":"choisis une fonction à l''achat, efficace seulement contre la proie historique : seuil de 3 m qu''elle ne franchit pas, détection à 10 m, blocage de sa régénération un round, ou refuge de 3 m. Un effet hostile s''oppose à sa Puissance.","texte_reference":"SR/R — Rituel. Choisir une fonction surnaturelle étroite propre à la tradition familiale et uniquement efficace contre sa proie historique : empêcher son entrée dans un lieu, révéler sa présence, empêcher sa régénération, contenir temporairement son essence, protéger un dormeur ou fonction comparable. La fonction est définie avec le MJ lors de l’achat.\nConditions de résolution : Choisir UNE fonction à l’achat : seuil 3 m, détection 10 m, blocage de régénération un round ou refuge 3 m ; 10 minutes, scène, opposition à la Puissance pour effet hostile.","lore":"Chaque Maison possède un petit rite que les étrangers jugeraient souvent trop étroit pour mériter un traité. C’est précisément sa force : protéger un dormeur, marquer un seuil ou contenir l’essence d’une seule proie traditionnelle, mais le faire avec une fiabilité née des générations.","groupe_actuel":"Chasseurs indépendants — Héritages modulaires › Tradition familiale","statut_regle":"correction","changements":"Rite de la maison n''est plus « défini avec le MJ » : les quatre profils fermés de ses conditions deviennent le seul choix (correction de l''incohérence entre texte et conditions)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'chasseurs_independants_heritages_modulaires_tradition_familiale_arme_heritee', 'Arme héritée', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, préparation de 10 minutes","activation":"10 minutes par arme ou lot de 6 munitions réelles ; durée scène, composants consommés, propriété ciblée sur la proie familiale sans bonus de DGT.","texte_court":"une arme ordinaire ou un lot de 6 munitions acquiert pour la scène une résonance avec la faiblesse familiale connue. Composants consommés ; ni arme, ni faiblesse, ni dégâts fournis.","texte_reference":"SR/R — Préparation. La famille connaît un rite surnaturel permettant de préparer une catégorie d’arme ordinaire afin qu’elle acquière une résonance authentique avec une faiblesse familiale connue, même lorsque la simple fabrication moderne ne suffirait pas à produire cette propriété. Le Talent ne fournit ni l’arme, ni les composants, ni la faiblesse et n’ajoute aucun DGT générique.\nConditions de résolution : 10 minutes par arme ou lot de 6 munitions réelles ; durée scène, composants consommés, propriété ciblée sur la proie familiale sans bonus de DGT.","lore":"Certaines familles connaissent depuis des générations le rite qui rend leur arme pertinente contre leur ennemi historique. Ce savoir ne fournit ni acier ni munition : il apprend à préparer correctement un moyen réel pour qu’il porte la faiblesse transmise par la tradition.","groupe_actuel":"Chasseurs indépendants — Héritages modulaires › Tradition familiale","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'chasseurs_independants_heritages_modulaires_tradition_familiale_derniere_lecon', 'Dernière leçon', NULL, '{"nature":"humain","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, 1/scène, sans PA, après Rite de la maison","activation":"Sans PA supplémentaire, 1/scène après action réussie utilisant le secret ; une Protection/régénération/fuite explicitement incompatible, jusqu’à fin de prochaine activation.","texte_court":"après une action réussie qui exploite le secret de famille contre la proie historique, une Protection, une régénération ou une fuite directement incompatible avec cette faiblesse est suspendue jusqu''à la fin de sa prochaine activation.","texte_reference":"R — 1/Scène — Prérequis : Rite de la maison. Lorsqu’il exploite réellement le Secret de famille contre la proie traditionnelle, le Chasseur peut suspendre jusqu’à la fin de la prochaine activation de la cible un effet surnaturel de Protection, Régénération ou fuite directement incompatible avec cette faiblesse. Le Talent ne crée jamais cette incompatibilité.\nConditions de résolution : Sans PA supplémentaire, 1/scène après action réussie utilisant le secret ; une Protection/régénération/fuite explicitement incompatible, jusqu’à fin de prochaine activation.","lore":"La Dernière leçon est le secret qu’on ne révèle qu’au moment de finir la chasse. Lorsque la faiblesse familiale est réellement exploitée, elle peut fermer brièvement la voie de protection, de régénération ou de fuite qui aurait normalement permis au monstre d’échapper au coup.","groupe_actuel":"Chasseurs indépendants — Héritages modulaires › Tradition familiale","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'humain', 'humain_chasseurs_independants_bricoleur_de_verite', 'Bricoleur de Vérité', NULL, '{"nature":"humain","forme":"une_porte","forme_lot":"1 porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"en-tête de Surcharge impossible complété (1 PA)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'chasseurs_independants_heritages_modulaires_bricoleur_de_verite_interface_batarde', 'Interface bâtarde', NULL, '{"nature":"humain","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, préparation d''une heure au moins","activation":"Minimum 1 heure, composants identifiés, test technique normal si incertain ; une fonction existante par liaison, aucune duplication d’énergie ou d’objet.","texte_court":"tu fais fonctionner ensemble deux technologies ou principes de Vérité incompatibles, si tu possèdes les composants. Une fonction existante par liaison ; test technique si incertain.","texte_reference":"SR/R — Préparation. Faire fonctionner ensemble deux technologies ou principes de Vérité normalement incompatibles à condition de posséder réellement les composants. La capacité obtenue reste limitée aux fonctions déjà présentes dans les éléments et les Compétences techniques normales restent nécessaires lorsqu’il y a difficulté réelle.\nConditions de résolution : Minimum 1 heure, composants identifiés, test technique normal si incertain ; une fonction existante par liaison, aucune duplication d’énergie ou d’objet.","lore":"Le Bricoleur de Vérité ne cherche pas l’élégance : il cherche le point où deux principes incompatibles peuvent tout de même se parler. Les composants doivent exister et garder leurs fonctions réelles ; le génie consiste à leur fabriquer une interface provisoire.","groupe_actuel":"Chasseurs indépendants — Héritages modulaires › Bricoleur de Vérité","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'chasseurs_independants_heritages_modulaires_bricoleur_de_verite_relais_de_propriete', 'Relais de propriété', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, préparation, après Interface bâtarde","activation":"Associer le composant source à une fonction cible du montage, conserver ses coûts, portée et limites, aucune propriété créée.","texte_court":"une propriété surnaturelle réelle d''un composant passe dans une autre fonction du montage (une relique qui touche les esprits permet au capteur construit autour d''enregistrer ce contact). Rien d''inventé.","texte_reference":"SR/R — Préparation — Prérequis : Interface bâtarde. Faire traverser une propriété surnaturelle réelle d’un composant vers une autre fonction cohérente du montage. Une relique capable d’entrer en contact avec les esprits peut par exemple permettre à un capteur construit autour d’elle d’enregistrer ce contact. Aucun bonus générique de dégâts ni propriété inventée.\nConditions de résolution : Associer le composant source à une fonction cible du montage, conserver ses coûts, portée et limites, aucune propriété créée.","lore":"Une propriété surnaturelle peut parfois voyager à travers le bon montage. Le Bricoleur fait d’une relique, d’un fragment ou d’un matériau le relais par lequel une autre fonction acquiert exactement cette interaction — jamais une puissance inventée de toutes pièces.","groupe_actuel":"Chasseurs indépendants — Héritages modulaires › Bricoleur de Vérité","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'chasseurs_independants_heritages_modulaires_bricoleur_de_verite_surcharge_impossible', 'Surcharge impossible', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R, 1 PA, 1/scène","activation":"Voir la résolution détaillée","texte_court":"un dispositif hybride que tu as préparé dépasse une fois son interface : portée ou rayon ×2, ou fonctionnement sous alimentation insuffisante, ou tolérance d''un milieu précis. Puis il tombe en panne jusqu''à réparation.","texte_reference":"R — 1/Scène. Sur un dispositif hybride personnellement préparé, lui demander brièvement de fonctionner au-delà de son interface normale : portée ou zone doublée, fonctionnement sous alimentation insuffisante, tolérance momentanée à un environnement incompatible ou dépassement comparable validé. Après résolution, l’appareil cesse de fonctionner jusqu’à réparation.\nConditions de résolution : 1 PA, 1/scène ; choisir portée OU rayon ×2, alimentation insuffisante OU tolérance d’un milieu précis pour une utilisation ; panne ensuite, réparation réelle sans reset automatique.","lore":"Le dispositif hybride possède toujours une zone rouge que son fabricant connaît trop bien. Une fois par crise, il peut l’y pousser volontairement pour arracher une portée, une tolérance ou une alimentation qu’il ne devrait pas soutenir, puis accepter la panne qui suit.","groupe_actuel":"Chasseurs indépendants — Héritages modulaires › Bricoleur de Vérité","statut_regle":"correction","changements":"en-tête de Surcharge impossible complété (1 PA)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'chasseurs_independants_heritages_modulaires_bricoleur_de_verite_prototype_unique', 'Prototype unique', NULL, '{"nature":"humain","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, préparation de plusieurs heures ou jours, après Interface bâtarde et Relais de propriété","activation":"Voir la résolution détaillée","texte_court":"un dispositif qui produit une interaction de Vérité nouvelle à partir de composants réels. Sa fiche fixe composants, fonction unique, PA, portée, Puissance, durée, entretien et défaillance. Les PTV achètent le savoir-faire, jamais l''objet.","texte_reference":"R — Préparation prolongée — Prérequis : Interface bâtarde + Relais de propriété. Construire un dispositif capable de produire une interaction de Vérité nouvelle à partir de composants possédant réellement les propriétés nécessaires. Chaque Prototype est un objet de scénario avec composants, limites, fragilité et contraintes. Les PTV achètent le savoir-faire, jamais l’objet.\nConditions de résolution : Fiche permanente : composants, unique fonction, PA, portée, Puissance, durée, entretien et défaillance ; création en plusieurs heures/jours selon objet, jamais ressource ou autorisation MJ fabriquée par le Builder.","lore":"Certains assemblages finissent par devenir des pièces uniques de la Chasse, trop étranges pour entrer dans un catalogue. Chaque Prototype dépend de matériaux précis, d’un entretien capricieux et de limites que son créateur connaît souvent mieux que personne.","groupe_actuel":"Chasseurs indépendants — Héritages modulaires › Bricoleur de Vérité","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'humain', 'humain_chasseurs_independants_marque_par_la_proie', 'Marqué par la proie', NULL, '{"nature":"humain","forme":"une_porte","forme_lot":"1 porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"en-tête de Retour par le lien complété (réaction 1 PA)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'chasseurs_independants_heritages_modulaires_marque_par_la_proie_odeur_du_semblable', 'Odeur du semblable', NULL, '{"nature":"humain","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, 1 PA, 10 m","activation":"Une marque/famille à l’achat ; 1 PA sur cible à 10 m perçue, même signature fondamentale seulement, dissimulation adaptée opposable.","texte_court":"choisis à l''achat une marque réelle et sa famille. Tu reconnais la même signature fondamentale chez une cible perçue. Ni identité, ni clan, ni puissance ; une dissimulation adaptée s''y oppose.","texte_reference":"SR/R — 1 PA. Choisir une marque réelle issue d’une famille de créatures. Reconnaître la même signature surnaturelle fondamentale chez une autre cible directement perçue. Aucun renseignement automatique sur identité, clan, intentions ou puissance.\nConditions de résolution : Une marque/famille à l’achat ; 1 PA sur cible à 10 m perçue, même signature fondamentale seulement, dissimulation adaptée opposable.","lore":"Une marque laissée par une créature surnaturelle ne ressemble à aucune cicatrice ordinaire. Le Chasseur apprend à sentir la même famille de puissance chez d’autres êtres, reconnaissance intime qui n’offre ni nom, ni clan, ni certitude sur leurs intentions.","groupe_actuel":"Chasseurs indépendants — Héritages modulaires › Marqué par la proie","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'chasseurs_independants_heritages_modulaires_marque_par_la_proie_resonance_etrangere', 'Résonance étrangère', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, réaction 1 PA","activation":"Réaction 1 PA avant résistance contre cette famille, +3 circonstanciel non cumulable, révélation de résonance en cas d’échec.","texte_court":"quand un pouvoir de cette famille te vise, ta marque répond : +3 à la résistance (sans cumul). Si tu échoues quand même, la source sait que tu portes cette résonance.","texte_reference":"SR/R — Réaction 1 PA. Lorsqu’un pouvoir de cette famille cible directement le Chasseur, laisser volontairement sa marque répondre et bénéficier d’un +3 favorable à la résistance appropriée. Si le test échoue malgré cela, la source sait immédiatement que le personnage porte cette résonance.\nConditions de résolution : Réaction 1 PA avant résistance contre cette famille, +3 circonstanciel non cumulable, révélation de résonance en cas d’échec.","lore":"Quand la puissance qui l’a marqué revient vers lui, la cicatrice répond avant l’esprit. Le Chasseur peut s’appuyer sur cette résonance pour mieux résister, au risque de révéler immédiatement à la source qu’elle vient de toucher quelqu’un qui porte déjà son empreinte.","groupe_actuel":"Chasseurs indépendants — Héritages modulaires › Marqué par la proie","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'chasseurs_independants_heritages_modulaires_marque_par_la_proie_retour_par_le_lien', 'Retour par le lien', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R, réaction 1 PA, 1/scène","activation":"Réaction 1 PA, 1/scène lors de l’exploitation de la marque ; direction pour le round dans le même plan, aucune traversée d’un anti-lien adapté.","texte_court":"quand une créature de cette famille agit sur ta marque ou l''exploite, tu sens la direction de la source jusqu''à la fin du round, même plan. Un anti-lien adapté bloque.","texte_reference":"R — 1/Scène. Lorsqu’une créature de la famille correspondante agit directement sur la marque ou tente de l’exploiter, le Chasseur perçoit la direction générale de la source jusqu’à la fin du round, même si celle-ci était normalement imperceptible. Aucun GPS ni suivi prolongé.\nConditions de résolution : Réaction 1 PA, 1/scène lors de l’exploitation de la marque ; direction pour le round dans le même plan, aucune traversée d’un anti-lien adapté.","lore":"Retour par le lien est connu dans Marqué par la proie comme une expression rare mais reconnaissable de la Vérité : lorsqu’elle se manifeste, les témoins comprennent que le personnage ne se contente plus d’agir selon les possibilités ordinaires de son corps ou de son esprit.","groupe_actuel":"Chasseurs indépendants — Héritages modulaires › Marqué par la proie","statut_regle":"correction","changements":"en-tête de Retour par le lien complété (réaction 1 PA)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'chasseurs_independants_heritages_modulaires_marque_par_la_proie_retourner_la_cicatrice', 'Retourner la cicatrice', NULL, '{"nature":"humain","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, 1/scène, sans PA, après Résonance étrangère","activation":"Sans PA supplémentaire après résistance réussie, 1/scène, durée courte ; ni murs, ni Hologramme, ni autre famille annulés.","texte_court":"quand un pouvoir de cette famille échoue contre toi, jusqu''à la fin de ta prochaine activation la source ne peut plus se dissimuler à toi par un effet de cette famille. Ni murs, ni Hologramme, ni autre famille.","texte_reference":"R — 1/Scène — Prérequis : Résonance étrangère. Lorsqu’un pouvoir de la famille correspondante échoue à affecter le Chasseur, maintenir brièvement la connexion. Jusqu’à la fin de la prochaine activation du Chasseur, la source ne peut pas dissimuler sa présence à celui-ci par un effet provenant de cette même famille de pouvoirs. Ne contourne ni Hologramme, ni mur physique, ni technologie ou Magie d’une autre famille.\nConditions de résolution : Sans PA supplémentaire après résistance réussie, 1/scène, durée courte ; ni murs, ni Hologramme, ni autre famille annulés.","lore":"La technique enseigne à disparaître de l’attention avant de disparaître du regard. Dans Marqué par la proie, posture, rythme et pouvoir se combinent jusqu’à rendre l’approche surnaturellement difficile à suivre.","groupe_actuel":"Chasseurs indépendants — Héritages modulaires › Marqué par la proie","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'humain', 'humain_chasseurs_independants_obsession_d_une_seule_proie', 'Obsession d''une seule proie', NULL, '{"nature":"humain","forme":"une_porte","forme_lot":"1 porte (courte)","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"en-tête du Chemin jusqu''à toi complété (1 PA). Ressort déjà distinct des autres reconnaissances : une seule proie, choisie pour toujours."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'chasseurs_independants_heritages_modulaires_obsession_dune_seule_proie_je_te_retrouverai', 'Je te retrouverai', NULL, '{"nature":"humain","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, rituel de 10 minutes","activation":"10 minutes, trace authentique de la proie obsessionnelle enregistrée ; oui/non dans 10 km et même plan, pas de changement de proie libre par scène.","texte_court":"avec une trace authentique de ta proie obsessionnelle (sang, fragment, objet très lié), tu sais si elle est encore à 10 km au plus, même plan. Oui ou non.","texte_reference":"SR/R — Rituel. Avec une trace authentique de la proie obsessionnelle — sang, essence, fragment, objet extrêmement lié — savoir si cette proie est encore présente dans la même région générale. Réponse oui/non ; aucune localisation.\nConditions de résolution : 10 minutes, trace authentique de la proie obsessionnelle enregistrée ; oui/non dans 10 km et même plan, pas de changement de proie libre par scène.","lore":"L’obsession transforme une trace authentique en question adressée au monde : cette proie existe-t-elle encore quelque part dans la région ? La réponse reste pauvre mais suffisante pour distinguer la poursuite vivante du deuil ou de la fausse piste.","groupe_actuel":"Chasseurs indépendants — Héritages modulaires › Obsession d’une seule proie","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'chasseurs_independants_heritages_modulaires_obsession_dune_seule_proie_rien_ne_te_remplacera', 'Rien ne te remplacera', NULL, '{"nature":"humain","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, passif","activation":"Proie obsessionnelle directement perçue, identité seulement, aucun sens de détection supplémentaire.","texte_court":"tu reconnais ta proie obsessionnelle quand tu la perçois, malgré métamorphose, corps différent, possession ou déguisement. Une cible Voilée reste humaine ; tu sais seulement que c''est elle.","texte_reference":"SR/R — Passif. Reconnaître automatiquement la proie obsessionnelle lorsqu’elle est directement perçue malgré métamorphose, corps différent, possession ou déguisement surnaturel. Une cible V reste visuellement humaine ; le Chasseur sait simplement qu’il s’agit d’elle.\nConditions de résolution : Proie obsessionnelle directement perçue, identité seulement, aucun sens de détection supplémentaire.","lore":"Le Chasseur connaît sa proie au-delà du visage qu’elle porte. Métamorphose, possession ou changement de corps ne suffisent plus à lui présenter un substitut lorsqu’il rencontre réellement l’individu qu’il poursuit depuis si longtemps.","groupe_actuel":"Chasseurs indépendants — Héritages modulaires › Obsession d’une seule proie","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'chasseurs_independants_heritages_modulaires_obsession_dune_seule_proie_le_chemin_jusqua_toi', 'Le chemin jusqu''à toi', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, 1 PA, 1/scène","activation":"1 PA, 1/scène, trace réelle, proie à 10 km et même plan ; opposition à un effet anti-lien, direction seulement.","texte_court":"avec une trace authentique, une direction approximative vers ta proie si elle est à 10 km au plus, même plan. Un effet anti-lien s''y oppose.","texte_reference":"SR/R — 1/Scène. Avec une trace authentique et si la proie se trouve dans la même zone géographique générale, obtenir une direction approximative vers elle. Un effet explicitement conçu pour rompre ce type de lien peut s’y opposer.\nConditions de résolution : 1 PA, 1/scène, trace réelle, proie à 10 km et même plan ; opposition à un effet anti-lien, direction seulement.","lore":"Avec un fragment réellement lié à sa proie, l’obsédé ressent momentanément de quel côté continuer la chasse. Cette direction n’est ni carte ni distance ; seulement l’intuition surnaturelle que le bon chemin commence par là.","groupe_actuel":"Chasseurs indépendants — Héritages modulaires › Obsession d’une seule proie","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'chasseurs_independants_heritages_modulaires_obsession_dune_seule_proie_pas_cette_fois', 'Pas cette fois', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R, réaction 1 PA, 1/scène, après Fenêtre de chasse","activation":"Réaction 1 PA incluant Fenêtre de chasse, 1/scène ; détection du départ imperceptible de cette proie, aucune deuxième dépense ni attaque.","texte_court":"tu détectes le départ autrement imperceptible de ta proie obsessionnelle et utilises Fenêtre de chasse : une action simple, sans attaque ni seconde dépense. Aucune autre proie.","texte_reference":"Une fois par scène, vous détectez le départ autrement imperceptible de votre unique proie obsessionnelle et pouvez utiliser Fenêtre de chasse en réaction pour 1 PA. Ce PA comprend une action simple à votre portée normale, sans attaque ni deuxième dépense. Aucune autre proie n’est concernée.","lore":"À force d’avoir vu sa proie disparaître, le Chasseur reconnaît l’instant exact où la fuite commence, même lorsque le pouvoir n’offre normalement aucun avertissement. Il gagne le droit de réagir avant la rupture, pas celui d’annuler gratuitement ce qui arrive.","groupe_actuel":"Chasseurs indépendants — Héritages modulaires › Obsession d’une seule proie","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('couche', 'humain', 'humain_table_ronde', 'Table Ronde', NULL, '{"nature":"humain","chemin":["Table Ronde"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'humain', 'humain_table_ronde_resonance_de_merlin', 'Résonance de Merlin', NULL, '{"nature":"humain","forme":"une_porte","forme_lot":"1 porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"en-tête de Mémoire du fer complété (1 PA). Reconnaître l''héritage inchangé, voir question 5."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'table_ronde_lignees_et_armes_de_merlin_resonance_de_merlin_appel_de_larme', 'Appel de l''arme', NULL, '{"nature":"humain","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, 1 PA","activation":"1 PA, arme à 20 m, trajet praticable vers la main ; ni matière pleine ordinaire, ni contenant fermé, ni sceau traversés ; aucun désarmement automatique d’un porteur hostile.","texte_court":"ton arme à 20 m au plus rejoint ta main par le trajet le plus direct. Ni matière pleine, ni contenant fermé, ni sceau ; elle n''est pas arrachée à un porteur hostile.","texte_reference":"SR/R — 1 PA. Si l’arme se trouve relativement proche et qu’aucune barrière surnaturelle ne les sépare, elle rejoint la main de son héritier par le moyen surnaturel le plus direct possible. Elle ne traverse ni dimension, ni scellement, ni contenant mystiquement fermé, ni distance déraisonnable.\nConditions de résolution : 1 PA, arme à 20 m, trajet praticable vers la main ; ni matière pleine ordinaire, ni contenant fermé, ni sceau traversés ; aucun désarmement automatique d’un porteur hostile.","lore":"À courte distance, l’Arme connaît la main à laquelle elle appartient. Si rien de surnaturel ne verrouille réellement leur séparation, elle rejoint son héritier par le chemin impossible mais direct que la Résonance lui ouvre.","groupe_actuel":"Table Ronde — lignées et armes de Merlin › Résonance de Merlin","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'table_ronde_lignees_et_armes_de_merlin_resonance_de_merlin_reconnaitre_lheritage', 'Reconnaître l''héritage', NULL, '{"nature":"humain","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, passif","activation":"1 PTV mais différencier : au contact, reconnaître l’authenticité ET la lignée historique de l’arme ; aucune identité ou localisation de son héritier actuel.","texte_court":"au contact d''une arme de Merlin, tu reconnais son authenticité et sa lignée. Ni l''identité ni la position de son héritier actuel.","texte_reference":"Au contact d’une arme de Merlin, reconnaissez son authenticité et sa lignée historique. Cette lecture ne révèle ni l’identité ni la localisation de son héritier actuel.","lore":"Au contact d’une autre Arme authentique, le porteur sait qu’elle appartient au même héritage de Merlin. S’il connaît déjà sa lignée, la manière particulière dont les deux armes se répondent suffit aussi à la reconnaître.","groupe_actuel":"Table Ronde — lignées et armes de Merlin › Résonance de Merlin","statut_regle":"correction","changements":"en-tête de Mémoire du fer complété (1 PA). Reconnaître l''héritage inchangé, voir question 5."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'table_ronde_lignees_et_armes_de_merlin_resonance_de_merlin_memoire_du_fer', 'Mémoire du fer', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, 1 PA, 1/scène, arme tenue","activation":"1 PA, 1/scène, arme tenue et stimulus réel ; un fragment authentique seulement.","texte_court":"face à un lieu, une personne, une créature ou un objet qu''un ancien héritier a rencontré avec elle, un bref souvenir authentique (image, parole, émotion, fragment de combat). Aucune Compétence transmise.","texte_reference":"SR/R — 1/Scène. L’arme conserve des rémanences de ce qu’elle a réellement vécu avec ses porteurs précédents. Face à un lieu, une personne, une créature, un symbole ou un objet qu’un ancien héritier a réellement rencontré avec elle, provoquer un bref souvenir : image, sensation, parole, émotion ou fragment de combat. Aucun téléchargement de Compétence.\nConditions de résolution : 1 PA, 1/scène, arme tenue et stimulus réel ; un fragment authentique seulement.","lore":"Le métal se souvient parfois de ce qu’il a réellement vécu avec d’autres porteurs. Un lieu, un symbole ou un ennemi déjà rencontré peut réveiller une image, une sensation ou quelques paroles, fragments historiques plutôt qu’apprentissage téléchargé.","groupe_actuel":"Table Ronde — lignées et armes de Merlin › Résonance de Merlin","statut_regle":"correction","changements":"en-tête de Mémoire du fer complété (1 PA). Reconnaître l''héritage inchangé, voir question 5."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'table_ronde_lignees_et_armes_de_merlin_resonance_de_merlin_lien_indissociable', 'Lien indissociable', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, passif","activation":"Opposition du porteur contre vol du lien, jamais contre vol ordinaire ou destruction physique de l’arme.","texte_court":"toute tentative surnaturelle de voler le lien, d''asservir l''arme ou de lui faire accepter un faux héritier doit vaincre ton V + MS. Le vol ordinaire reste possible : il protège le lien, pas les poches.","texte_reference":"SR/R — Passif. Une tentative surnaturelle visant spécifiquement à voler le lien, asservir l’arme, rompre sa reconnaissance ou lui faire accepter un faux héritier doit vaincre Volonté + Maîtrise spirituelle du porteur. Le vol physique ordinaire reste possible ; le Talent protège le lien, pas les poches.\nConditions de résolution : Opposition du porteur contre vol du lien, jamais contre vol ordinaire ou destruction physique de l’arme.","lore":"La Résonance de Merlin protège d’abord la reconnaissance mutuelle entre Lame et lignée. On peut voler physiquement l’arme, mais lui imposer un faux héritier ou arracher le lien demande de vaincre quelque chose de beaucoup plus ancien qu’une serrure.","groupe_actuel":"Table Ronde — lignées et armes de Merlin › Résonance de Merlin","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'table_ronde_lignees_et_armes_de_merlin_resonance_de_merlin_resonance_parfaite', 'Résonance parfaite', NULL, '{"nature":"humain","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, 1 PA, 1/scène, au moins deux Formes connues","activation":"1 PA, 1/scène ; exige au moins deux Formes connues, rappel gratuit seulement avec Appel de l’arme ; aucune nouvelle Forme ou attaque offerte.","texte_court":"pour la scène, changer de Forme est gratuit une fois par round, un Appel de l''arme est gratuit une fois, et une Forme peut apparaître pendant une réaction qui utilise l''arme. Aucun PA ni attaque créés.","texte_reference":"R — 1 PA — 1/Scène. Pour la scène, l’arme et son héritier fonctionnent comme une seule extension. Le changement entre ses formes connues devient gratuit 1/round ; l’arme peut être rappelée gratuitement une fois pendant la scène ; une forme peut apparaître directement au cours d’une Réaction utilisant l’arme. Aucun PA supplémentaire n’est créé.\nConditions de résolution : 1 PA, 1/scène ; exige au moins deux Formes connues, rappel gratuit seulement avec Appel de l’arme ; aucune nouvelle Forme ou attaque offerte.","lore":"Pendant une scène, l’arme et son héritier cessent presque d’avoir des temps séparés. Formes et rappel répondent avec une fluidité instinctive jusque dans la réaction, sans jamais créer une action ou une réserve de PA supplémentaire.","groupe_actuel":"Table Ronde — lignées et armes de Merlin › Résonance de Merlin","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'humain', 'humain_table_ronde_formes_de_la_lame', 'Formes de la Lame', NULL, '{"nature":"humain","forme":"une_porte","forme_lot":"1 porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"Forme du Chevalier n''est plus « définie avec le MJ » : les trois profils fermés de ses conditions deviennent le seul choix. Forme de Rupture garde Vigueur + Mêlée, alors que ses équivalents d''autres traditions utilisent V + MS : c''est son ressort propre (la lame du chevalier, pas la prière). Signalé, non corrigé."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'table_ronde_lignees_et_armes_de_merlin_formes_de_la_lame_forme_de_garde', 'Forme de Garde', NULL, '{"nature":"humain","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"R, passif","activation":"Défense active normale de Mêlée pour 1 PA, arme en main et attaque physique/énergétique perçue, pas de défense contre possession ou pensée.","texte_court":"ton arme peut parer, pour le PA normal de la Défense active de Mêlée, une attaque surnaturelle physique ou énergétique qu''une arme ordinaire ne parerait pas. Pas contre une possession ou une pensée.","texte_reference":"R — Passif. L’arme peut adopter une de ses formes défensives et servir à effectuer une Défense active contre une attaque surnaturelle physique ou énergétique qu’une arme ordinaire ne pourrait pas réellement parer. La Défense active coûte toujours son PA normal.\nConditions de résolution : Défense active normale de Mêlée pour 1 PA, arme en main et attaque physique/énergétique perçue, pas de défense contre possession ou pensée.","lore":"La Forme de Garde transforme l’arme héritée en véritable instrument de parade contre l’énergie ou la violence surnaturelle. Le chevalier doit toujours défendre activement ; la Lame lui donne seulement quelque chose de valable à interposer.","groupe_actuel":"Table Ronde — lignées et armes de Merlin › Formes de la Lame","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'table_ronde_lignees_et_armes_de_merlin_formes_de_la_lame_forme_de_chasse', 'Forme de Chasse', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R, passif","activation":"Attaque normalement payée, cible spirituelle accessible, pas de DGT ajoutés.","texte_court":"une forme adaptée frappe un esprit manifesté ou une créature partiellement immatérielle accessible au contact. Ni cible absente, ni autre plan ; aucun dégât en plus.","texte_reference":"R — Passif. Une forme adaptée peut interagir directement avec un esprit manifesté, une créature partiellement immatérielle ou une manifestation surnaturelle réellement accessible au contact. Elle ne frappe ni une cible absente ni une entité située sur un autre plan inaccessible.\nConditions de résolution : Attaque normalement payée, cible spirituelle accessible, pas de DGT ajoutés.","lore":"Une Arme de Merlin peut adopter une forme dont la géométrie touche aussi le surnaturel manifesté. L’esprit ou la créature en phase reste hors de portée s’il est réellement absent, mais l’immatériel présent cesse d’être intouchable par principe.","groupe_actuel":"Table Ronde — lignées et armes de Merlin › Formes de la Lame","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'table_ronde_lignees_et_armes_de_merlin_formes_de_la_lame_forme_dentrave', 'Forme d''Entrave', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R, passif","activation":"Attaque payée, DR 2+ et Altération disponible, remplacement par verrou corporel bref ; pas de portail extérieur bloqué.","texte_court":"sur une attaque réussie à DR 2+, renonce à une Altération pour empêcher, jusqu''à la fin de la prochaine activation de la cible, un déplacement surnaturel qui passe par le corps touché (phase, dissolution, transformation de fuite, déplacement spectral). Pas un portail extérieur.","texte_reference":"R — Passif. Sur une attaque réussie avec DR 2+, renoncer à une Altération offensive pour empêcher jusqu’à la fin de la prochaine activation de la cible un déplacement surnaturel utilisant directement le corps touché : phase, dissolution corporelle, transformation de fuite, déplacement spectral ou équivalent. Ne bloque pas un portail extérieur ou un transport dont le corps n’est pas le vecteur.\nConditions de résolution : Attaque payée, DR 2+ et Altération disponible, remplacement par verrou corporel bref ; pas de portail extérieur bloqué.","lore":"La Lame peut laisser dans un corps touché une entrave accordée à son déplacement surnaturel. Phase, dissolution ou mouvement spectral devient momentanément difficile, mais un portail extérieur ou un autre vecteur de transport reste une autre affaire.","groupe_actuel":"Table Ronde — lignées et armes de Merlin › Formes de la Lame","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'table_ronde_lignees_et_armes_de_merlin_formes_de_la_lame_forme_de_rupture', 'Forme de Rupture', NULL, '{"nature":"humain","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, 1 PA au contact, 1/scène","activation":"1 PA au contact, 1/scène, Vigueur + Mêlée contre Puissance de la structure ciblable ; suspension d’un seul effet actif, aucun dégât ajouté.","texte_court":"une barrière, un lien, un enchantement ou un ancrage que tu perçois comme cible distincte : attaque-le, Vigueur + Mêlée contre sa Puissance. Réussite : suspendu jusqu''à la fin de la prochaine activation de sa source. Jamais une Nature, un Mageius ou un passif fondamental.","texte_reference":"R — 1/Scène. Lorsque l’héritier perçoit une barrière, un lien, une manifestation, un enchantement ou un ancrage comme une cible distincte, il peut l’attaquer avec l’arme. Résoudre l’opposition contre la Puissance de l’effet. En réussite, l’effet est suspendu jusqu’à la fin de la prochaine activation de sa source. Ne vise jamais une Nature, un Mageius ou une propriété fondamentale purement passive.\nConditions de résolution : 1 PA au contact, 1/scène, Vigueur + Mêlée contre Puissance de la structure ciblable ; suspension d’un seul effet actif, aucun dégât ajouté.","lore":"Lorsque le chevalier sait distinguer une barrière, un enchantement ou un ancrage comme cible propre, sa Lame peut frapper la structure métaphysique elle-même et la faire céder brièvement sans mutiler la Nature qui l’a créée.","groupe_actuel":"Table Ronde — lignées et armes de Merlin › Formes de la Lame","statut_regle":"correction","changements":"Forme du Chevalier n''est plus « définie avec le MJ » : les trois profils fermés de ses conditions deviennent le seul choix. Forme de Rupture garde Vigueur + Mêlée, alors que ses équivalents d''autres traditions utilisent V + MS : c''est son ressort propre (la lame du chevalier, pas la prière). Signalé, non corrigé."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'table_ronde_lignees_et_armes_de_merlin_formes_de_la_lame_forme_du_chevalier', 'Forme du Chevalier', NULL, '{"nature":"humain","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, 1/scène","activation":"Voir la résolution détaillée","texte_court":"la fonction parfaite de ton arme, choisie une fois pour toutes parmi trois profils : interception (réaction 1 PA) ; ouverture d''un seuil (2 PA, sur opposition) ; verrou d''une fuite précise (1 PA, sur opposition). Portée 10 m ou contact selon le profil. Jamais un bonus de dégâts.","texte_reference":"R — 1/Scène. Chaque arme possède une fonction parfaite correspondant réellement à son chevalier historique. Cette capacité de niveau 3 PTV est définie individuellement avec le MJ : interception exceptionnelle, interaction avec un type de seuil, verrouillage d’une fuite particulière, capacité liée à un adversaire historique ou autre signature authentique. Jamais un simple gros bonus générique de DGT.\nConditions de résolution : Choix permanent parmi profils : interception réaction 1 PA ; ouverture de seuil 2 PA sur opposition ; verrou de fuite 1 PA sur opposition ; 1/scène, portée 10 m ou contact selon profil.","lore":"Chaque arme se souvient du chevalier auquel elle appartenait et d’une fonction qui lui était propre. Cette Forme parfaite est une signature historique définie autour de cette lignée, jamais une simple augmentation générique de violence.","groupe_actuel":"Table Ronde — lignées et armes de Merlin › Formes de la Lame","statut_regle":"correction","changements":"Forme du Chevalier n''est plus « définie avec le MJ » : les trois profils fermés de ses conditions deviennent le seul choix. Forme de Rupture garde Vigueur + Mêlée, alors que ses équivalents d''autres traditions utilisent V + MS : c''est son ressort propre (la lame du chevalier, pas la prière). Signalé, non corrigé."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'humain', 'humain_table_ronde_heritage_chevaleresque', 'Héritage chevaleresque', NULL, '{"nature":"humain","forme":"une_porte","forme_lot":"1 porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"en-têtes complétés pour Écho de la lignée, Écho ancestral (1 PA) et Quête inachevée (réaction 1 PA)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'table_ronde_lignees_et_armes_de_merlin_heritage_chevaleresque_serment_de_quete', 'Serment de Quête', NULL, '{"nature":"humain","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, rituel de 10 minutes","activation":"Voir la résolution détaillée","texte_court":"un objectif concret et un critère de fin, une seule Quête active. Tu sais toujours si elle reste réalisable ou est devenue impossible ; pas comment l''accomplir.","texte_reference":"SR/R — Rituel. Prononcer un Serment portant sur un objectif concret : protéger quelqu’un, retrouver quelque chose, abattre une proie, empêcher un événement ou accomplir une tâche clairement définie. Une seule Quête active. Le porteur sait toujours si son Serment reste objectivement réalisable ou est devenu impossible ; il ne sait pas comment l’accomplir.\nConditions de résolution : 10 minutes, un objectif et critère de fin écrits ; seulement possible/impossible, aucune cause, distance ou solution ; changement de quête exige un nouvel engagement fictionnel réel.","lore":"Le chevalier nomme devant l’arme un objectif concret et en fait sa Quête unique. Dès lors, il sait si ce but reste réellement possible, mais la lignée ne lui souffle jamais le chemin permettant de l’accomplir.","groupe_actuel":"Table Ronde — lignées et armes de Merlin › Héritage chevaleresque","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'table_ronde_lignees_et_armes_de_merlin_heritage_chevaleresque_echo_de_la_lignee', 'Écho de la lignée', NULL, '{"nature":"humain","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, 1 PA, 1/scène, arme tenue","activation":"1 PA, 1/scène, arme tenue ; vie et même plan, direction seulement dans 10 km ; sceaux anti-lien respectés, aucune lecture de santé.","texte_court":"pour un membre de ta lignée déjà reconnu par l''arme : vivant ou non, même plan ou non, et sa direction s''il est à 10 km au plus. Un anti-lien bloque.","texte_reference":"SR/R — 1/Scène. En tenant l’arme, se concentrer sur un membre de sa lignée déjà reconnu par elle. Savoir s’il est encore vivant, s’il se trouve sur le même plan d’existence et, s’il est dans la même région générale, percevoir sa direction approximative. Aucun état de santé, pensée ou localisation précise ; un scellement ou effet anti-lien approprié peut bloquer l’Écho.\nConditions de résolution : 1 PA, 1/scène, arme tenue ; vie et même plan, direction seulement dans 10 km ; sceaux anti-lien respectés, aucune lecture de santé.","lore":"L’arme reconnaît ceux de la lignée qu’elle a déjà reconnus. En se concentrant sur l’un d’eux, le porteur ressent s’il vit encore et, s’il n’est pas trop loin sur le même plan, dans quelle direction générale se trouve cette résonance.","groupe_actuel":"Table Ronde — lignées et armes de Merlin › Héritage chevaleresque","statut_regle":"correction","changements":"en-têtes complétés pour Écho de la lignée, Écho ancestral (1 PA) et Quête inachevée (réaction 1 PA)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'table_ronde_lignees_et_armes_de_merlin_heritage_chevaleresque_echo_ancestral', 'Écho ancestral', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, 1 PA, 1/scène, arme tenue","activation":"1 PA, 1/scène, arme tenue ; un enseignement réellement vécu de l’ancêtre, pas d’invention rétroactive d’un talent ou d’une solution garantie.","texte_court":"dans une situation analogue à ce qu''a vécu ton ancêtre chevalier avec cette arme, tu reçois ce qu''il a compris trop tard, réussi ou raté. Une possibilité, jamais une réussite.","texte_reference":"SR/R — 1/Scène. Lorsque le personnage agit dans une situation fondamentalement analogue à un événement réellement vécu par son ancêtre chevalier avec cette arme, la résonance lui transmet ce que l’ancêtre avait compris trop tard, réussi ou raté dans cette situation. Cela peut révéler une possibilité qu’une déduction normale n’aurait pas ouverte, mais n’accorde aucune réussite automatique.\nConditions de résolution : 1 PA, 1/scène, arme tenue ; un enseignement réellement vécu de l’ancêtre, pas d’invention rétroactive d’un talent ou d’une solution garantie.","lore":"Une situation peut réveiller dans l’arme le souvenir d’un ancêtre qui a vécu quelque chose de fondamentalement similaire. L’héritier reçoit l’enseignement que ce chevalier avait gagné — souvent trop tard — sans recevoir son succès à sa place.","groupe_actuel":"Table Ronde — lignées et armes de Merlin › Héritage chevaleresque","statut_regle":"correction","changements":"en-têtes complétés pour Écho de la lignée, Écho ancestral (1 PA) et Quête inachevée (réaction 1 PA)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'table_ronde_lignees_et_armes_de_merlin_heritage_chevaleresque_aucun_enchantement_ne_detourne', 'Aucun enchantement ne détourne', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, passif, après Serment de Quête","activation":"Prérequis Serment de Quête, +3 non cumulable contre trahison surnaturelle directe du serment, aucune immunité ou relance ajoutée.","texte_court":"tant que ta Quête est valable, +3 (sans cumul) aux résistances contre une influence surnaturelle qui te contraindrait à la trahir. Ni immunité ni relance.","texte_reference":"Tant que votre Serment de Quête est valable, gagnez +3, non cumulable avec un bonus équivalent, aux résistances contre une influence surnaturelle qui vous contraindrait directement à le trahir. Aucune immunité ni relance supplémentaire n’est accordée.","lore":"La Quête donne au chevalier une direction qu’une magie de domination doit réellement arracher. Un enchantement qui l’obligerait à trahir son serment, son protégé ou son devoir rencontre une volonté renforcée par la lignée et l’arme.","groupe_actuel":"Table Ronde — lignées et armes de Merlin › Héritage chevaleresque","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'table_ronde_lignees_et_armes_de_merlin_heritage_chevaleresque_quete_inachevee', 'Quête inachevée', NULL, '{"nature":"humain","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, réaction 1 PA, 1/scénario, après Serment de Quête","activation":"Réaction 1 PA, 1/scénario, quête encore possible ; jusqu’à fin de prochaine activation sans restaurer PV ou PA, un seul sauvetage surnaturel par conséquence.","texte_court":"quand un effet devrait te tuer alors que ta Quête reste réalisable, l''arme te maintient jusqu''à la fin de ta prochaine activation. Aucun PV rendu ; sans stabilisation avant, la mort suit.","texte_reference":"R — Réaction — 1/Scénario — Prérequis : Serment de Quête. Lorsqu’un effet devrait tuer le porteur alors que sa Quête reste objectivement réalisable, l’arme maintient la résonance de la lignée jusqu’à la fin de sa prochaine activation. Le personnage ne récupère aucun PV. S’il n’est pas sauvé ou Stabilisé avant l’expiration, la Mort s’applique normalement.\nConditions de résolution : Réaction 1 PA, 1/scénario, quête encore possible ; jusqu’à fin de prochaine activation sans restaurer PV ou PA, un seul sauvetage surnaturel par conséquence.","lore":"Tant qu’une Quête reste encore accomplissable, l’arme peut retenir la résonance de son héritier au bord de la mort. Ce sursis ne soigne rien : il donne seulement à d’autres le temps de sauver celui dont le devoir n’est pas encore achevé.","groupe_actuel":"Table Ronde — lignées et armes de Merlin › Héritage chevaleresque","statut_regle":"correction","changements":"en-têtes complétés pour Écho de la lignée, Écho ancestral (1 PA) et Quête inachevée (réaction 1 PA)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'humain', 'humain_table_ronde_la_table', 'La Table', NULL, '{"nature":"humain","forme":"une_porte","forme_lot":"1 porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"aucun. Les armes se reconnaissent inchangé, voir question 5."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'table_ronde_lignees_et_armes_de_merlin_la_table_les_armes_se_reconnaissent', 'Les armes se reconnaissent', NULL, '{"nature":"humain","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, passif, 20 m","activation":"Une arme de Merlin perçue à 20 m, présence d’un autre héritier, lignée seulement si déjà connue ; aucune preuve d’authenticité détaillée.","texte_court":"quand une autre véritable arme de Merlin est à portée de perception, tu sais qu''un autre héritier de la Table est là ; sa lignée seulement si elle t''est familière.","texte_reference":"SR/R — Passif. La résonance entre armes est naturelle ; le Talent permet au porteur d’en comprendre le sens sans contact direct lorsqu’une autre véritable arme de Merlin se trouve à portée de perception. Il sait qu’un autre héritier de la Table est présent. L’identité exacte n’est connue que si la lignée est déjà familière.\nConditions de résolution : Une arme de Merlin perçue à 20 m, présence d’un autre héritier, lignée seulement si déjà connue ; aucune preuve d’authenticité détaillée.","lore":"Une véritable Arme de Merlin ne reste pas parfaitement anonyme auprès d’une autre. La résonance dit qu’un héritier de la Table se tient à portée ; seule une lignée déjà connue donne un visage plus précis à ce salut silencieux.","groupe_actuel":"Table Ronde — lignées et armes de Merlin › La Table","statut_regle":"correction","changements":"aucun. Les armes se reconnaissent inchangé, voir question 5."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'table_ronde_lignees_et_armes_de_merlin_la_table_appel_de_la_table', 'Appel de la Table', NULL, '{"nature":"humain","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, 1 PA","activation":"1 PA, rayon 10 km, même plan ; une impulsion parmi danger/rassemblement/poursuite/aide et direction, pas de conversation ni localisation exacte.","texte_court":"une impulsion simple aux autres armes de Merlin à 10 km au plus, même plan : danger, rassemblement, poursuite ou aide, avec une direction. Pas une conversation ; un scellement spirituel la coupe.","texte_reference":"SR/R — 1 PA. Envoyer par l’arme une impulsion simple aux autres armes de Merlin de la même région : danger, rassemblement, poursuite ou aide, accompagnée d’une direction générale. Ce n’est pas une conversation télépathique et un scellement spirituel approprié peut couper l’Appel.\nConditions de résolution : 1 PA, rayon 10 km, même plan ; une impulsion parmi danger/rassemblement/poursuite/aide et direction, pas de conversation ni localisation exacte.","lore":"L’Appel fait vibrer les autres Armes de Merlin de la région avec une intention très simple : danger, rassemblement, chasse ou secours. La direction accompagne le signal comme une orientation héraldique, pas comme une conversation entre les héritiers.","groupe_actuel":"Table Ronde — lignées et armes de Merlin › La Table","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'table_ronde_lignees_et_armes_de_merlin_la_table_resonance_croisee', 'Résonance croisée', NULL, '{"nature":"humain","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, réaction 1 PA, 10 m","activation":"Réaction 1 PA, autre porteur à 10 m, +2 à sa Défense active pertinente ; une seule Assistance effective.","texte_court":"quand un autre chevalier fait une Défense active contre un phénomène surnaturel, ton arme résonne avec la sienne : Assistance +2, même en combat. Une seule Assistance.","texte_reference":"SR/R — Réaction 1 PA. Lorsqu’un autre chevalier proche effectue une Défense active contre un phénomène surnaturel, le porteur peut faire résonner son arme avec la sienne et fournir Assistance +2, même en combat, si l’intervention est réellement pertinente.\nConditions de résolution : Réaction 1 PA, autre porteur à 10 m, +2 à sa Défense active pertinente ; une seule Assistance effective.","lore":"Une défense surnaturelle accomplie par un chevalier peut être soutenue par la résonance d’une autre Arme de Merlin. Le second porteur fait vibrer sa Lame en accord avec la première et ajoute son propre héritage à l’effort défensif.","groupe_actuel":"Table Ronde — lignées et armes de Merlin › La Table","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'table_ronde_lignees_et_armes_de_merlin_la_table_formes_complementaires', 'Formes complémentaires', NULL, '{"nature":"humain","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, passif, 1/round","activation":"1/round, la première Forme maintient son ouverture jusqu’à la seconde action du partenaire avant fin du round, même si elle aurait expiré ; aucun jet/PA offert.","texte_court":"quand deux porteurs coordonnent deux actions payées, l''ouverture réellement créée par la première Forme tient jusqu''à l''action du partenaire avant la fin du round. Le partenaire doit avoir une Forme et un vecteur compatibles ; rien n''est offert.","texte_reference":"Une fois par round, lorsque deux porteurs coordonnent deux actions normalement payées, la première Forme maintient l’ouverture qu’elle a réellement créée jusqu’à la seconde action du partenaire avant la fin du round, même si cette ouverture aurait expiré. Le partenaire doit disposer d’une Forme et d’un vecteur compatibles ; aucun jet, PA ou effet nouveau n’est offert.","lore":"Les Armes de la Table savent exploiter ce qu’une sœur vient réellement d’ouvrir. Une Forme qui rend un ancrage, une barrière ou une présence accessible permet à une seconde Forme de travailler immédiatement sur cette même ouverture.","groupe_actuel":"Table Ronde — lignées et armes de Merlin › La Table","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'humain', 'table_ronde_lignees_et_armes_de_merlin_la_table_reformer_la_table', 'Reformer la Table', NULL, '{"nature":"humain","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, 1 PA par héritier, au moins 3, 1/scène, 20 m","activation":"Trois héritiers à 20 m, chacun 1 PA, 1/scène ; effets tant qu’ils restent conscients dans ce rayon, une Puissance collective fixée, Appel gratuit 1/round pour le groupe entier.","texte_court":"tant que trois restent conscients dans la zone : chaque arme connaît la position des autres ; une falsification qui veut les isoler doit vaincre le meilleur V + MS du groupe ; aucune arme ne peut être arrachée à sa lignée ; Appel de la Table est gratuit une fois par round dans le groupe.","texte_reference":"R — Rituel collectif — 1/Scène — au moins 3 héritiers. Chaque héritier consacre 1 PA. Pour la scène, tant qu’au moins trois restent conscients et dans la zone : chaque arme connaît la position générale des autres ; une falsification surnaturelle de perception visant à les isoler les uns des autres doit vaincre la meilleure Volonté + Maîtrise spirituelle parmi eux ; une arme ne peut être surnaturellement arrachée à sa lignée ; Appel de la Table peut être employé gratuitement 1/round à l’intérieur du groupe.\nConditions de résolution : Trois héritiers à 20 m, chacun 1 PA, 1/scène ; effets tant qu’ils restent conscients dans ce rayon, une Puissance collective fixée, Appel gratuit 1/round pour le groupe entier.","lore":"Lorsque trois héritiers ou davantage se réunissent réellement, la Table cesse d’être seulement un souvenir. Leurs Armes composent un réseau de présence mutuelle qui résiste aux falsifications destinées à les isoler et renforce le lien entre chaque lignée et sa Lame.","groupe_actuel":"Table Ronde — lignées et armes de Merlin › La Table","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
